// Class 7 Science Preloaded Chapter Data for offline/file:// protocol fallback
window.CHAPTER_DATA = {"1":"<section class=\"chapter-section\" id=\"ch1\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">1</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 1: Nutrition in Plants</h2>\n      <p>NCERT Exercise Solutions — Complete Step-by-Step Answers with CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Scientific Concepts &amp; Chemical Equations</div>\n    <ul class=\"concept-list\">\n      <li><strong>Modes of Nutrition:</strong>\n        <ul>\n          <li><em>Autotrophic Nutrition:</em> Organisms synthesise their own food from simple inorganic raw materials (CO₂, H₂O, minerals) using sunlight and chlorophyll. E.g., all green plants and blue-green algae.</li>\n          <li><em>Heterotrophic Nutrition:</em> Organisms depend directly or indirectly on autotrophs for food. E.g., animals, non-green plants, fungi.</li>\n        </ul>\n      </li>\n      <li><strong>Photosynthesis:</strong>\n        The biochemical process by which green leaves prepare food using chlorophyll, sunlight, carbon dioxide, and water:\n        <br>\n        <span class=\"math\">Carbon dioxide (6CO₂) + Water (6H₂O) ⎯⎯⎯[Sunlight / Chlorophyll]⎯⎯→ Glucose (C₆H₁₂O₆) + Oxygen (6O₂)</span>\n      </li>\n      <li><strong>Specialised Modes of Nutrition in Plants:</strong>\n        <ul>\n          <li><em>Parasitic Plants:</em> Non-green plants that obtain readymade food from a host plant using specialised absorbing roots (haustoria). E.g., <em>Cuscuta</em> (Amarbel).</li>\n          <li><em>Insectivorous Plants:</em> Partially autotrophic plants growing in nitrogen-deficient bogs that trap and digest insects to obtain nitrogenous compounds. E.g., Pitcher plant (<em>Nepenthes</em>), Venus flytrap.</li>\n          <li><em>Saprotrophic Nutrition:</em> Organisms secrete digestive juices onto dead and decaying matter and absorb dissolved nutrients. E.g., Fungi, Mushrooms, bread mould (<em>Rhizopus</em>).</li>\n          <li><em>Symbiosis:</em> Mutually beneficial association between two organisms sharing shelter and nutrients. E.g., Lichens (Alga + Fungus), <em>Rhizobium</em> bacteria in root nodules of leguminous plants.</li>\n        </ul>\n      </li>\n      <li><strong>Stomata:</strong> Tiny microscopic pores present predominantly on the underside of leaves, flanked by kidney-shaped guard cells, responsible for gaseous exchange (CO₂ and O₂) and transpiration.</li>\n    </ul>\n  </div>\n\n  <div class=\"ex-div\">NCERT Textbook Exercise Questions</div>\n\n  <!-- Q1 -->\n  <div class=\"q-card\" id=\"q1_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Why do organisms take food?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>All living organisms require food for the following essential life functions:</p>\n          <div class=\"step\">\n            <strong>1. Energy Provision:</strong> Food acts as fuel, releasing energy through cellular respiration to perform all vital life activities (locomotion, digestion, circulation, reproduction).\n          </div>\n          <div class=\"step\">\n            <strong>2. Growth and Development:</strong> Nutrients in food (proteins, minerals) provide building materials for cellular division, tissue formation, and body growth.\n          </div>\n          <div class=\"step\">\n            <strong>3. Repair and Maintenance:</strong> Damaged body tissues, worn-out cells, and injured organs require nutrients for cellular repair and regeneration.\n          </div>\n          <div class=\"step\">\n            <strong>4. Protection Against Diseases:</strong> Vitamins and minerals strengthen the immune system and protect the body from infections.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mentioning energy for vital biological activities</span><span class=\"marking-marks\">½ Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mentioning body growth and cell division</span><span class=\"marking-marks\">½ Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mentioning repair of worn-out tissues</span><span class=\"marking-marks\">½ Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mentioning protection against infections/diseases</span><span class=\"marking-marks\">½ Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q2 -->\n  <div class=\"q-card\" id=\"q1_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Distinguish between a parasite and a saprotroph.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr>\n                <th>Feature</th>\n                <th>Parasite</th>\n                <th>Saprotroph</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td><strong>Source of Food</strong></td>\n                <td>Derives nutrients directly from the living body of another organism called the <strong>host</strong>.</td>\n                <td>Absorbs nutrients in solution form from <strong>dead and decaying</strong> organic matter.</td>\n              </tr>\n              <tr>\n                <td><strong>Host Impact</strong></td>\n                <td>Harms the host by depriving it of valuable nutrients and sometimes causes diseases.</td>\n                <td>Does not harm living organisms; acts as a natural cleaner/decomposer.</td>\n              </tr>\n              <tr>\n                <td><strong>Digestive Mechanism</strong></td>\n                <td>Absorbs already digested or synthesised food via specialised sucking roots (haustoria).</td>\n                <td>Secretes extracellular digestive juices onto dead matter and absorbs the liquified solution.</td>\n              </tr>\n              <tr>\n                <td><strong>Examples</strong></td>\n                <td><em>Cuscuta</em> (Amarbel), tapeworm, mistletoe.</td>\n                <td>Fungi, mushrooms, yeast, bread mould (<em>Rhizopus</em>).</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Difference in source of nutrition (living host vs dead matter)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Difference in mode of digestion/host impact</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct examples for both categories</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q3 -->\n  <div class=\"q-card\" id=\"q1_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">How would you test the presence of starch in leaves?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>The presence of starch in green leaves is tested using the <strong>Iodine Test</strong> following a standard laboratory procedure:</p>\n          <div class=\"step\">\n            <strong>Step 1 (Killing the cells):</strong> Pluck a green leaf from a healthy plant exposed to sunlight for a few hours. Boil the leaf in a beaker of water for 3 to 5 minutes to break down cell membranes and make it permeable.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2 (Decolourisation):</strong> Place the boiled leaf in a test tube containing alcohol (ethanol). Place this test tube inside a water bath (beaker filled with boiling water) and heat gently until all the green pigment (chlorophyll) dissolves out into the alcohol and the leaf turns pale white/colourless.<br>\n            <em>Caution: Alcohol is highly flammable; never heat it directly over a flame!</em>\n          </div>\n          <div class=\"step\">\n            <strong>Step 3 (Washing &amp; Softening):</strong> Remove the brittle bleached leaf and rinse it gently in warm water to soften it and remove trace alcohol.\n          </div>\n          <div class=\"step\">\n            <strong>Step 4 (Iodine Addition):</strong> Spread the decolourised leaf flat on a white ceramic tile and add a few drops of dilute iodine solution onto its surface.\n          </div>\n          <div class=\"step\">\n            <strong>Observation &amp; Conclusion:</strong> The leaf turns <strong>blue-black</strong> in colour. This confirms the presence of starch, proving that photosynthesis has taken place.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Boiling in water + alcohol decolourisation in water bath</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Application of iodine solution on bleached leaf</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Blue-black colour observation and valid starch conclusion</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q4 -->\n  <div class=\"q-card\" id=\"q1_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Give a brief description of the process of synthesis of food in green plants.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Green plants synthesise their food through the physiological process of <strong>Photosynthesis</strong>. Leaves act as the \"food factories\" of the plant.</p>\n          <div class=\"step\">\n            <strong>1. Absorption of Water &amp; Minerals:</strong> Roots absorb water and dissolved minerals from the soil. These are transported upwards through specialised vascular tissues called <strong>xylem vessels</strong> to the leaves.\n          </div>\n          <div class=\"step\">\n            <strong>2. Intake of Carbon Dioxide:</strong> Carbon dioxide from atmospheric air enters the leaves through microscopic pores called <strong>stomata</strong>, controlled by guard cells.\n          </div>\n          <div class=\"step\">\n            <strong>3. Trapping Solar Energy:</strong> Green leaves contain a special pigment called <strong>chlorophyll</strong>, which captures radiant solar energy.\n          </div>\n          <div class=\"step\">\n            <strong>4. Chemical Conversion:</strong> Solar energy is converted into chemical energy to combine CO₂ and H₂O into carbohydrate (glucose). Oxygen is released as a vital byproduct into the air:\n            <br>\n            <span class=\"math\">6CO₂ + 6H₂O ⎯⎯⎯[Sunlight / Chlorophyll]⎯⎯→ C₆H₁₂O₆ (Glucose) + 6O₂ (Oxygen)</span>\n          </div>\n          <p>The synthesised glucose is converted and stored in plant organs as <strong>starch</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Raw materials: water via xylem, CO₂ via stomata</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role of chlorophyll and conversion of solar energy</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Word / Chemical equation with products (glucose + oxygen)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q5 -->\n  <div class=\"q-card\" id=\"q1_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Show with the help of a sketch that plants are the ultimate source of food.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>All living organisms on Earth depend directly or indirectly on green plants for nourishment, as plants alone convert solar energy into chemical energy:</p>\n          <div class=\"step\" style=\"text-align:center;font-weight:700;line-height:2;\">\n            ☀️ <strong>Sun (Ultimate Source of Energy)</strong><br>\n            ↓ <em>(trapped by chlorophyll)</em><br>\n            🌱 <strong>Green Plants / Producers (Autotrophs)</strong><br>\n            ↓ <em>(consumed by herbivores)</em><br>\n            🦗 <strong>Herbivores / Primary Consumers</strong> (e.g., Deer, Grasshopper, Goat)<br>\n            ↓ <em>(consumed by carnivores)</em><br>\n            🦁 <strong>Carnivores / Secondary Consumers</strong> (e.g., Lion, Frog, Eagle)<br>\n            ↓ <em>(on death of organisms)</em><br>\n            🍄 <strong>Decomposers / Saprotrophs</strong> (Bacteria, Fungi) → Soil Nutrients → Plants\n          </div>\n          <p><strong>Explanation:</strong> Herbivores directly eat plants. Carnivores eat herbivores that fed on plants. If plants did not exist, herbivores would starve, leading to the extinction of carnivores. Thus, plants are the ultimate source of all food on Earth.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clear sequential sketch (Sun → Plants → Herbivores → Carnivores)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Scientific explanation of direct/indirect dependence</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q6 -->\n  <div class=\"q-card\" id=\"q1_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">Fill in the blanks:<br>(a) Green plants are called _________ since they synthesise their own food.<br>(b) The food synthesised by plants is stored as _________.<br>(c) In photosynthesis solar energy is absorbed by the pigment called _________.<br>(d) During photosynthesis plants take in _________ and release _________ gas.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a)</strong> Green plants are called <strong>autotrophs</strong> since they synthesise their own food.\n          </div>\n          <div class=\"step\">\n            <strong>(b)</strong> The food synthesised by plants is stored as <strong>starch</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(c)</strong> In photosynthesis solar energy is absorbed by the pigment called <strong>chlorophyll</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(d)</strong> During photosynthesis plants take in <strong>carbon dioxide</strong> and release <strong>oxygen</strong> gas.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct blank (0.5 Mark × 4)</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q7 -->\n  <div class=\"q-card\" id=\"q1_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Name the following:<br>(i) A parasitic plant with yellow, slender and branched stem.<br>(ii) A plant that is partially autotrophic.<br>(iii) The pores through which leaves exchange gases.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> <strong>Cuscuta (Amarbel)</strong> — A total parasite that lacks chlorophyll and wraps around host trees.\n          </div>\n          <div class=\"step\">\n            <strong>(ii)</strong> <strong>Pitcher plant (<em>Nepenthes</em>)</strong> or <strong>Venus flytrap</strong> — Possesses green chlorophyll to perform photosynthesis, but traps insects to supplement nitrogen.\n          </div>\n          <div class=\"step\">\n            <strong>(iii)</strong> <strong>Stomata</strong> — Microscopic apertures on leaf surfaces surrounded by guard cells.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct name (1 Mark × 3)</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q8 -->\n  <div class=\"q-card\" id=\"q1_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">Tick the correct answer:<br>(a) Cuscuta is an example of: (i) autotroph (ii) parasite (iii) saprotroph (iv) host<br>(b) The plant which traps and feeds on insects is: (i) Cuscuta (ii) china rose (iii) pitcher plant (iv) rose</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a)</strong> <strong>(ii) parasite</strong><br>\n            <em>Reason:</em> Cuscuta climbs on other trees and derives its food from the host plant using haustoria.\n          </div>\n          <div class=\"step\">\n            <strong>(b)</strong> <strong>(iii) pitcher plant</strong><br>\n            <em>Reason:</em> Its leaf blade is modified into a jug-like pitcher with a lid to trap insects and digest them with enzymes.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): (ii) parasite</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): (iii) pitcher plant</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q9 -->\n  <div class=\"q-card\" id=\"q1_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">Match the items given in Column I with those in Column II:<br>\n        <strong>Column I:</strong> Chlorophyll, Nitrogen, Cuscuta, Animals, Insects<br>\n        <strong>Column II:</strong> Rhizobium, Heterotrophs, Pitcher plant, Leaf, Parasite\n      </div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr><th>Column I</th><th>Column II</th><th>Scientific Rationale</th></tr>\n            </thead>\n            <tbody>\n              <tr><td><strong>Chlorophyll</strong></td><td><strong>Leaf</strong></td><td>Found in chloroplasts of leaf mesophyll cells.</td></tr>\n              <tr><td><strong>Nitrogen</strong></td><td><strong>Rhizobium</strong></td><td>Rhizobium fixes atmospheric nitrogen into soluble nitrates in root nodules.</td></tr>\n              <tr><td><strong>Cuscuta</strong></td><td><strong>Parasite</strong></td><td>Non-green climber that absorbs readymade food from host trees.</td></tr>\n              <tr><td><strong>Animals</strong></td><td><strong>Heterotrophs</strong></td><td>Cannot make own food; depend on plants and other animals.</td></tr>\n              <tr><td><strong>Insects</strong></td><td><strong>Pitcher plant</strong></td><td>Pitcher plant traps and digests insects for nitrogen requirements.</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct pair matched accurately (0.5 Mark × 5)</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q10 -->\n  <div class=\"q-card\" id=\"q1_10\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_10')\">\n      <div class=\"q-num\">Q10</div>\n      <div class=\"q-text\">Mark 'T' if the statement is true and 'F' if it is false:<br>(i) Carbon dioxide is released during photosynthesis. (T/F)<br>(ii) Plants which synthesise their food are called saprotrophs. (T/F)<br>(iii) The product of photosynthesis is not a protein. (T/F)<br>(iv) Solar energy is converted into chemical energy during photosynthesis. (T/F)</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) False (F)</strong> — Oxygen is released during photosynthesis; carbon dioxide is taken in.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) False (F)</strong> — Plants that synthesise their own food are called <strong>autotrophs</strong> (saprotrophs feed on dead decaying matter).\n          </div>\n          <div class=\"step\">\n            <strong>(iii) True (T)</strong> — The primary product of photosynthesis is a carbohydrate (glucose/starch), not a protein.\n          </div>\n          <div class=\"step\">\n            <strong>(iv) True (T)</strong> — Solar light energy is converted into chemical bond energy stored in glucose molecules.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct True/False determination (0.5 Mark × 4)</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q11 & Q12 & Q13 -->\n  <div class=\"q-card\" id=\"q1_11\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_11')\">\n      <div class=\"q-num\">Q11</div>\n      <div class=\"q-text\">Choose the correct option: Which part of the plant takes in carbon dioxide from the air for photosynthesis? (i) Root hair (ii) Stomata (iii) Leaf veins (iv) Petals</div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (ii) Stomata</strong></p>\n          <p><em>Scientific Explanation:</em> Stomata are microscopic pores located primarily on the lower epidermal surface of leaves. They are regulated by guard cells that open during daylight to allow the diffusion of atmospheric CO₂ into photosynthetic mesophyll tissues.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Option (ii) Stomata with brief explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q1_12\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_12')\">\n      <div class=\"q-num\">Q12</div>\n      <div class=\"q-text\">Choose the correct option: Plants take carbon dioxide from the atmosphere mainly through their: (i) roots (ii) stem (iii) flowers (iv) leaves</div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (iv) leaves</strong></p>\n          <p><em>Scientific Explanation:</em> Leaves bear the vast majority of stomata and contain the green mesophyll tissues where photosynthesis occurs, making them the primary site of atmospheric carbon dioxide intake.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Option (iv) leaves</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q1_13\">\n    <div class=\"q-head\" onclick=\"toggleQ('q1_13')\">\n      <div class=\"q-num\">Q13</div>\n      <div class=\"q-text\">Why do farmers grow many fruits and vegetable crops inside large green houses? What are the advantages to the farmers?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>A <strong>greenhouse</strong> (glasshouse or polyhouse) provides a controlled microenvironment for plant cultivation. Farmers grow crops inside greenhouses due to the following specific advantages:</p>\n          <div class=\"step\">\n            <strong>1. Optimal Temperature &amp; Light Control:</strong> Glass walls trap solar heat (greenhouse effect), maintaining a warmer, optimum temperature for photosynthesis even during cold winter seasons.\n          </div>\n          <div class=\"step\">\n            <strong>2. Protection from Harsh Weather &amp; Pests:</strong> Enclosed structures shield delicate crops from high winds, hailstorms, heavy rainfall, frost, birds, insects, and air-borne pests.\n          </div>\n          <div class=\"step\">\n            <strong>3. Controlled Carbon Dioxide &amp; Humidity:</strong> Farmers can enrich the internal air with higher concentrations of CO₂ and maintain ideal humidity, leading to faster growth rates, higher yields, and better-quality produce.\n          </div>\n          <div class=\"step\">\n            <strong>4. Year-Round Farming:</strong> It enables farmers to grow off-season vegetables and fruits, fetching premium market prices.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Greenhouse effect trapping warmth for photosynthesis</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Protection from pests, wind, frost and weather extremes</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Controlled CO₂/humidity and off-season yield advantages</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#059669;\">Case Study: Nitrogen Fixation in Agriculture</div>\n        <div class=\"cbq-question\">\n          <strong>Scenario:</strong> Farmer Ramesh noticed that after harvesting wheat, the soil becomes depleted of nitrogen. However, his agricultural advisor recommended rotating the crop by planting gram (chickpea) or peas before sowing wheat again, without applying synthetic nitrogen fertilisers.\n          <br><br>\n          (i) Name the bacterium that lives in the roots of gram and pea plants.<br>\n          (ii) What type of relationship exists between this bacterium and the leguminous plant?<br>\n          (iii) Why is crop rotation with legumes economically and ecologically beneficial?\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Bacterium Name:</strong> <strong><em>Rhizobium</em></strong>.</p>\n          <p><strong>(ii) Biological Relationship:</strong> <strong>Symbiotic relationship (Symbiosis)</strong>. The bacterium cannot synthesise its own food; it receives shelter, carbohydrates, and organic nutrients from the host plant roots. In exchange, <em>Rhizobium</em> converts atmospheric gaseous nitrogen (N₂) into water-soluble nitrogenous compounds (nitrates) that the plant easily absorbs.</p>\n          <p><strong>(iii) Benefits:</strong> (a) <em>Economic:</em> Saves farmers significant money on expensive chemical fertilisers. (b) <em>Ecological:</em> Prevents soil degradation, preserves soil texture, and stops chemical runoff from polluting nearby water bodies (eutrophication).</p>\n        </div>\n      </div>\n\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">⚡ Assertion &amp; Reason (HOTS)</div>\n        <div class=\"cbq-question\">\n          <strong>Assertion (A):</strong> Pitcher plant performs photosynthesis but still traps and digests insects.<br>\n          <strong>Reason (R):</strong> Pitcher plants grow in nitrogen-deficient boggy soils and feed on insects to fulfil their nitrogen requirement.<br><br>\n          Choose the correct option:<br>\n          (a) Both A and R are true, and R is the correct explanation of A.<br>\n          (b) Both A and R are true, but R is not the correct explanation of A.<br>\n          (c) A is true, but R is false.<br>\n          (d) A is false, but R is true.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>Answer: (a) Both A and R are true, and R is the correct explanation of A.</strong></p>\n          <p><em>Scientific Explanation:</em> Pitcher plants possess green chlorophyll and synthesise their own carbohydrates through photosynthesis. However, the waterlogged, marshy soils they inhabit are severely deficient in available nitrogen minerals. To synthesise essential proteins, the leaf lamina modifies into a pitcher trap with digestive enzymes to digest trapped insects and absorb amino acids.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn\" disabled style=\"opacity:.35;\">← Previous Chapter</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(2)\">Chapter 2: Nutrition in Animals →</button>\n  </div>\n</section>\n","2":"<section class=\"chapter-section\" id=\"ch2\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">2</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 2: Nutrition in Animals</h2>\n      <p>NCERT Exercise Solutions — Complete Step-by-Step Answers with CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Scientific Concepts &amp; Digestive System Summary</div>\n    <ul class=\"concept-list\">\n      <li><strong>Five Major Steps of Holozoic Nutrition:</strong>\n        <ol>\n          <li><em>Ingestion:</em> Taking food into the body via the mouth (buccal cavity).</li>\n          <li><em>Digestion:</em> Breakdown of complex, insoluble food molecules into simple, soluble forms by digestive enzymes.</li>\n          <li><em>Absorption:</em> Movement of digested nutrients through intestinal walls (villi) into the bloodstream.</li>\n          <li><em>Assimilation:</em> Utilization of absorbed nutrients by body cells for energy, growth, and tissue repair.</li>\n          <li><em>Egestion:</em> Removal of undigested, unabsorbed waste residue from the body through the anus.</li>\n        </ol>\n      </li>\n      <li><strong>Human Digestive Canal &amp; Associated Glands:</strong>\n        <ul>\n          <li><em>Mouth &amp; Teeth:</em> Incisors (cutting/biting), Canines (tearing), Premolars &amp; Molars (chewing/grinding). Salivary amylase breaks starch into maltose.</li>\n          <li><em>Stomach:</em> Secretes mucous (protects inner wall), hydrochloric acid (kills bacteria, creates acidic medium pH ~1.5–2), and pepsin (digests proteins into peptides).</li>\n          <li><em>Liver:</em> Largest gland in human body; secretes bile stored in gall bladder; emulsifies fats (breaks large fat globules into tiny droplets).</li>\n          <li><em>Pancreas:</em> Secretes pancreatic juice containing amylase, trypsin, and lipase.</li>\n          <li><em>Small Intestine:</em> Longest part (~7.5 m); site of complete digestion and nutrient absorption through finger-like <strong>villi</strong>.</li>\n          <li><em>Large Intestine:</em> ~1.5 m; absorbs water and essential salts from undigested residue.</li>\n        </ul>\n      </li>\n      <li><strong>Nutrition in Ruminants:</strong> Four-chambered stomach (Rumen, Reticulum, Omasum, Abomasum). Swallowed food is stored in rumen as cud, brought back to mouth and chewed (rumination). Symbiotic bacteria in caecum digest complex cellulose.</li>\n      <li><strong>Nutrition in Amoeba:</strong> Unicellular organism that pushes out finger-like projections called <strong>pseudopodia</strong> (false feet) to engulf food into a <strong>food vacuole</strong> where digestive enzymes break it down.</li>\n    </ul>\n  </div>\n\n  <div class=\"ex-div\">NCERT Textbook Exercise Questions</div>\n\n  <!-- Q1 -->\n  <div class=\"q-card\" id=\"q2_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Fill in the blanks:<br>(a) The main steps of nutrition in humans are _________, _________, _________, _________ and _________.<br>(b) The largest gland in the human body is _________.<br>(c) The stomach releases hydrochloric acid and _________ juices which act on food.<br>(d) The inner wall of the small intestine has many finger-like outgrowths called _________.<br>(e) Amoeba digests its food in the _________.</div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a)</strong> The main steps of nutrition in humans are <strong>ingestion</strong>, <strong>digestion</strong>, <strong>absorption</strong>, <strong>assimilation</strong> and <strong>egestion</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(b)</strong> The largest gland in the human body is <strong>liver</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(c)</strong> The stomach releases hydrochloric acid and <strong>digestive</strong> juices which act on food.\n          </div>\n          <div class=\"step\">\n            <strong>(d)</strong> The inner wall of the small intestine has many finger-like outgrowths called <strong>villi</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(e)</strong> Amoeba digests its food in the <strong>food vacuole</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct blank (0.5 Mark × 5)</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q2 -->\n  <div class=\"q-card\" id=\"q2_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Mark 'T' if the statement is true and 'F' if it is false:<br>(a) Digestion of starch starts in the stomach. (T/F)<br>(b) The tongue helps in mixing food with saliva. (T/F)<br>(c) The gall bladder temporarily stores bile. (T/F)<br>(d) The ruminants bring back swallowed grass into their mouth and chew it for some time. (T/F)</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) False (F)</strong> — Digestion of starch starts in the <strong>mouth (buccal cavity)</strong> by the action of salivary amylase.\n          </div>\n          <div class=\"step\">\n            <strong>(b) True (T)</strong> — The muscular tongue moves food around, mixes it thoroughly with saliva, and assists in swallowing.\n          </div>\n          <div class=\"step\">\n            <strong>(c) True (T)</strong> — Bile juice synthesised by the liver is stored and concentrated in the <strong>gall bladder</strong> until needed.\n          </div>\n          <div class=\"step\">\n            <strong>(d) True (T)</strong> — Ruminants quickly swallow vegetation into the rumen, then bring the partially digested <strong>cud</strong> back into the mouth for thorough rumination.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with brief scientific rationale</span><span class=\"marking-marks\">0.5 Mark each (Total 2 Marks)</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q3 -->\n  <div class=\"q-card\" id=\"q2_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Tick the correct answer:<br>(a) Fat is completely digested in the: (i) stomach (ii) mouth (iii) small intestine (iv) large intestine<br>(b) Water from the undigested food is absorbed mainly in the: (i) stomach (ii) foodpipe (iii) small intestine (iv) large intestine</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) (iii) small intestine</strong><br>\n            <em>Reason:</em> In the small intestine, bile from liver emulsifies fats, and pancreatic lipase together with intestinal lipases breaks them down completely into fatty acids and glycerol.\n          </div>\n          <div class=\"step\">\n            <strong>(b) (iv) large intestine</strong><br>\n            <em>Reason:</em> The large intestine absorbs water and remaining minerals from undigested food slurry, forming semi-solid faeces stored in the rectum.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): (iii) small intestine</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): (iv) large intestine</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q4 -->\n  <div class=\"q-card\" id=\"q2_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Match the items of Column I with those given in Column II:<br>\n        <strong>Column I (Food components):</strong> Carbohydrates, Proteins, Fats<br>\n        <strong>Column II (Products of digestion):</strong> Fatty acids and glycerol, Sugar (glucose), Amino acids\n      </div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr><th>Column I (Complex Food Component)</th><th>Column II (End Product of Digestion)</th></tr>\n            </thead>\n            <tbody>\n              <tr><td><strong>Carbohydrates</strong></td><td><strong>Sugar (Glucose)</strong></td></tr>\n              <tr><td><strong>Proteins</strong></td><td><strong>Amino acids</strong></td></tr>\n              <tr><td><strong>Fats</strong></td><td><strong>Fatty acids and glycerol</strong></td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct matching pair (1 Mark × 3)</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q5 -->\n  <div class=\"q-card\" id=\"q2_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">What are villi? What is their location and function?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Definition:</strong> <strong>Villi</strong> (singular: <em>villus</em>) are millions of microscopic, finger-like projections protruding from the mucous membrane of the digestive tract.\n          </div>\n          <div class=\"step\">\n            <strong>Location:</strong> Villi are located on the inner mucosal lining of the <strong>small intestine</strong> (especially in the jejunum and ileum).\n          </div>\n          <div class=\"step\">\n            <strong>Functions:</strong>\n            <ul>\n              <li><strong>Increasing Surface Area:</strong> The millions of villi vastly increase the effective absorptive surface area of the small intestine by hundreds of times.</li>\n              <li><strong>Rapid Nutrient Absorption:</strong> Each villus contains a dense network of thin, fine blood capillaries and a central lymph vessel (lacteal). Simple digested nutrients (glucose, amino acids, minerals, vitamins) readily diffuse through the thin single-cell epithelium into the blood stream for transportation to all body cells.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of villi (finger-like outgrowths)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Location: Inner wall of small intestine</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Function: Maximising surface area for rapid nutrient absorption</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q6 -->\n  <div class=\"q-card\" id=\"q2_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">Where is bile produced? Which component of the food does it help to digest?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Site of Production &amp; Storage:</strong> Bile juice is produced continuously by the <strong>Liver</strong>. It is temporarily stored and concentrated in a sac-like organ called the <strong>Gall Bladder</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>Component of Food Digested:</strong> Bile plays a vital role in the digestion of <strong>Fats (Lipids)</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>Mechanism (Emulsification):</strong> Bile does not contain enzymes, but its bile salts break down large, hydrophobic fat globules into microscopic droplets (a process called <strong>emulsification</strong>). This enormously increases the surface area for pancreatic lipase enzymes to chemically break fats into fatty acids and glycerol. Furthermore, bile provides the necessary alkaline medium for pancreatic enzymes to function.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Production site: Liver (stored in gall bladder)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Digests fats via emulsification</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q7 -->\n  <div class=\"q-card\" id=\"q2_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Name the type of carbohydrate that can be digested by ruminants but not by humans. Give the reason also.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Carbohydrate Name:</strong> <strong>Cellulose</strong> (the tough structural polysaccharide constituting plant cell walls and grass).\n          </div>\n          <div class=\"step\">\n            <strong>Scientific Reason:</strong>\n            <ul>\n              <li><strong>In Ruminants (Cattle, Deer, Buffaloes):</strong> Ruminants possess a specialised large sac-like chamber called the <strong>caecum / rumen</strong> between the small and large intestine. Inside this chamber live specialised <strong>symbiotic anaerobic bacteria and protozoa</strong> that secrete the enzyme <em>cellulase</em>, which hydrolyses the tough β-glycosidic bonds of cellulose.</li>\n              <li><strong>In Humans:</strong> The human digestive system completely lacks the enzyme <em>cellulase</em> as well as the symbiotic bacteria required to break down cellulose. Therefore, cellulose passes through the human alimentary canal undigested, functioning only as dietary fibre (roughage) to aid bowel movement.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying carbohydrate as Cellulose</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Presence of cellulose-digesting bacteria in ruminants</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Absence of cellulase enzyme/bacteria in humans</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q8 -->\n  <div class=\"q-card\" id=\"q2_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">Why do we get instant energy from glucose?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. No Digestion Required:</strong> Glucose is a simple monosaccharide (the simplest form of carbohydrate). Unlike complex carbohydrates (starch, sucrose) which require hours of enzymatic digestion in the mouth, stomach, and intestine to be broken down, glucose requires <strong>zero digestion</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>2. Direct &amp; Immediate Absorption:</strong> When consumed, glucose is instantly absorbed directly across the intestinal wall into the bloodstream and delivered straight to body cells.\n          </div>\n          <div class=\"step\">\n            <strong>3. Rapid Cellular Respiration:</strong> Inside cells, glucose is readily oxidised by oxygen during cellular respiration to immediately release energy in the form of ATP:\n            <br>\n            <span class=\"math\">Glucose + Oxygen ⎯⎯→ Carbon dioxide + Water + Energy (ATP)</span>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Glucose is simplest sugar requiring no prior digestion</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Direct absorption into blood and instant oxidation in cells</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q9 -->\n  <div class=\"q-card\" id=\"q2_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">Which part of the digestive canal is involved in:<br>(i) absorption of food _________.<br>(ii) chewing of food _________.<br>(iii) killing of bacteria _________.<br>(iv) complete digestion of food _________.<br>(v) formation of faeces _________.</div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) Absorption of food:</strong> <strong>Small intestine</strong> (via intestinal villi).\n          </div>\n          <div class=\"step\">\n            <strong>(ii) Chewing of food:</strong> <strong>Buccal cavity (Mouth)</strong> (by teeth).\n          </div>\n          <div class=\"step\">\n            <strong>(iii) Killing of bacteria:</strong> <strong>Stomach</strong> (by hydrochloric acid).\n          </div>\n          <div class=\"step\">\n            <strong>(iv) Complete digestion of food:</strong> <strong>Small intestine</strong> (action of bile, pancreatic, and intestinal juices).\n          </div>\n          <div class=\"step\">\n            <strong>(v) Formation of faeces:</strong> <strong>Large intestine</strong> (water absorbed, compacted into solid faeces).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct organ identified (0.5 Mark × 5)</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q10 -->\n  <div class=\"q-card\" id=\"q2_10\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_10')\">\n      <div class=\"q-num\">Q10</div>\n      <div class=\"q-text\">State one similarity and one difference between the nutrition in amoeba and human beings.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Similarity:</strong> Both Amoeba and humans exhibit <strong>holozoic nutrition</strong> consisting of the same fundamental sequence of stages: ingestion, digestion (where complex substances are broken down into simpler soluble forms by digestive enzymes), absorption, assimilation for energy, and egestion of undigested waste.\n          </div>\n          <div class=\"step\">\n            <strong>Difference:</strong>\n            <ul>\n              <li><strong>Amoeba:</strong> Being a single-celled microscopic organism, it has no mouth or specialised digestive canal; food is captured by pseudopodia and digested inside a temporary <strong>food vacuole</strong>.</li>\n              <li><strong>Humans:</strong> Being complex multicellular organisms, they possess a specialised, highly developed <strong>alimentary canal</strong> with distinct organs (mouth, stomach, intestine) and specialised digestive glands (salivary glands, liver, pancreas).</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Valid similarity (holozoic stages / enzymatic digestion)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Valid structural difference (food vacuole vs complex alimentary canal)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q11 & Q12 & Q13 -->\n  <div class=\"q-card\" id=\"q2_11\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_11')\">\n      <div class=\"q-num\">Q11</div>\n      <div class=\"q-text\">Match the items of Column I with suitable items in Column II:<br>\n        <strong>Column I:</strong> (a) Salivary gland, (b) Stomach, (c) Liver, (d) Rectum, (e) Small intestine, (f) Large intestine<br>\n        <strong>Column II:</strong> (i) Bile juice secretion, (ii) Storage of undigested food, (iii) Saliva secretion, (iv) Acid release, (v) Digestion is completed, (vi) Absorption of water\n      </div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr><th>Column I (Organ / Gland)</th><th>Column II (Primary Function)</th></tr>\n            </thead>\n            <tbody>\n              <tr><td><strong>(a) Salivary gland</strong></td><td><strong>(iii) Saliva secretion</strong></td></tr>\n              <tr><td><strong>(b) Stomach</strong></td><td><strong>(iv) Acid release</strong> (HCl)</td></tr>\n              <tr><td><strong>(c) Liver</strong></td><td><strong>(i) Bile juice secretion</strong></td></tr>\n              <tr><td><strong>(d) Rectum</strong></td><td><strong>(ii) Storage of undigested food</strong></td></tr>\n              <tr><td><strong>(e) Small intestine</strong></td><td><strong>(v) Digestion is completed</strong></td></tr>\n              <tr><td><strong>(f) Large intestine</strong></td><td><strong>(vi) Absorption of water</strong></td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct pair accurately matched (0.5 Mark × 6)</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_12\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_12')\">\n      <div class=\"q-num\">Q12</div>\n      <div class=\"q-text\">Label the following parts of the human digestive system in sequence: Stomach, Gall bladder, Liver, Pancreas, Small intestine, Large intestine, Rectum, Anus.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>The anatomical sequence of organs forming the human digestive system from mouth to anus is:</p>\n          <div class=\"step\">\n            1. <strong>Mouth / Buccal Cavity:</strong> Teeth masticate food; salivary glands add saliva.<br>\n            2. <strong>Oesophagus (Foodpipe):</strong> Connects pharynx to stomach through peristaltic waves.<br>\n            3. <strong>Stomach:</strong> J-shaped muscular sac on the upper left abdomen that releases HCl, mucous, and pepsin.<br>\n            4. <strong>Liver:</strong> Large reddish-brown gland on upper right side; produces bile.<br>\n            5. <strong>Gall Bladder:</strong> Pear-shaped sac nestled beneath liver; stores and concentrates bile.<br>\n            6. <strong>Pancreas:</strong> Cream-coloured leaf-shaped gland located just below stomach; secretes pancreatic enzymes.<br>\n            7. <strong>Small Intestine:</strong> Highly coiled 7.5-metre central organ; completes chemical digestion and absorbs nutrients via villi.<br>\n            8. <strong>Large Intestine:</strong> Wider 1.5-metre frame surrounding the small intestine; absorbs water and salts.<br>\n            9. <strong>Rectum:</strong> Terminal pouch storing compacted faeces.<br>\n            10. <strong>Anus:</strong> Muscular sphincter opening for egestion.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct identification and anatomical sequence of organs</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q2_13\">\n    <div class=\"q-head\" onclick=\"toggleQ('q2_13')\">\n      <div class=\"q-num\">Q13</div>\n      <div class=\"q-text\">Can we survive only on raw, leafy vegetables/grass? Discuss.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>No, human beings cannot survive solely on raw, leafy vegetables and grass.</strong></p>\n          <div class=\"step\">\n            <strong>1. Inability to Digest Cellulose:</strong> Grass and raw leafy plants primarily contain <strong>cellulose</strong>, a tough structural carbohydrate. The human digestive tract completely lacks the enzyme <em>cellulase</em> and does not house the symbiotic cellulose-fermenting micro-organisms found in ruminants (cows, goats). Consequently, cellulose passes out undigested, providing virtually zero energy to humans.\n          </div>\n          <div class=\"step\">\n            <strong>2. Severe Energy &amp; Nutrient Deficit:</strong> Raw vegetables contain very high proportions of water and fibre, but extremely low concentrations of accessible proteins, essential fats, and complex carbohydrates needed to sustain human metabolic rates and body organ functions.\n          </div>\n          <div class=\"step\">\n            <strong>3. Nutritional Role as Roughage:</strong> While leafy vegetables are vital in a balanced diet to provide essential vitamins, minerals, and roughage (fibre) to maintain healthy bowel movement and prevent constipation, they must be supplemented with energy-dense foods (grains, pulses, dairy, oils) to sustain life.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clear negative response stating lack of cellulase in humans</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Inadequate calorie, protein, and fat provision from grass</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Highlighting role of leafy greens as roughage/vitamins in a balanced diet</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#059669;\">Case Study: Oral Rehydration Therapy (ORT)</div>\n        <div class=\"cbq-question\">\n          <strong>Clinical Case:</strong> 10-year-old Aarav contracted an intestinal infection after eating unhygienic street food. He experienced frequent watery stools and vomiting, feeling extremely weak, dizzy, and parched. The doctor diagnosed him with acute diarrhoea, warned against severe dehydration, and immediately prescribed frequent sips of ORS (Oral Rehydration Solution).\n          <br><br>\n          (i) What is dehydration, and why is it dangerous?<br>\n          (ii) How can an emergency ORS solution be prepared at home?<br>\n          (iii) Why is simple plain water not as effective as ORS during severe diarrhoea?\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Dehydration:</strong> Dehydration is the excessive loss of water and vital dissolved mineral salts (electrolytes such as sodium, potassium, and chloride) from body tissues. It is life-threatening because blood volume drops, leading to hypovolemic shock, organ failure, and collapse.</p>\n          <p><strong>(ii) Home Preparation of ORS:</strong> Boil 1 litre of clean drinking water and let it cool. Dissolve <strong>6 level teaspoons of sugar</strong> and <strong>half a level teaspoon of salt</strong> thoroughly in the water.</p>\n          <p><strong>(iii) Mechanism:</strong> The intestinal lining absorbs sodium and water through co-transport coupled with glucose molecules. Plain water cannot be efficiently absorbed by an inflamed, rapidly purging bowel and gets excreted. The presence of glucose in ORS triggers rapid intestinal sodium and water reabsorption back into the circulatory system.</p>\n        </div>\n      </div>\n\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">⚡ Assertion &amp; Reason (HOTS)</div>\n        <div class=\"cbq-question\">\n          <strong>Assertion (A):</strong> A patient whose gall bladder has been surgically removed is advised to avoid heavy, fatty meals.<br>\n          <strong>Reason (R):</strong> The gall bladder produces bile juice, and without it, no bile is synthesised in the body.<br><br>\n          Choose the correct option:<br>\n          (a) Both A and R are true, and R is the correct explanation of A.<br>\n          (b) Both A and R are true, but R is not the correct explanation of A.<br>\n          (c) A is true, but R is false.<br>\n          (d) A is false, but R is true.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>Answer: (c) A is true, but R is false.</strong></p>\n          <p><em>Scientific Explanation:</em> Assertion (A) is true because without the gall bladder, there is no reservoir to store and release concentrated pulses of bile when a fatty meal enters the duodenum. However, Reason (R) is completely false: bile is synthesised by the <strong>liver</strong>, not the gall bladder. Following a cholecystectomy, the liver continues to produce bile, which drips continuously in dilute amounts directly into the intestine, making large boluses of fat difficult to digest.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(1)\">← Chapter 1: Nutrition in Plants</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(3)\">Chapter 3: Heat →</button>\n  </div>\n</section>\n","3":"<section class=\"chapter-section\" id=\"ch3\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">3</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 3: Heat</h2>\n      <p>NCERT Exercise Solutions — Complete Step-by-Step Answers with CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Scientific Concepts &amp; Thermodynamics Summary</div>\n    <ul class=\"concept-list\">\n      <li><strong>Heat vs Temperature:</strong>\n        <ul>\n          <li><em>Heat:</em> A form of energy that flows spontaneously from a body at a higher temperature to a body at a lower temperature until thermal equilibrium is reached. Unit: Joule (J) or Calorie (cal).</li>\n          <li><em>Temperature:</em> A reliable quantitative measure of the degree of hotness or coldness of an object. Measured using thermometers in Degree Celsius (°C), Fahrenheit (°F), or Kelvin (K).</li>\n        </ul>\n      </li>\n      <li><strong>Thermometers:</strong>\n        <ul>\n          <li><em>Clinical Thermometer:</em> Designed specifically for human body temperature. Range: 35°C to 42°C (or 94°F to 108°F). Contains a narrow constriction (<strong>kink</strong>) just above the bulb to prevent mercury from falling back automatically before the reading is recorded.</li>\n          <li><em>Laboratory Thermometer:</em> Used to measure temperature of chemical solutions and substances in labs. Range: -10°C to 110°C. Has no kink; reading must be taken while still in contact with the substance.</li>\n        </ul>\n      </li>\n      <li><strong>Three Modes of Heat Transfer:</strong>\n        <ol>\n          <li><em>Conduction:</em> Heat transfer in solids from the hotter end to the colder end through molecular vibrations without the actual movement of particles. Metals are good conductors; wood, plastic, glass, and air are insulators.</li>\n          <li><em>Convection:</em> Heat transfer in fluids (liquids and gases) where warmer, less dense fluid expands, rises, and cooler denser fluid sinks to replace it, setting up <strong>convection currents</strong>. Drives <strong>sea breeze</strong> (day) and <strong>land breeze</strong> (night) in coastal areas.</li>\n          <li><em>Radiation:</em> Heat transfer through electromagnetic infrared waves without requiring any physical medium. Can travel through vacuum (how the Sun's heat warms Earth). Dark, dull surfaces absorb and radiate heat best; light, polished surfaces reflect heat.</li>\n        </ol>\n      </li>\n    </ul>\n  </div>\n\n  <div class=\"ex-div\">NCERT Textbook Exercise Questions</div>\n\n  <!-- Q1 -->\n  <div class=\"q-card\" id=\"q3_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">State similarities and differences between the laboratory thermometer and the clinical thermometer.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Similarities:</strong>\n            <ul>\n              <li>Both thermometers consist of a long, narrow, uniform glass capillary tube with a sealed liquid bulb at one end.</li>\n              <li>Both traditionally use mercury (or coloured alcohol) as the thermometric liquid that expands uniformly upon heating.</li>\n              <li>Both are graduated with the Celsius scale (°C) to measure temperature.</li>\n            </ul>\n          </div>\n          <div class=\"step\">\n            <strong>Differences:</strong>\n            <table class=\"data-table\">\n              <thead>\n                <tr><th>Parameter</th><th>Clinical Thermometer</th><th>Laboratory Thermometer</th></tr>\n              </thead>\n              <tbody>\n                <tr>\n                  <td><strong>Measurement Range</strong></td>\n                  <td>35°C to 42°C (spans human body temperature variation).</td>\n                  <td>-10°C to 110°C (wide range for chemical experiments).</td>\n                </tr>\n                <tr>\n                  <td><strong>Constriction (Kink)</strong></td>\n                  <td>Has a kink in the capillary tube near the bulb to prevent mercury from backflowing.</td>\n                  <td>Has no kink; mercury level falls immediately when removed from the medium.</td>\n                </tr>\n                <tr>\n                  <td><strong>Taking Readings</strong></td>\n                  <td>Reading can be taken conveniently after removing it from the patient's mouth or armpit.</td>\n                  <td>Reading must be recorded while the thermometer bulb remains immersed in the liquid.</td>\n                </tr>\n                <tr>\n                  <td><strong>Jerking</strong></td>\n                  <td>Must be given a few sharp jerks to reset mercury below 35°C before reuse.</td>\n                  <td>Does not require jerking; resets spontaneously to ambient temperature.</td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing at least two valid similarities (glass tube, mercury, °C scale)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Differences in range (35–42°C vs -10 to 110°C) and presence/absence of kink</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q2 -->\n  <div class=\"q-card\" id=\"q3_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Give two examples each of conductors and insulators of heat.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. Conductors of Heat (Materials that permit thermal energy to pass easily):</strong>\n            <ul>\n              <li><strong>Copper</strong> (used in bottom of cookware and heat exchangers)</li>\n              <li><strong>Aluminium / Iron</strong> (used in cooking utensils, radiators)</li>\n            </ul>\n          </div>\n          <div class=\"step\">\n            <strong>2. Insulators of Heat (Poor conductors that impede heat transfer):</strong>\n            <ul>\n              <li><strong>Wood</strong> (used for handles of cooking pots)</li>\n              <li><strong>Plastic / Bakelite</strong> (used for electrical iron and pressure cooker handles)</li>\n              <li><em>(Also Air, Glass, Wool, Thermocol).</em></li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Two correct conductors with definition</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Two correct insulators with definition</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q3 -->\n  <div class=\"q-card\" id=\"q3_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Fill in the blanks:<br>(a) The hotness of an object is determined by its _________.<br>(b) Temperature of boiling water cannot be measured by a _________ thermometer.<br>(c) Temperature is measured in degree _________.<br>(d) No medium is required for transfer of heat by the process of _________.<br>(e) A cold steel spoon is dipped in a cup of hot milk. It transfers heat to its other end by the process of _________.<br>(f) Clothes of _________ colours absorb heat better than clothes of light colours.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a)</strong> The hotness of an object is determined by its <strong>temperature</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(b)</strong> Temperature of boiling water cannot be measured by a <strong>clinical</strong> thermometer. <em>(Since clinical range ends at 42°C while boiling water is 100°C; it would burst).</em>\n          </div>\n          <div class=\"step\">\n            <strong>(c)</strong> Temperature is measured in degree <strong>Celsius</strong> (°C).\n          </div>\n          <div class=\"step\">\n            <strong>(d)</strong> No medium is required for transfer of heat by the process of <strong>radiation</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(e)</strong> A cold steel spoon is dipped in a cup of hot milk. It transfers heat to its other end by the process of <strong>conduction</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(f)</strong> Clothes of <strong>dark</strong> colours absorb heat better than clothes of light colours.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct fill-in-the-blank (0.5 Mark × 6)</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q4 -->\n  <div class=\"q-card\" id=\"q3_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Match the following:<br>\n        (i) Land breeze blows during — (a) summer<br>\n        (ii) Sea breeze blows during — (b) winter<br>\n        (iii) Dark coloured clothes are preferred during — (c) day<br>\n        (iv) Light coloured clothes are preferred during — (d) night\n      </div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr><th>Phenomenon / Practice</th><th>Correct Matching</th><th>Scientific Reason</th></tr>\n            </thead>\n            <tbody>\n              <tr><td><strong>(i) Land breeze blows during</strong></td><td><strong>(d) night</strong></td><td>Land cools down faster than sea water at night; cooler air from land moves towards sea.</td></tr>\n              <tr><td><strong>(ii) Sea breeze blows during</strong></td><td><strong>(c) day</strong></td><td>Land heats up faster than sea during day; warm air rises, cool sea air rushes in.</td></tr>\n              <tr><td><strong>(iii) Dark coloured clothes are preferred during</strong></td><td><strong>(b) winter</strong></td><td>Dark fabrics absorb maximum radiant heat from sunlight, keeping body warm.</td></tr>\n              <tr><td><strong>(iv) Light coloured clothes are preferred during</strong></td><td><strong>(a) summer</strong></td><td>Light fabrics reflect most of the incident solar radiation, keeping body cool.</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct match with brief rationale (0.5 Mark × 4)</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q5 -->\n  <div class=\"q-card\" id=\"q3_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Discuss why wearing more layers of clothing during winter keeps us warmer than wearing just one thick piece of clothing.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Wearing multiple layers of clothing keeps us significantly warmer than wearing one thick garment due to the <strong>insulating properties of trapped air</strong>:</p>\n          <div class=\"step\">\n            <strong>1. Trapped Air Layers:</strong> When we wear multiple thin layers of clothes, pockets of air become trapped in the microscopic spaces between adjacent layers of fabric.\n          </div>\n          <div class=\"step\">\n            <strong>2. Air is a Poor Conductor of Heat:</strong> Air is one of the poorest conductors (best insulators) of heat in nature. The motionless trapped air forms an effective thermal barrier that prevents body heat from conducting outwards into the freezing ambient surroundings.\n          </div>\n          <div class=\"step\">\n            <strong>Conclusion:</strong> Multiple trapped air interfaces provide far superior thermal resistance compared to a single thick piece of fabric, which has only two exterior air-contact surfaces.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mention of air trapped between multiple layers of fabric</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Air acting as a poor conductor/insulator preventing body heat loss</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q6 & Q7 & Q8 & Q9 & Q10 & Q11 -->\n  <div class=\"q-card\" id=\"q3_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">Look at a vessel containing water boiling over a burner flame. Mark where the heat is being transferred by conduction, by convection and by radiation.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. Conduction:</strong> Takes place through the <strong>solid metallic base and sides of the pan</strong>. Heat transfers from the outer bottom surface of the metal pan directly to its inner surface in contact with water, and along the pan handle.\n          </div>\n          <div class=\"step\">\n            <strong>2. Convection:</strong> Takes place <strong>within the water inside the pan</strong>. The bottom water layer heats up, expands, becomes lighter, and rises upwards. Cold, denser water from the top sinks to the bottom, creating circular <strong>convection currents</strong> that heat the entire body of water.\n          </div>\n          <div class=\"step\">\n            <strong>3. Radiation:</strong> Takes place <strong>through the air surrounding the flame and hot pan</strong>. Thermal infrared waves travel directly outward in all directions from the burner flame and hot outer pan surfaces without needing physical contact.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conduction through solid metal pan base/handle</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Convection within water via convection currents</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Radiation through air from flame and exterior pan</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">In places of hot climate, it is advised that the outer walls of houses be painted white. Explain.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. High Reflection:</strong> White and light-coloured surfaces are excellent reflectors of radiant heat. They reflect back most of the intense sunlight falling upon them.\n          </div>\n          <div class=\"step\">\n            <strong>2. Poor Absorption:</strong> White surfaces absorb a minimal fraction of solar infrared radiation compared to dark surfaces.\n          </div>\n          <div class=\"step\">\n            <strong>Conclusion:</strong> As a result, the outer walls absorb very little heat during scorching daytime hours, keeping the interior of the house substantially cooler, reducing room temperature and cooling costs.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">White surfaces reflect most incident solar radiant heat</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Minimal heat absorption keeps building interiors cooler</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">One litre of water at 30°C is mixed with one litre of water at 50°C. The temperature of the mixture will be: (a) 80°C (b) more than 50°C but less than 80°C (c) 20°C (d) between 30°C and 50°C</div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (d) between 30°C and 50°C</strong></p>\n          <div class=\"step\">\n            <em>Scientific Principle of Heat Exchange:</em> Heat flows spontaneously from a warmer body to a cooler body until thermal equilibrium is attained:\n            <br>\n            <span class=\"math\">Heat Lost by Hot Water = Heat Gained by Cold Water</span>\n            <br>\n            For equal masses of water: <span class=\"math\">T_final = (30°C + 50°C) / 2 = 80 / 2 = 40°C</span>. Since 40°C lies strictly between 30°C and 50°C, option (d) is correct.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Option (d) with heat equilibrium explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">An iron ball at 40°C is dropped in a mug containing water at 40°C. The heat will: (a) flow from iron ball to water (b) not flow from iron ball to water or from water to iron ball (c) flow from water to iron ball (d) increase the temperature of both</div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (b) not flow from iron ball to water or from water to iron ball</strong></p>\n          <div class=\"step\">\n            <em>Scientific Reason:</em> The flow of thermal energy requires a <strong>temperature difference (ΔT &gt; 0)</strong> between two contacting bodies. Since both the iron ball and water are at the exact same temperature (40°C), they are in a state of <strong>thermal equilibrium</strong>. Hence, no net heat transfer takes place between them.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Option (b) with thermal equilibrium principle</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_10\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_10')\">\n      <div class=\"q-num\">Q10</div>\n      <div class=\"q-text\">A wooden spoon is dipped in a cup of ice cream. Its other end: (a) becomes cold by the process of conduction (b) becomes cold by the process of convection (c) becomes cold by the process of radiation (d) does not become cold</div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (d) does not become cold</strong></p>\n          <div class=\"step\">\n            <em>Scientific Reason:</em> Wood is a non-metal and an <strong>insulator (poor conductor of heat)</strong>. It does not allow thermal energy to conduct from one end of the spoon to the other. Therefore, the outer handle does not become cold.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Option (d) with wood insulator explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q3_11\">\n    <div class=\"q-head\" onclick=\"toggleQ('q3_11')\">\n      <div class=\"q-num\">Q11</div>\n      <div class=\"q-text\">Stainless steel pans are usually provided with copper bottoms. The reason for this could be that: (a) copper bottom makes the pan more durable (b) such pans appear colourful (c) copper is a better conductor of heat than the stainless steel (d) copper is easier to clean than the stainless steel</div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (c) copper is a better conductor of heat than the stainless steel</strong></p>\n          <div class=\"step\">\n            <em>Scientific Reason:</em> Copper has significantly higher thermal conductivity than stainless steel alloy. A copper base conducts heat from the stove burner much faster and distributes heat evenly across the base of the pan, cooking food quickly while preventing localized burning (hotspots).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Option (c) with thermal conductivity comparison</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#059669;\">Case Study: Coastal Breeze Convection Cycles</div>\n        <div class=\"cbq-question\">\n          <strong>Scenario:</strong> Coastal cities like Mumbai and Chennai experience pleasant breezes during both day and night without drastic diurnal temperature extremes seen in desert cities like Jaisalmer.\n          <br><br>\n          (i) What is Sea Breeze? Explain its formation mechanism during daytime.<br>\n          (ii) What is Land Breeze? Explain why it reverses during nighttime.<br>\n          (iii) Why do windows of houses in coastal areas ideally face the sea?\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Sea Breeze (Daytime):</strong> Land heats up much faster than water due to its lower specific heat capacity. During the day, air above land heats up, expands, and rises. Cool, dense air from over the sea moves inland towards land to take its place. This cool onshore wind is the <strong>Sea Breeze</strong>.</p>\n          <p><strong>(ii) Land Breeze (Nighttime):</strong> At night, land cools down much faster than sea water. The sea water remains relatively warm, causing the air above it to rise. Cooler, denser air from over the land blows seaward to replace it. This offshore wind is the <strong>Land Breeze</strong>.</p>\n          <p><strong>(iii) Architectural Design:</strong> Windows are built facing the sea to directly receive the continuous, refreshing daytime sea breeze, naturally cooling the interior without requiring artificial air conditioning.</p>\n        </div>\n      </div>\n\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">⚡ Assertion &amp; Reason (HOTS)</div>\n        <div class=\"cbq-question\">\n          <strong>Assertion (A):</strong> A clinical thermometer should never be sterilised by dipping in boiling water.<br>\n          <strong>Reason (R):</strong> The maximum calibrated range of a clinical thermometer is 42°C, whereas boiling water reaches 100°C, causing extreme mercury expansion that can shatter the glass capillary.<br><br>\n          Choose the correct option:<br>\n          (a) Both A and R are true, and R is the correct explanation of A.<br>\n          (b) Both A and R are true, but R is not the correct explanation of A.<br>\n          (c) A is true, but R is false.<br>\n          (d) A is false, but R is true.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>Answer: (a) Both A and R are true, and R is the correct explanation of A.</strong></p>\n          <p><em>Scientific Explanation:</em> Clinical thermometers are specially engineered only for human physiological range (35°C–42°C). Dipping in boiling water (100°C) produces excessive hydrostatic pressure from expanding mercury, which will break the sealed glass tube and release toxic mercury vapor. Antiseptic solutions (like Dettol or alcohol wipes) should be used instead.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(2)\">← Chapter 2: Nutrition in Animals</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(4)\">Chapter 4: Acids, Bases &amp; Salts →</button>\n  </div>\n</section>\n","4":"<section class=\"chapter-section\" id=\"ch4\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">4</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 4: Acids, Bases and Salts</h2>\n      <p>NCERT Exercise Solutions — Complete Step-by-Step Answers with CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Scientific Concepts &amp; Neutralisation Reactions</div>\n    <ul class=\"concept-list\">\n      <li><strong>Acids:</strong> Substances with a sour taste, turn blue litmus red, pH &lt; 7. Contain hydrogen ions (H⁺).\n        <ul>\n          <li><em>Natural/Organic Acids:</em> Acetic acid (Vinegar), Formic acid (Ant sting), Citric acid (Lemons, Oranges), Lactic acid (Curd), Oxalic acid (Spinach), Ascorbic acid/Vitamin C (Amla, Citrus), Tartaric acid (Tamarind, Grapes).</li>\n          <li><em>Mineral Acids:</em> Hydrochloric acid (HCl), Sulphuric acid (H₂SO₄), Nitric acid (HNO₃).</li>\n        </ul>\n      </li>\n      <li><strong>Bases:</strong> Substances bitter in taste and soapy/slippery to touch, turn red litmus blue, pH &gt; 7. Contain hydroxide ions (OH⁻).\n        <ul>\n          <li>Calcium hydroxide (Lime water), Ammonium hydroxide (Window cleaner), Sodium hydroxide / Potassium hydroxide (Soap), Magnesium hydroxide (Milk of Magnesia).</li>\n        </ul>\n      </li>\n      <li><strong>Indicators:</strong> Special chemical substances that exhibit distinct colour changes in acidic and basic solutions:\n        <ul>\n          <li><em>Litmus (from Lichens):</em> Mauve/purple in neutral; <strong>Red in acid</strong>; <strong>Blue in base</strong>.</li>\n          <li><em>Turmeric:</em> Yellow in acid/neutral; turns <strong>Reddish-brown in base</strong>.</li>\n          <li><em>China Rose Petal Solution:</em> Turns <strong>dark pink (magenta) in acid</strong>; <strong>green in base</strong>.</li>\n          <li><em>Phenolphthalein:</em> <strong>Colourless in acid</strong>; turns <strong>pink in base</strong>.</li>\n        </ul>\n      </li>\n      <li><strong>Neutralisation Reaction:</strong> The reaction between an acid and a base producing a salt and water with the evolution of heat:\n        <br>\n        <span class=\"math\">Acid + Base ⎯⎯→ Salt + Water + Heat</span><br>\n        <span class=\"math\">HCl (Hydrochloric acid) + NaOH (Sodium hydroxide) ⎯⎯→ NaCl (Sodium chloride) + H₂O + Heat</span>\n      </li>\n    </ul>\n  </div>\n\n  <div class=\"ex-div\">NCERT Textbook Exercise Questions</div>\n\n  <!-- Q1 -->\n  <div class=\"q-card\" id=\"q4_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">State differences between acids and bases.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr><th>Property</th><th>Acids</th><th>Bases</th></tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td><strong>Taste</strong></td>\n                <td>Have a distinctly <strong>sour</strong> taste (e.g., lemon juice, vinegar).</td>\n                <td>Have a distinctly <strong>bitter</strong> taste (e.g., baking soda, neem).</td>\n              </tr>\n              <tr>\n                <td><strong>Touch / Texture</strong></td>\n                <td>Do not feel soapy; can cause burning sensations when concentrated.</td>\n                <td>Feel <strong>soapy and slippery</strong> to the touch.</td>\n              </tr>\n              <tr>\n                <td><strong>Action on Litmus</strong></td>\n                <td>Turn <strong>blue litmus paper red</strong>.</td>\n                <td>Turn <strong>red litmus paper blue</strong>.</td>\n              </tr>\n              <tr>\n                <td><strong>Phenolphthalein Indicator</strong></td>\n                <td>Remains <strong>colourless</strong>.</td>\n                <td>Turns bright <strong>pink</strong>.</td>\n              </tr>\n              <tr>\n                <td><strong>Turmeric Paper</strong></td>\n                <td>Remains yellow (no colour change).</td>\n                <td>Turns <strong>reddish-brown</strong>.</td>\n              </tr>\n              <tr>\n                <td><strong>Examples</strong></td>\n                <td>Citric acid, hydrochloric acid (HCl), acetic acid.</td>\n                <td>Sodium hydroxide (NaOH), calcium hydroxide (slaked lime).</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Taste and touch distinctions</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Action on litmus, phenolphthalein and turmeric indicators</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Chemical examples for both classes</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q2 -->\n  <div class=\"q-card\" id=\"q4_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Ammonia is found in many household products, such as window cleaners. It turns red litmus blue. What is its nature?</div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Nature of Ammonia:</strong> <strong>Basic (Alkaline)</strong>.</p>\n          <div class=\"step\">\n            <em>Scientific Reason:</em> Bases have the characteristic chemical property of turning <strong>red litmus paper blue</strong>. Ammonia dissolves in water to form ammonium hydroxide (NH₄OH), which releases hydroxide ions (OH⁻), rendering the cleaner alkaline.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating basic nature + litmus test rationale</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q3 -->\n  <div class=\"q-card\" id=\"q4_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Name the source from which litmus solution is obtained. What is the use of this solution?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Source:</strong> Natural litmus dye solution is extracted from <strong>Lichens</strong> (a composite symbiotic organism of an alga and a fungus). In distilled neutral water, it possesses a characteristic mauve (purple) colour.\n          </div>\n          <div class=\"step\">\n            <strong>Use:</strong> Litmus solution is used universally as an <strong>acid-base indicator</strong> to test the chemical nature of unknown aqueous solutions:\n            <ul>\n              <li>When added to an <em>acidic solution</em>, it turns <strong>red</strong>.</li>\n              <li>When added to a <em>basic solution</em>, it turns <strong>blue</strong>.</li>\n              <li>In a <em>neutral solution</em>, it remains <strong>purple</strong>.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Source identified as Lichens</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Use as indicator with colour shifts in acid (red) and base (blue)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q4 -->\n  <div class=\"q-card\" id=\"q4_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Is the distilled water acidic/basic/neutral? How would you verify it?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Nature of Distilled Water:</strong> Distilled water is completely <strong>Neutral</strong> (pH = 7).</p>\n          <div class=\"step\">\n            <strong>Experimental Verification:</strong>\n            <ol>\n              <li>Take two strips of litmus paper: one red litmus paper and one blue litmus paper.</li>\n              <li>Place a few drops of pure distilled water onto both strips using a clean dropper.</li>\n              <li><strong>Observation:</strong>\n                <ul>\n                  <li>Red litmus paper does not change colour (remains red).</li>\n                  <li>Blue litmus paper does not change colour (remains blue).</li>\n                </ul>\n              </li>\n              <li><strong>Conclusion:</strong> Since the water affects neither blue nor red litmus, it is neither acidic nor basic; it is confirmed to be strictly <strong>neutral</strong>.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">State neutral nature</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Verification test using both red and blue litmus strips</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q5 -->\n  <div class=\"q-card\" id=\"q4_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Describe the process of neutralisation with the help of an example.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Definition:</strong> <strong>Neutralisation</strong> is the chemical reaction between an acid and a base. The acidic nature of the acid and the alkaline nature of the base destroy each other, resulting in the formation of a neutral salt and water along with the release of thermal energy:\n            <br>\n            <span class=\"math\">Acid + Base ⎯⎯→ Salt + Water + Heat</span>\n          </div>\n          <div class=\"step\">\n            <strong>Experimental Example:</strong>\n            <ol>\n              <li>Take 5 mL of dilute Hydrochloric acid (HCl) in a conical flask and add 2–3 drops of phenolphthalein indicator. The solution remains colourless.</li>\n              <li>Using a burette, add dilute Sodium hydroxide solution (NaOH) drop by drop with continuous swirling.</li>\n              <li>At the exact neutralisation point, the solution turns a faint persistent pink.</li>\n              <li>Now add one more drop of dilute HCl; the pink colour vanishes. Add a drop of NaOH; pink colour returns.</li>\n              <li>Touching the flask reveals that the mixture has become warm, showing that heat is evolved.</li>\n            </ol>\n          </div>\n          <div class=\"step\">\n            <strong>Chemical Equation:</strong>\n            <br>\n            <span class=\"math\">HCl (Hydrochloric acid) + NaOH (Sodium hydroxide) ⎯⎯→ NaCl (Sodium chloride) + H₂O (Water) + Heat</span>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition with word equation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Detailed experimental demonstration using phenolphthalein</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Balanced chemical equation (HCl + NaOH → NaCl + H₂O)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q6 -->\n  <div class=\"q-card\" id=\"q4_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">Mark 'T' if the statement is true and 'F' if it is false:<br>(a) Nitric acid turns red litmus blue. (T/F)<br>(b) Sodium hydroxide turns blue litmus red. (T/F)<br>(c) Sodium hydroxide and hydrochloric acid neutralise each other and form salt and water. (T/F)<br>(d) Indicator is a substance which shows different colours in acidic and basic solutions. (T/F)<br>(e) Tooth decay is caused by the presence of a base. (T/F)</div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) False (F)</strong> — Nitric acid is a strong acid; it turns blue litmus red, not red litmus blue.\n          </div>\n          <div class=\"step\">\n            <strong>(b) False (F)</strong> — Sodium hydroxide is a strong base; it turns red litmus blue.\n          </div>\n          <div class=\"step\">\n            <strong>(c) True (T)</strong> — This is a classical neutralisation reaction forming sodium chloride (table salt) and water.\n          </div>\n          <div class=\"step\">\n            <strong>(d) True (T)</strong> — Chemical indicators exhibit characteristic colour transitions depending on hydrogen ion concentrations.\n          </div>\n          <div class=\"step\">\n            <strong>(e) False (F)</strong> — Tooth decay is caused by <strong>acids</strong> produced by mouth bacteria fermenting leftover sugar, corroding the enamel.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct True/False determination (0.5 Mark × 5)</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q7 -->\n  <div class=\"q-card\" id=\"q4_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Dorji has a few bottles of soft drink in his restaurant. But, unfortunately, these are not labelled. He has to serve the drinks on the demand of customers. One customer wants acidic drink, another wants basic and third one wants neutral drink. How will Dorji decide which drink is to be served to whom?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Dorji can easily distinguish the three drinks by testing a drop from each unlabelled bottle using <strong>red and blue litmus papers</strong> (or by tasting a drop, since edible soft drinks are safe):</p>\n          <div class=\"step\">\n            <strong>1. Identification of the Acidic Drink:</strong><br>\n            Dip a strip of blue litmus paper into a small sample of each drink. The drink that <strong>turns blue litmus paper RED</strong> is the <strong>acidic drink</strong> (serve to customer 1).\n          </div>\n          <div class=\"step\">\n            <strong>2. Identification of the Basic Drink:</strong><br>\n            Dip a strip of red litmus paper into a sample of the remaining drinks. The drink that <strong>turns red litmus paper BLUE</strong> is the <strong>basic drink</strong> (serve to customer 2).\n          </div>\n          <div class=\"step\">\n            <strong>3. Identification of the Neutral Drink:</strong><br>\n            The drink that causes <strong>no colour change</strong> on either red or blue litmus paper is the <strong>neutral drink</strong> (serve to customer 3).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Testing for acidic drink (blue litmus turns red)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Testing for basic drink (red litmus turns blue)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Testing for neutral drink (no colour change on either litmus)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q8 -->\n  <div class=\"q-card\" id=\"q4_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">Explain why:<br>(a) An antacid tablet is taken when you suffer from acidity.<br>(b) Calamine solution is applied on the skin when an ant bites.<br>(c) Factory waste is neutralised before disposing it into the water bodies.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) Antacid for Acidity:</strong> The stomach naturally secretes hydrochloric acid (HCl) to digest food. During indigestion or hyperacidity, excess HCl causes irritation, pain, and burning sensations. Antacid tablets contain a mild, non-toxic base such as <strong>Milk of Magnesia (Magnesium hydroxide)</strong> or aluminium hydroxide. The base neutralises the excess stomach acid, forming salt and water, providing rapid relief:\n            <br>\n            <span class=\"math\">2HCl + Mg(OH)₂ ⎯⎯→ MgCl₂ + 2H₂O</span>\n          </div>\n          <div class=\"step\">\n            <strong>(b) Calamine on Ant Bite:</strong> When an ant stings, it injects acidic <strong>Formic acid (methanoic acid)</strong> into the dermal skin layers, causing burning pain, inflammation, and itching. Calamine solution contains zinc carbonate (ZnCO₃), which is a mild base. Applying calamine neutralises the acidic formic acid, relieving swelling and pain immediately.\n          </div>\n          <div class=\"step\">\n            <strong>(c) Neutralisation of Factory Waste:</strong> Industrial effluents from chemical and manufacturing plants often contain high concentrations of toxic acids or strong alkalis. If discharged directly into rivers, lakes, or oceans, the sharp change in aquatic pH will kill fish, aquatic plants, and beneficial microorganisms. Hence, factories neutralise acidic wastes by adding basic substances (like slaked lime) before safe discharge.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): Neutralisation of excess HCl by magnesium hydroxide</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): Neutralisation of formic acid by zinc carbonate in calamine</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (c): Preventing death of aquatic life from pH shock</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q9 & Q10 & Q11 -->\n  <div class=\"q-card\" id=\"q4_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">Three liquids are given to you. One is hydrochloric acid, another is sodium hydroxide and third is a sugar solution. How will you identify them using only turmeric indicator?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Turmeric paper is naturally bright yellow. It remains <strong>yellow in acidic and neutral solutions</strong>, but turns <strong>reddish-brown in basic solutions</strong>. We can identify all three liquids systematically:</p>\n          <div class=\"step\">\n            <strong>Step 1: Identifying Sodium Hydroxide (Base):</strong><br>\n            Place a drop of each of the three liquids on three separate strips of yellow turmeric paper.<br>\n            The liquid that <strong>turns the yellow turmeric paper REDDISH-BROWN</strong> is <strong>Sodium hydroxide (NaOH)</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Differentiating Acid (HCl) and Neutral (Sugar Solution):</strong><br>\n            Take two separate portions of the reddish-brown turmeric paper (or red-turned paste) created in Step 1:<br>\n            • Add a few drops of the second liquid to one red strip, and the third liquid to the other.<br>\n            • The liquid that <strong>neutralises the base and turns the reddish-brown paper back to YELLOW</strong> is <strong>Hydrochloric acid (HCl)</strong>.<br>\n            • The remaining liquid that causes <strong>no colour change on the red paper</strong> is the <strong>Sugar solution (Neutral)</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of NaOH (turns turmeric yellow to reddish-brown)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of HCl (reverses red turmeric back to yellow via neutralisation)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of sugar solution as remaining neutral liquid</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q4_10\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_10')\">\n      <div class=\"q-num\">Q10</div>\n      <div class=\"q-text\">Blue litmus paper is dipped in a solution. It remains blue. What is the nature of the solution? Explain.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>The solution can be either <strong>Basic</strong> or <strong>Neutral</strong>.</p>\n          <div class=\"step\">\n            <strong>Scientific Explanation:</strong>\n            <ul>\n              <li><strong>Possibility 1 (Basic Solution):</strong> Bases turn red litmus blue and have no effect on blue litmus paper. Therefore, a basic solution will leave blue litmus paper blue.</li>\n              <li><strong>Possibility 2 (Neutral Solution):</strong> Neutral substances (such as pure water, salt solution, sugar solution) cause no colour change on either red or blue litmus paper. Hence, blue litmus paper remains blue in a neutral solution as well.</li>\n            </ul>\n            <em>Confirmation:</em> To definitively distinguish between the two, dip a strip of <strong>red litmus paper</strong> into the solution. If red litmus turns blue, it is basic; if it stays red, it is neutral.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stating both possibilities: Basic or Neutral</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Scientific explanation for both cases + confirmatory test</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q4_11\">\n    <div class=\"q-head\" onclick=\"toggleQ('q4_11')\">\n      <div class=\"q-num\">Q11</div>\n      <div class=\"q-text\">Consider the following statements:<br>(a) Both acids and bases change colour of all indicators.<br>(b) If an indicator gives a colour change with an acid, it does not give a change with a base.<br>(c) If an indicator changes colour with a base, it does not change colour with an acid.<br>(d) Change of colour in an acid and a base depends on the type of the indicator.<br>Which of these statements are correct? (i) All four (ii) a and d (iii) b, c and d (iv) only d</div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (iv) only d</strong></p>\n          <div class=\"step\">\n            <em>Scientific Explanation:</em> Different indicators respond distinctively depending on their unique molecular composition. For instance, litmus changes colour in both acid (red) and base (blue), while turmeric only changes colour in a base (turns red) and remains yellow in acid. Phenolphthalein is colourless in acid and pink in base. Thus, the specific colour change depends entirely on the type and chemical nature of the indicator used.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Option (iv) only d with explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#059669;\">Case Study: Soil Treatment in Agriculture</div>\n        <div class=\"cbq-question\">\n          <strong>Agricultural Case:</strong> A soil testing lab analyzed samples from two different agricultural fields:<br>\n          • <em>Field A:</em> Overused with excessive chemical nitrogenous fertilisers; tested highly acidic (pH 4.8). Crop roots are decaying.<br>\n          • <em>Field B:</em> Located near limestone quarries; tested excessively alkaline (pH 8.9). Nutrients are insoluble.<br><br>\n          (i) What should the farmer add to Field A to treat the soil? Explain the chemical principle.<br>\n          (ii) What should be added to Field B to remediate the alkaline soil?<br>\n          (iii) Why does extreme soil pH prevent healthy crop growth?\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Treatment for Field A (Acidic Soil):</strong> The farmer should treat the soil with bases such as <strong>quicklime (calcium oxide, CaO)</strong> or <strong>slaked lime (calcium hydroxide, Ca(OH)₂)</strong>. The alkaline lime chemically neutralises the excessive soil acidity, raising the pH to an optimal neutral level (~6.5–7).</p>\n          <p><strong>(ii) Treatment for Field B (Basic Soil):</strong> The farmer should add <strong>organic matter (manure or compost)</strong>. As organic manure decays, soil microorganisms release organic acids that neutralise the excessive alkaline bases in the soil.</p>\n          <p><strong>(iii) Biological Reason:</strong> Plants cannot absorb essential minerals (nitrogen, phosphorus, potassium) efficiently when soil is either too acidic or too basic, leading to stunted growth and wilting.</p>\n        </div>\n      </div>\n\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">⚡ Assertion &amp; Reason (HOTS)</div>\n        <div class=\"cbq-question\">\n          <strong>Assertion (A):</strong> When soap is rubbed onto a yellow curry stain on a white shirt, the stain turns reddish-brown.<br>\n          <strong>Reason (R):</strong> Soap solution contains bases (sodium/potassium salts of fatty acids), which react with the natural turmeric indicator present in the curry stain to produce a reddish-brown colour.<br><br>\n          Choose the correct option:<br>\n          (a) Both A and R are true, and R is the correct explanation of A.<br>\n          (b) Both A and R are true, but R is not the correct explanation of A.<br>\n          (c) A is true, but R is false.<br>\n          (d) A is false, but R is true.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>Answer: (a) Both A and R are true, and R is the correct explanation of A.</strong></p>\n          <p><em>Scientific Explanation:</em> Curry contains turmeric, a natural pH indicator. Turmeric contains curcumin, which remains yellow in acidic or neutral mediums but turns reddish-brown at alkaline pH (above 7.5). Washing soap is basic, causing the instantaneous colour change. When rinsed with plenty of acidic lemon water, the yellow color returns.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(3)\">← Chapter 3: Heat</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(5)\">Chapter 5: Physical &amp; Chemical Changes →</button>\n  </div>\n</section>\n","5":"<section class=\"chapter-section\" id=\"ch5\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">5</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 5: Physical and Chemical Changes</h2>\n      <p>NCERT Exercise Solutions — Complete Step-by-Step Answers with CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Scientific Concepts &amp; Chemical Reactions</div>\n    <ul class=\"concept-list\">\n      <li><strong>Physical Changes:</strong> Changes in which only the physical properties (shape, size, state, appearance) of a substance undergo transformation, with <strong>no new chemical substance formed</strong>. Generally temporary and easily reversible. E.g., melting of ice, boiling of water, tearing of paper, dissolution of sugar in water.</li>\n      <li><strong>Chemical Changes (Chemical Reactions):</strong> Changes in which one or more entirely <strong>new substances</strong> with distinct chemical compositions and properties are formed. Irreversible and accompanied by energy changes (heat, light, sound), evolution of gas, change in colour, or precipitate formation. E.g., burning of fuels, rusting of iron, curdling of milk, digestion of food.</li>\n      <li><strong>Classic Laboratory Chemical Reactions:</strong>\n        <ul>\n          <li><em>Burning of Magnesium Ribbon:</em> Burns with a dazzling white flame:\n            <br><span class=\"math\">2Mg (Magnesium) + O₂ (Oxygen) ⎯⎯→ 2MgO (Magnesium oxide - basic ash)</span><br>\n            <span class=\"math\">MgO + H₂O ⎯⎯→ Mg(OH)₂ (Magnesium hydroxide — turns red litmus blue)</span>\n          </li>\n          <li><em>Copper Sulphate and Iron Nail Reaction (Displacement):</em>\n            <br><span class=\"math\">CuSO₄ (Blue solution) + Fe (Iron nail) ⎯⎯→ FeSO₄ (Light green solution) + Cu (Brown deposit on nail)</span>\n          </li>\n          <li><em>Baking Soda and Vinegar Reaction:</em>\n            <br><span class=\"math\">CH₃COOH (Vinegar / Acetic acid) + NaHCO₃ (Baking soda) ⎯⎯→ CO₂ (Carbon dioxide) + H₂O + Sodium acetate</span><br>\n            <span class=\"math\">CO₂ + Ca(OH)₂ (Lime water) ⎯⎯→ CaCO₃ (Insoluble Calcium carbonate, milky) + H₂O</span>\n          </li>\n        </ul>\n      </li>\n      <li><strong>Rusting of Iron:</strong> Corrosion of iron in the simultaneous presence of both <strong>oxygen (air)</strong> and <strong>moisture (water)</strong>:\n        <br><span class=\"math\">4Fe + 3O₂ + 2xH₂O ⎯⎯→ 2Fe₂O₃·xH₂O (Hydrated iron(III) oxide / Rust)</span><br>\n        <em>Prevention:</em> Barrier protection (painting, greasing, oiling), alloying (stainless steel), and <strong>galvanisation</strong> (coating iron with a sacrificial protective layer of molten zinc metal).\n      </li>\n      <li><strong>Crystallisation:</strong> A physical purification technique in which pure, well-defined solid crystals of a substance are separated from its hot, saturated solution upon cooling.</li>\n    </ul>\n  </div>\n\n  <div class=\"ex-div\">NCERT Textbook Exercise Questions</div>\n\n  <!-- Q1 -->\n  <div class=\"q-card\" id=\"q5_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Classify the changes involved in the following processes as physical or chemical changes:<br>(a) Photosynthesis<br>(b) Dissolving sugar in water<br>(c) Burning of coal<br>(d) Melting of wax<br>(e) Beating aluminium to make aluminium foil<br>(f) Digestion of food</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr><th>Process</th><th>Type of Change</th><th>Scientific Rationale</th></tr>\n            </thead>\n            <tbody>\n              <tr><td><strong>(a) Photosynthesis</strong></td><td><strong>Chemical change</strong></td><td>CO₂ and H₂O react in sunlight to form entirely new substances: glucose and oxygen.</td></tr>\n              <tr><td><strong>(b) Dissolving sugar in water</strong></td><td><strong>Physical change</strong></td><td>No new substance is formed; sugar can be recovered unchanged by evaporating the water.</td></tr>\n              <tr><td><strong>(c) Burning of coal</strong></td><td><strong>Chemical change</strong></td><td>Carbon reacts with atmospheric oxygen to form carbon dioxide, ash, and heat irreversibly.</td></tr>\n              <tr><td><strong>(d) Melting of wax</strong></td><td><strong>Physical change</strong></td><td>Solid wax changes state to liquid wax; on cooling, solid wax is reformed with no new substance.</td></tr>\n              <tr><td><strong>(e) Beating aluminium to make foil</strong></td><td><strong>Physical change</strong></td><td>Only shape and thickness of aluminium metal change (malleability); chemical identity remains intact.</td></tr>\n              <tr><td><strong>(f) Digestion of food</strong></td><td><strong>Chemical change</strong></td><td>Complex macromolecules (starch, proteins, fats) are enzymatically broken down into new simple compounds (glucose, amino acids).</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct classification with valid scientific reasoning (0.5 Mark × 6)</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q2 -->\n  <div class=\"q-card\" id=\"q5_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">State whether the following statements are true or false:<br>(a) Cutting a log of wood into pieces is a chemical change. (T/F)<br>(b) Formation of manure from leaves is a physical change. (T/F)<br>(c) Iron pipes coated with zinc do not get rusted easily. (T/F)<br>(d) Iron and rust are the same substance. (T/F)<br>(e) Condensation of steam is not a chemical change. (T/F)</div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) False (F)</strong> — Cutting wood only alters its physical size and dimensions; no new chemical substance is formed (it remains wood). Hence it is a physical change.\n          </div>\n          <div class=\"step\">\n            <strong>(b) False (F)</strong> — Conversion of leaves into manure is biological decomposition by bacteria/fungi forming a new nutrient-rich substance (humus); it is a chemical change.\n          </div>\n          <div class=\"step\">\n            <strong>(c) True (T)</strong> — Coating iron with a layer of zinc (galvanisation) forms a protective barrier preventing air and moisture from contacting the iron.\n          </div>\n          <div class=\"step\">\n            <strong>(d) False (F)</strong> — Iron is a pure grey transition metal element (Fe), while rust is a reddish-brown chemical compound: hydrated iron(III) oxide (Fe₂O₃·xH₂O).\n          </div>\n          <div class=\"step\">\n            <strong>(e) True (T)</strong> — Condensation of steam into liquid water is merely a physical change of state from gas to liquid; water molecules (H₂O) remain unchanged.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct True/False answer with brief rationale (0.5 Mark × 5)</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q3 -->\n  <div class=\"q-card\" id=\"q5_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Fill in the blanks:<br>(a) When carbon dioxide is passed through lime water, it turns milky due to the formation of _________.<br>(b) The chemical name of baking soda is _________.<br>(c) Two methods by which rusting of iron can be prevented are _________ and _________.<br>(d) Changes in which only _________ properties of a substance change are called physical changes.<br>(e) Changes in which new substances are formed are called _________ changes.</div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a)</strong> When carbon dioxide is passed through lime water, it turns milky due to the formation of <strong>calcium carbonate (CaCO₃)</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(b)</strong> The chemical name of baking soda is <strong>sodium hydrogen carbonate</strong> (or sodium bicarbonate, NaHCO₃).\n          </div>\n          <div class=\"step\">\n            <strong>(c)</strong> Two methods by which rusting of iron can be prevented are <strong>painting/greasing</strong> and <strong>galvanisation</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(d)</strong> Changes in which only <strong>physical</strong> properties of a substance change are called physical changes.\n          </div>\n          <div class=\"step\">\n            <strong>(e)</strong> Changes in which new substances are formed are called <strong>chemical</strong> changes.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct blank accurately filled (0.5 Mark × 5)</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q4 -->\n  <div class=\"q-card\" id=\"q5_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">When baking soda is mixed with lemon juice, bubbles are formed with the evolution of a gas. What type of change is it? Explain.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Type of Change:</strong> It is a <strong>Chemical change</strong>.</p>\n          <div class=\"step\">\n            <strong>Scientific Explanation:</strong>\n            <ul>\n              <li>When lemon juice (which contains <strong>citric acid</strong>) reacts with baking soda (<strong>sodium hydrogen carbonate</strong>), a brisk effervescence occurs, releasing a new gas: <strong>carbon dioxide (CO₂)</strong> along with water and sodium citrate salt.</li>\n              <li>Since entirely new chemical substances with distinct properties are produced that cannot be converted back by simple physical means, the reaction is chemical:\n                <br>\n                <span class=\"math\">Lemon juice (Citric acid) + Baking soda (Sodium hydrogen carbonate) ⎯⎯→ Carbon dioxide (bubbles) + Sodium citrate + Water</span>\n              </li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification as a chemical change</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formation of new substance (carbon dioxide gas) with word equation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q5 -->\n  <div class=\"q-card\" id=\"q5_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">When a candle burns, both physical and chemical changes take place. Identify these changes. Give another example of a familiar process in which both physical and chemical changes take place.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. In Burning of a Candle:</strong>\n            <ul>\n              <li><strong>Physical Change:</strong> The heat of the flame melts the solid wax near the wick into liquid wax. When it drips down and cools, it resolidifies into solid wax without changing its chemical composition. This change of state is a <strong>physical change</strong>.</li>\n              <li><strong>Chemical Change:</strong> Molten wax rises through the wick and vaporises; the wax vapour combusts in atmospheric oxygen producing heat, light, carbon dioxide (CO₂), water vapour (H₂O), and soot. These new substances cannot be converted back into wax; hence, it is a <strong>chemical change</strong>.</li>\n            </ul>\n          </div>\n          <div class=\"step\">\n            <strong>2. Another Example Exhibiting Both Changes:</strong>\n            <ul>\n              <li><strong>Digestion of Food in the Human Body:</strong>\n                <ul>\n                  <li><em>Physical Change:</em> Mechanical mastication and grinding of food by teeth into smaller physical pieces in the mouth.</li>\n                  <li><em>Chemical Change:</em> Enzymatic breakdown of complex starch into maltose by saliva and digestion of proteins into amino acids by gastric juices.</li>\n                </ul>\n              </li>\n              <li><em>(Alternative: LPG cylinder usage — physical conversion of liquid LPG into gas as pressure drops, followed by chemical combustion of gas into CO₂ and H₂O).</em></li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Melting of wax identified as physical change</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Burning of wax vapour identified as chemical change</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Another valid example explained (e.g. food digestion or LPG)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q6 -->\n  <div class=\"q-card\" id=\"q5_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">How would you show that setting of curd is a chemical change?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Setting of curd is proven to be a <strong>chemical change</strong> based on the following scientific criteria:</p>\n          <div class=\"step\">\n            <strong>1. Formation of a New Substance:</strong> When a small amount of curd (inoculum) is added to warm milk, the bacterium <em>Lactobacillus</em> ferments lactose sugar present in milk into <strong>lactic acid</strong>. The acid coagulates the milk protein (casein), forming an entirely new chemical substance: curd.\n          </div>\n          <div class=\"step\">\n            <strong>2. Change in Properties:</strong> Curd has a distinctly sour taste, acidic pH, and a thick semi-solid texture completely different from sweet liquid milk.\n          </div>\n          <div class=\"step\">\n            <strong>3. Irreversibility:</strong> Once curd is formed, it cannot be reversed back into milk by any physical separation method.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conversion of lactose to lactic acid by Lactobacillus forming a new substance</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Irreversible nature and altered chemical/taste properties</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q7 -->\n  <div class=\"q-card\" id=\"q5_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Explain why burning of wood and cutting it into small pieces are considered as two different types of changes.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. Cutting of Wood (Physical Change):</strong>\n            <ul>\n              <li>When a wooden log is sawn or chopped into smaller pieces, only its <strong>physical dimensions (size and shape)</strong> are altered.</li>\n              <li>The chemical composition of each wood chip remains identical to the original log (cellulose and lignin).</li>\n              <li>No new chemical substance is formed; therefore, cutting wood is purely a <strong>physical change</strong>.</li>\n            </ul>\n          </div>\n          <div class=\"step\">\n            <strong>2. Burning of Wood (Chemical Change):</strong>\n            <ul>\n              <li>When wood is ignited, the carbon and organic compounds present in the wood chemically react with atmospheric oxygen at high temperatures (combustion).</li>\n              <li>Entirely new chemical substances are formed: <strong>ash, carbon dioxide, carbon monoxide, water vapour, and soot</strong>, alongside the liberation of heat and light.</li>\n              <li>The ash and smoke cannot be recombined to reconstruct the original wood; hence, it is a permanent and irreversible <strong>chemical change</strong>.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Cutting wood: change in size only, no new substance (physical)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Burning wood: combustion forming ash/CO₂ irreversibly (chemical)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q8 -->\n  <div class=\"q-card\" id=\"q5_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">Describe how crystals of copper sulphate are prepared.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Pure, large crystals of copper sulphate (CuSO₄·5H₂O) are prepared through the physical purification process of <strong>Crystallisation</strong>:</p>\n          <div class=\"step\">\n            <strong>Apparatus &amp; Materials:</strong> Beaker, tripod stand, wire gauze, bunsen burner, water, dilute sulphuric acid, copper sulphate powder, filter paper, china dish.\n          </div>\n          <div class=\"step\">\n            <strong>Procedure:</strong>\n            <ol>\n              <li>Take approximately 100 mL of water in a clean beaker and add a few drops of <strong>dilute sulphuric acid</strong> (to prevent hydrolysis).</li>\n              <li>Heat the water over a burner on a tripod stand until it starts boiling.</li>\n              <li>While boiling, add impure copper sulphate powder gradually while stirring continuously with a glass rod.</li>\n              <li>Continue adding copper sulphate powder until no more powder can dissolve; the solution becomes a <strong>saturated solution</strong>.</li>\n              <li>Filter the hot saturated solution using filter paper to remove insoluble solid impurities into a clean china dish.</li>\n              <li>Allow the hot filtrate to cool slowly at room temperature undisturbed. Do not shake, stir, or move the solution while cooling.</li>\n            </ol>\n          </div>\n          <div class=\"step\">\n            <strong>Observation:</strong> After a few hours, beautiful, well-defined, transparent <strong>blue triclinic crystals of copper sulphate</strong> appear at the bottom of the dish.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Heating water with dilute sulphuric acid + preparing saturated solution</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Filtration and slow undisturbed cooling</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Observation of pure blue crystals (physical change)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q9 & Q10 & Q11 & Q12 -->\n  <div class=\"q-card\" id=\"q5_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">Explain how painting of an iron gate prevents it from rusting.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. Conditions for Rusting:</strong> Rusting of iron is a chemical oxidation reaction that strictly requires the concurrent presence of both <strong>oxygen (air)</strong> and <strong>water / moisture</strong>:\n            <br>\n            <span class=\"math\">4Fe + 3O₂ + 2xH₂O ⎯⎯→ 2Fe₂O₃·xH₂O (Rust)</span>\n          </div>\n          <div class=\"step\">\n            <strong>2. Barrier Mechanism of Paint:</strong> Applying a coat of paint over the iron gate creates a continuous, impervious physical barrier. This coating completely cuts off direct contact between the underlying metallic iron atoms and atmospheric moisture and oxygen. In the absence of moisture and air, the oxidation reaction cannot initiate, effectively protecting the iron gate from rusting.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Essential conditions for rusting (air + moisture)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Paint acting as a protective barrier preventing contact with oxygen/water</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_10\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_10')\">\n      <div class=\"q-num\">Q10</div>\n      <div class=\"q-text\">Explain why rusting of iron objects is faster in coastal areas than in deserts.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. High Humidity in Coastal Areas:</strong> Coastal regions (such as Mumbai, Chennai, Kolkata) are surrounded by sea water, creating an atmosphere with very high <strong>relative humidity (moisture content)</strong>. Water vapour readily condenses on iron surfaces, providing the necessary aqueous medium for oxidation.\n          </div>\n          <div class=\"step\">\n            <strong>2. Catalytic Effect of Sea Salts:</strong> Coastal air carries tiny droplets of sea spray containing dissolved salts (primarily sodium chloride, NaCl). Saline water acts as an excellent electrolyte, accelerating the electrochemical corrosion process and causing rapid, severe rusting.\n          </div>\n          <div class=\"step\">\n            <strong>3. Arid Conditions in Deserts:</strong> In contrast, desert areas (such as Thar) have extremely dry, hot air with virtually negligible atmospheric moisture. Without sufficient water vapour, iron cannot readily react with oxygen, making rusting exceptionally slow.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">High humidity + presence of salt in coastal air accelerating corrosion</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Arid, dry conditions in deserts inhibiting rust formation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_11\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_11')\">\n      <div class=\"q-num\">Q11</div>\n      <div class=\"q-text\">The gas we use in the kitchen is called liquefied petroleum gas (LPG). In the cylinder it exists as a liquid. When it comes out from the cylinder it becomes a gas (Change — A) then it burns (Change — B). The following statements pertain to these changes. Choose the correct one:<br>(i) Process — A is a chemical change.<br>(ii) Process — B is a chemical change.<br>(iii) Both processes A and B are chemical changes.<br>(iv) None of these processes is a chemical change.</div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (ii) Process — B is a chemical change.</strong></p>\n          <div class=\"step\">\n            <em>Scientific Explanation:</em>\n            <ul>\n              <li><strong>Process A (Liquid LPG → Gaseous LPG):</strong> As pressure is released from the cylinder valve, liquefied petroleum gas vaporises into gas. This is strictly a <strong>physical change of state</strong>; the chemical molecules (butane and propane) remain identical.</li>\n              <li><strong>Process B (Combustion of Gas):</strong> When ignited over the burner, hydrocarbon gas reacts chemically with atmospheric oxygen to form carbon dioxide, water vapour, heat, and light. This produces entirely new substances and is an irreversible <strong>chemical change</strong>.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Option (ii) with physical vs chemical change distinction</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q5_12\">\n    <div class=\"q-head\" onclick=\"toggleQ('q5_12')\">\n      <div class=\"q-num\">Q12</div>\n      <div class=\"q-text\">Anaerobic bacteria digest animal waste and produce biogas (Change — A). The biogas is then burnt as fuel (Change — B). The following statements pertain to these changes. Choose the correct one:<br>(i) Process — A is a chemical change.<br>(ii) Process — B is a chemical change.<br>(iii) Both processes A and B are chemical changes.<br>(iv) None of these processes is a chemical change.</div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (iii) Both processes A and B are chemical changes.</strong></p>\n          <div class=\"step\">\n            <em>Scientific Explanation:</em>\n            <ul>\n              <li><strong>Process A (Biogas Production):</strong> Anaerobic methanogenic bacteria biochemically digest and decompose organic cow dung / animal waste into methane and carbon dioxide (biogas). This is a biological <strong>chemical change</strong> producing new chemical compounds.</li>\n              <li><strong>Process B (Combustion of Biogas):</strong> The methane in biogas reacts with atmospheric oxygen to produce carbon dioxide, water, and heat energy:\n                <br>\n                <span class=\"math\">CH₄ + 2O₂ ⎯⎯→ CO₂ + 2H₂O + Heat</span>\n                <br>\n                Combustion creates entirely new substances and is also a <strong>chemical change</strong>.\n              </li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Option (iii) Both processes A and B are chemical changes</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#059669;\">Case Study: Displacement Reaction in Iron Nails &amp; Copper Sulphate</div>\n        <div class=\"cbq-question\">\n          <strong>Laboratory Experiment:</strong> Priyanka dissolved a spoonful of blue vitriol (copper sulphate) in 100 mL of water and added a few drops of dilute sulphuric acid. She dropped a clean iron nail into the blue solution and left it undisturbed for 45 minutes.<br><br>\n          (i) What colour change does the solution undergo, and why?<br>\n          (ii) What observation is recorded on the surface of the iron nail?<br>\n          (iii) Write the complete word and chemical equation for this reaction.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Colour Shift of Solution:</strong> The solution changes from its initial <strong>deep blue</strong> to a <strong>light green</strong> colour. This occurs because iron is chemically more reactive than copper; it displaces copper from copper sulphate solution to form <strong>iron(II) sulphate (ferrous sulphate, FeSO₄)</strong>, which is light green.</p>\n          <p><strong>(ii) Surface of Iron Nail:</strong> A distinct <strong>reddish-brown powdery coating</strong> is deposited on the submerged portion of the iron nail. This reddish-brown coating is pure metallic copper (Cu) displaced from the solution.</p>\n          <p><strong>(iii) Equation:</strong><br>\n            <span class=\"math\">Copper sulphate solution (Blue) + Iron (Nail) ⎯⎯→ Iron sulphate solution (Light green) + Copper (Brown deposit)</span><br>\n            <span class=\"math\">CuSO₄ (aq) + Fe (s) ⎯⎯→ FeSO₄ (aq) + Cu (s)</span>\n          </p>\n        </div>\n      </div>\n\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">⚡ Assertion &amp; Reason (HOTS)</div>\n        <div class=\"cbq-question\">\n          <strong>Assertion (A):</strong> Ships operating in sea water require frequent replacement of sacrificial zinc blocks attached to their steel hulls.<br>\n          <strong>Reason (R):</strong> Zinc is more reactive than iron, so it corrodes preferentially (sacrificial protection), preventing the steel ship hull from rusting in saline ocean water.<br><br>\n          Choose the correct option:<br>\n          (a) Both A and R are true, and R is the correct explanation of A.<br>\n          (b) Both A and R are true, but R is not the correct explanation of A.<br>\n          (c) A is true, but R is false.<br>\n          (d) A is false, but R is true.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>Answer: (a) Both A and R are true, and R is the correct explanation of A.</strong></p>\n          <p><em>Scientific Explanation:</em> Saline ocean water acts as a strong electrolyte, dramatically accelerating iron corrosion. Large zinc blocks bolted to the submerged steel hull undergo galvanic sacrificial oxidation (zinc oxidises to Zn²⁺ instead of Fe to Fe³⁺). Once the zinc blocks are completely consumed, they must be renewed to safeguard the ship structure.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(4)\">← Chapter 4: Acids, Bases &amp; Salts</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(6)\">Chapter 6: Respiration in Organisms →</button>\n  </div>\n</section>\n","6":"<section class=\"chapter-section\" id=\"ch6\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">6</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 6: Respiration in Organisms</h2>\n      <p>NCERT Exercise Solutions — Complete Step-by-Step Answers with CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Scientific Concepts &amp; Respiratory Mechanisms</div>\n    <ul class=\"concept-list\">\n      <li><strong>Cellular Respiration:</strong> The intracellular biochemical breakdown of glucose in the presence or absence of oxygen to release usable biological energy (stored as ATP):\n        <ul>\n          <li><em>Aerobic Respiration:</em> Occurs in the presence of oxygen; completely oxidises glucose into carbon dioxide, water, and 36–38 ATP molecules:\n            <br><span class=\"math\">Glucose + Oxygen ⎯⎯→ Carbon dioxide (6CO₂) + Water (6H₂O) + Energy (38 ATP)</span>\n          </li>\n          <li><em>Anaerobic Respiration in Yeast (Fermentation):</em> In the absence of oxygen, glucose is partially broken down into ethyl alcohol, carbon dioxide, and 2 ATP molecules:\n            <br><span class=\"math\">Glucose ⎯⎯[In absence of O₂]⎯⎯→ Ethyl alcohol (2C₂H₅OH) + Carbon dioxide (2CO₂) + Energy (2 ATP)</span>\n          </li>\n          <li><em>Anaerobic Respiration in Human Skeletal Muscles:</em> Occurs during intense exercise when oxygen supply falls short of muscular demand; produces lactic acid:\n            <br><span class=\"math\">Glucose ⎯⎯[In absence of O₂]⎯⎯→ Lactic acid (2C₃H₆O₃) + Energy (2 ATP)</span>\n            <br>Accumulation of lactic acid causes painful <strong>muscle cramps</strong>. Relief is obtained through a hot bath or massage, which improves blood circulation and oxygen supply to oxidise lactic acid into CO₂ and H₂O.\n          </li>\n        </ul>\n      </li>\n      <li><strong>Breathing Mechanism in Humans:</strong>\n        <ul>\n          <li><em>Inhalation (Inspiration):</em> Diaphragm contracts and flattens downwards; ribcage moves upwards and outwards. Chest cavity volume increases, lowering air pressure in lungs. Atmospheric air rushes in through nostrils → pharynx → trachea → bronchi → lungs.</li>\n          <li><em>Exhalation (Expiration):</em> Diaphragm relaxes and curves upwards into dome shape; ribcage moves downwards and inwards. Chest cavity volume decreases, increasing lung air pressure, forcing air out.</li>\n        </ul>\n      </li>\n      <li><strong>Respiration in Diverse Organisms:</strong>\n        <ul>\n          <li><em>Insects (Cockroach):</em> Network of air tubes called <strong>tracheae</strong> opening through small exterior holes called <strong>spiracles</strong>.</li>\n          <li><em>Earthworm:</em> Breathes through moist, slimy, vascular <strong>skin</strong> (cutaneous respiration).</li>\n          <li><em>Fish:</em> Breathes dissolved oxygen in water through comb-like, highly vascularised <strong>gills</strong>.</li>\n          <li><em>Frogs:</em> Dual breathing: through moist skin in water and through a pair of lungs on land.</li>\n          <li><em>Plants:</em> Stomata on leaves and lenticels on bark for gaseous exchange; root hairs absorb oxygen from air spaces between soil particles.</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n\n  <div class=\"ex-div\">NCERT Textbook Exercise Questions</div>\n\n  <!-- Q1 -->\n  <div class=\"q-card\" id=\"q6_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Why does an athlete breathe faster and deeper than usual after finishing the race?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. High Energy &amp; Oxygen Debt:</strong> During a fast running race, the athlete's leg muscle cells demand immense amounts of energy. Since the oxygen supplied through normal breathing is insufficient, muscle cells respire <strong>anaerobically</strong>, producing <strong>lactic acid</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>2. Repaying the Oxygen Debt:</strong> After crossing the finish line, the athlete must breathe much faster and deeper to inhale extra oxygen (repaying the \"oxygen debt\"). This excess oxygen is transported by blood to the muscle cells to completely oxidise and breakdown the accumulated lactic acid into harmless <strong>carbon dioxide and water</strong>, relieving muscular fatigue.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Anaerobic respiration in muscles producing lactic acid during the race</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Faster breathing providing excess oxygen to break down lactic acid</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q2 -->\n  <div class=\"q-card\" id=\"q6_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">List the similarities and differences between aerobic and anaerobic respiration.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Similarities:</strong>\n            <ul>\n              <li>In both types, <strong>glucose</strong> serves as the primary cellular fuel substrate to produce usable energy.</li>\n              <li>Both processes take place inside living cells through enzyme-catalysed biochemical reactions.</li>\n              <li>Both types generate energy stored chemically in <strong>ATP</strong> molecules.</li>\n            </ul>\n          </div>\n          <div class=\"step\">\n            <strong>Differences:</strong>\n            <table class=\"data-table\">\n              <thead>\n                <tr><th>Feature</th><th>Aerobic Respiration</th><th>Anaerobic Respiration</th></tr>\n              </thead>\n              <tbody>\n                <tr>\n                  <td><strong>Presence of Oxygen</strong></td>\n                  <td>Occurs strictly in the <strong>presence of oxygen</strong> (O₂).</td>\n                  <td>Occurs in the <strong>absence of oxygen</strong>.</td>\n                </tr>\n                <tr>\n                  <td><strong>Breakdown of Glucose</strong></td>\n                  <td>Complete oxidation of glucose molecules.</td>\n                  <td>Incomplete/partial breakdown of glucose.</td>\n                </tr>\n                <tr>\n                  <td><strong>End Products</strong></td>\n                  <td>Carbon dioxide (CO₂) and Water (H₂O).</td>\n                  <td>Ethyl alcohol + CO₂ (in yeast) OR Lactic acid (in human muscles).</td>\n                </tr>\n                <tr>\n                  <td><strong>Energy Yield</strong></td>\n                  <td>Releases a large amount of energy (~38 ATP per glucose molecule).</td>\n                  <td>Releases very little energy (only 2 ATP per glucose molecule).</td>\n                </tr>\n                <tr>\n                  <td><strong>Occurrence</strong></td>\n                  <td>Most plants, animals, and human cells.</td>\n                  <td>Yeast, certain bacteria, and fatigued human muscle cells.</td>\n                </tr>\n              </tbody>\n            </table>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">At least two valid similarities (fuel glucose, ATP generation)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Differences in oxygen requirement, end products and energy yield</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q3 -->\n  <div class=\"q-card\" id=\"q6_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Why do we often sneeze when we inhale a lot of dust-laden air?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. Nasal Defence Mechanism:</strong> The human nasal cavity is lined with fine hairs (cilia) and sticky mucus designed to trap airborne dust particles, pollen, smoke, and microbes.\n          </div>\n          <div class=\"step\">\n            <strong>2. Irritation &amp; Reflex Action:</strong> When we inhale air laden with heavy dust, some particles bypass the nasal hairs and directly irritate the delicate, sensitive inner mucosal lining of the nasal cavity.\n          </div>\n          <div class=\"step\">\n            <strong>3. Sneeze Expulsion:</strong> This irritation instantly triggers an involuntary protective reflex known as a <strong>sneeze</strong>. A forceful blast of air is expelled through the nose and mouth, violently dislodging and expelling the foreign irritant particles so that only clean, filtered air enters the delicate lungs.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Foreign dust particles irritating the mucosal lining of nasal cavity</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Sneezing as a protective reflex expelling irritants to safeguard lungs</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q4 -->\n  <div class=\"q-card\" id=\"q6_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Take three test-tubes. Fill 3/4th of each with water. Label them A, B and C. Keep a snail in test-tube A, a water plant in test-tube B and in C, keep snail and plant both. Which test-tube would have the highest concentration of CO₂?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Test-tube A</strong> will have the <strong>highest concentration of Carbon Dioxide (CO₂)</strong>.</p>\n          <div class=\"step\">\n            <strong>Scientific Analysis:</strong>\n            <ul>\n              <li><strong>In Test-tube A (Snail only):</strong> The snail performs only respiration; it continuously absorbs dissolved oxygen (O₂) and releases carbon dioxide (CO₂) into the water. Since there is no green plant to utilise the CO₂, carbon dioxide accumulates progressively, reaching the highest concentration.</li>\n              <li><strong>In Test-tube B (Water Plant only):</strong> The aquatic plant carries out both respiration and photosynthesis. In the presence of light, the rate of photosynthesis is far higher than respiration; the plant rapidly consumes CO₂ from the water to make food, resulting in the lowest CO₂ level.</li>\n              <li><strong>In Test-tube C (Snail + Water Plant):</strong> The CO₂ exhaled by the snail is actively absorbed and utilised by the water plant for photosynthesis, while the O₂ released by the plant is used by the snail for respiration. A biological equilibrium is maintained, so CO₂ concentration remains moderate.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identifying Test-tube A with highest CO₂ concentration</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation for Test-tube A (only CO₂ release, no consumer)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Comparative explanation for Test-tubes B and C (photosynthesis utilisation)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q5 -->\n  <div class=\"q-card\" id=\"q6_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Tick the correct answer:<br>(a) In cockroaches, air enters the body through: (i) lungs (ii) gills (iii) spiracles (iv) skin<br>(b) During heavy exercise, we get cramps in the legs due to the accumulation of: (i) carbon dioxide (ii) lactic acid (iii) alcohol (iv) water<br>(c) Normal range of breathing rate per minute in an average adult person at rest is: (i) 9–12 (ii) 15–18 (iii) 21–24 (iv) 30–33<br>(d) During exhalation, the ribs: (i) move outwards (ii) move downwards (iii) move upwards (iv) do not move at all</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) (iii) spiracles</strong> — Small lateral openings along the sides of the cockroach's body connected to tracheal air tubes.\n          </div>\n          <div class=\"step\">\n            <strong>(b) (ii) lactic acid</strong> — Produced by anaerobic breakdown of glucose when muscular oxygen demand outstrips supply.\n          </div>\n          <div class=\"step\">\n            <strong>(c) (ii) 15–18</strong> — An average resting adult human breathes 15 to 18 times per minute (one breath = one inhalation + one exhalation).\n          </div>\n          <div class=\"step\">\n            <strong>(d) (ii) move downwards</strong> — During exhalation, the ribs move downwards and inwards while the diaphragm arches upwards into a dome shape.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct option chosen (0.5 Mark × 4)</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q6 -->\n  <div class=\"q-card\" id=\"q6_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">Match the items in Column I with those in Column II:<br>\n        <strong>Column I:</strong> (a) Yeast, (b) Diaphragm, (c) Skin, (d) Leaves, (e) Fish, (f) Frog<br>\n        <strong>Column II:</strong> (i) Earthworm, (ii) Gills, (iii) Alcohol, (iv) Chest cavity, (v) Stomata, (vi) Lungs and skin, (vii) Tracheae\n      </div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr><th>Column I</th><th>Column II</th><th>Scientific Rationale</th></tr>\n            </thead>\n            <tbody>\n              <tr><td><strong>(a) Yeast</strong></td><td><strong>(iii) Alcohol</strong></td><td>Anaerobic fermentation by yeast converts sugar into ethanol and CO₂.</td></tr>\n              <tr><td><strong>(b) Diaphragm</strong></td><td><strong>(iv) Chest cavity</strong></td><td>Muscular sheet forming the flexible floor of the thoracic (chest) cavity.</td></tr>\n              <tr><td><strong>(c) Skin</strong></td><td><strong>(i) Earthworm</strong></td><td>Cutaneous respiration through thin, vascularised, mucus-moistened skin.</td></tr>\n              <tr><td><strong>(d) Leaves</strong></td><td><strong>(v) Stomata</strong></td><td>Microscopic pores on leaf epidermis for gaseous exchange.</td></tr>\n              <tr><td><strong>(e) Fish</strong></td><td><strong>(ii) Gills</strong></td><td>Feathery, blood-rich filaments extracting dissolved oxygen from water.</td></tr>\n              <tr><td><strong>(f) Frog</strong></td><td><strong>(vi) Lungs and skin</strong></td><td>Amphibian breathing through moist skin in water and lungs on land.</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct matching pair (0.5 Mark × 6)</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q7 & Q8 & Q9 -->\n  <div class=\"q-card\" id=\"q6_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Mark 'T' if the statement is true and 'F' if it is false:<br>(i) During heavy exercise the breathing rate of a person slows down. (T/F)<br>(ii) Plants carry out photosynthesis only during the day and respiration only at night. (T/F)<br>(iii) Frogs breathe through their skins as well as their lungs. (T/F)<br>(iv) The fishes have lungs for respiration. (T/F)<br>(v) The size of the chest cavity increases during inhalation. (T/F)</div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) False (F)</strong> — During heavy exercise, breathing rate speeds up drastically (up to 25 breaths/min) to meet higher energy demands.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) False (F)</strong> — Respiration is continuous (24 hours, day and night) in all living cells to stay alive; photosynthesis occurs only during the daytime when sunlight is present.\n          </div>\n          <div class=\"step\">\n            <strong>(iii) True (T)</strong> — Adult frogs possess lungs on land and breathe through their moist, permeable skin in water.\n          </div>\n          <div class=\"step\">\n            <strong>(iv) False (F)</strong> — Fishes breathe through <strong>gills</strong>, which are specialised to extract dissolved oxygen from water.\n          </div>\n          <div class=\"step\">\n            <strong>(v) True (T)</strong> — Outward rib movement and downward diaphragm contraction enlarge the thoracic cavity volume during inhalation.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with brief rationale (0.5 Mark × 5)</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q6_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">Find the respiratory terms for: (i) Air tubes of insects, (ii) Skeletal structures surrounding chest cavity, (iii) Muscular floor of chest cavity, (iv) Tiny pores on the surface of leaf, (v) Small openings on the sides of the body of an insect, (vi) The respiratory organs of human beings.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) Air tubes of insects:</strong> <strong>Tracheae</strong>\n          </div>\n          <div class=\"step\">\n            <strong>(ii) Skeletal structures surrounding chest cavity:</strong> <strong>Ribs</strong> (Ribcage)\n          </div>\n          <div class=\"step\">\n            <strong>(iii) Muscular floor of chest cavity:</strong> <strong>Diaphragm</strong>\n          </div>\n          <div class=\"step\">\n            <strong>(iv) Tiny pores on the surface of leaf:</strong> <strong>Stomata</strong>\n          </div>\n          <div class=\"step\">\n            <strong>(v) Small openings on the sides of the body of an insect:</strong> <strong>Spiracles</strong>\n          </div>\n          <div class=\"step\">\n            <strong>(vi) The respiratory organs of human beings:</strong> <strong>Lungs</strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct anatomical term (0.5 Mark × 6)</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q6_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q6_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">The mountaineers carry oxygen with them because: (a) At an altitude of more than 5 km there is no air. (b) The amount of air available to a person is less than that available on the ground. (c) The temperature of air is higher than that on the ground. (d) The pressure of air is higher than that on the ground.</div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (b) The amount of air available to a person is less than that available on the ground.</strong></p>\n          <div class=\"step\">\n            <em>Scientific Explanation:</em> As altitude increases, atmospheric density and atmospheric pressure drop significantly. The air becomes thin (rarefied), meaning there are fewer oxygen molecules per unit volume of air. To prevent hypoxia (oxygen deficiency in tissues and brain), mountaineers must carry portable compressed oxygen cylinders.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Option (b) with altitude atmospheric pressure explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#059669;\">Case Study: Investigating Exhaled Air with Lime Water</div>\n        <div class=\"cbq-question\">\n          <strong>Experiment:</strong> Rohan set up a clean glass test tube filled with freshly prepared clear lime water [calcium hydroxide, Ca(OH)₂]. Using a clean plastic straw, he gently blew his exhaled breath into the lime water for about 30 seconds.<br><br>\n          (i) What change in appearance of the lime water is observed?<br>\n          (ii) Write the chemical equation explaining this observation.<br>\n          (iii) What does this test prove regarding the composition of exhaled air compared to inhaled air?\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Observation:</strong> The clear lime water turns cloudy and <strong>milky white</strong>.</p>\n          <p><strong>(ii) Chemical Equation:</strong> Carbon dioxide in exhaled breath chemically reacts with calcium hydroxide to form an insoluble white precipitate of <strong>calcium carbonate (CaCO₃)</strong>:\n            <br>\n            <span class=\"math\">Ca(OH)₂ (aq) [Lime water] + CO₂ (g) [In exhaled breath] ⎯⎯→ CaCO₃ (s) [White precipitate] + H₂O (l)</span>\n          </p>\n          <p><strong>(iii) Scientific Conclusion:</strong> Inhaled air contains only 0.04% carbon dioxide, whereas exhaled air contains approximately <strong>4.4% carbon dioxide</strong>. This proves conclusively that cellular respiration produces CO₂ as an excretory metabolic byproduct released via the lungs.</p>\n        </div>\n      </div>\n\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">⚡ Assertion &amp; Reason (HOTS)</div>\n        <div class=\"cbq-question\">\n          <strong>Assertion (A):</strong> Taking a hot water bath or getting an oil massage provides quick relief from painful muscle cramps after a strenuous gym workout.<br>\n          <strong>Reason (R):</strong> Hot water baths improve systemic blood circulation, which enhances oxygen delivery to muscle cells to completely oxidise accumulated lactic acid into carbon dioxide and water.<br><br>\n          Choose the correct option:<br>\n          (a) Both A and R are true, and R is the correct explanation of A.<br>\n          (b) Both A and R are true, but R is not the correct explanation of A.<br>\n          (c) A is true, but R is false.<br>\n          (d) A is false, but R is true.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>Answer: (a) Both A and R are true, and R is the correct explanation of A.</strong></p>\n          <p><em>Scientific Explanation:</em> Muscular cramps stem from the intracellular accumulation of lactic acid under anaerobic conditions. Heat from a warm bath dilates blood vessels (vasodilation), increasing blood flow and flushing muscles with fresh oxygen-rich blood, enabling aerobic enzymes to convert lactic acid back into CO₂ and H₂O.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(5)\">← Chapter 5: Physical &amp; Chemical Changes</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(7)\">Chapter 7: Transportation in Animals &amp; Plants →</button>\n  </div>\n</section>\n","7":"<section class=\"chapter-section\" id=\"ch7\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">7</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 7: Transportation in Animals and Plants</h2>\n      <p>NCERT Exercise Solutions — Complete Step-by-Step Answers with CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Scientific Concepts &amp; Circulatory / Vascular Systems</div>\n    <ul class=\"concept-list\">\n      <li><strong>Human Circulatory System:</strong>\n        <ul>\n          <li><em>Blood Composition:</em> Liquid matrix called <strong>plasma</strong> containing <strong>Red Blood Cells (RBCs)</strong> with iron-rich <strong>haemoglobin</strong> for oxygen transport; <strong>White Blood Cells (WBCs)</strong> that destroy invading pathogens; and <strong>Platelets</strong> essential for blood clotting to prevent haemorrhage.</li>\n          <li><em>Blood Vessels:</em> <strong>Arteries</strong> carry oxygenated blood away from the heart at high pressure (thick, elastic walls, no valves; exception: pulmonary artery); <strong>Veins</strong> carry deoxygenated blood towards the heart at low pressure (thin walls, possess internal pocket valves preventing backflow; exception: pulmonary vein); <strong>Capillaries</strong> are microscopic single-cell-thick vessels facilitating nutrient and gas exchange.</li>\n          <li><em>Heart:</em> A hollow, muscular organ roughly the size of a fist, divided into 4 chambers (Right Atrium, Right Ventricle, Left Atrium, Left Ventricle) separated by a muscular septum to completely prevent mixing of oxygen-rich and carbon dioxide-rich blood.</li>\n        </ul>\n      </li>\n      <li><strong>Human Excretory System:</strong>\n        Consists of a pair of bean-shaped <strong>Kidneys</strong> (filter blood), tube-like <strong>Ureters</strong>, a muscular <strong>Urinary Bladder</strong> (stores urine), and a terminal <strong>Urethra</strong> with an opening. Normal human urine composition: ~95% water, 2.5% urea, 2.5% other toxic metabolic salts. In kidney failure, blood is cleansed periodically using an artificial kidney through <strong>dialysis</strong>.\n      </li>\n      <li><strong>Vascular Transport in Plants:</strong>\n        <ul>\n          <li><em>Xylem:</em> Continuous tubular network conducting water and dissolved mineral salts unidirectionally from roots upwards to the leaves.</li>\n          <li><em>Phloem:</em> Living vascular tissue translocating food (sugars synthesized by leaves) bidirectionally to all parts of the plant.</li>\n          <li><em>Transpiration:</em> Evaporation of water vapour from leaf stomata. Generates a powerful <strong>suction pull (transpirational pull)</strong> capable of lifting water columns over 100 metres high in giant trees, while cooling the plant.</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n\n  <div class=\"ex-div\">NCERT Textbook Exercise Questions</div>\n\n  <!-- Q1 -->\n  <div class=\"q-card\" id=\"q7_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Match structures given in Column I with functions given in Column II:<br>\n        <strong>Column I:</strong> (i) Stomata, (ii) Xylem, (iii) Root hairs, (iv) Phloem<br>\n        <strong>Column II:</strong> (a) Absorption of water, (b) Transpiration, (c) Transport of food, (d) Transport of water, (e) Synthesis of carbohydrates\n      </div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr><th>Column I (Plant Tissue/Structure)</th><th>Column II (Physiological Function)</th></tr>\n            </thead>\n            <tbody>\n              <tr><td><strong>(i) Stomata</strong></td><td><strong>(b) Transpiration</strong> (and gaseous exchange)</td></tr>\n              <tr><td><strong>(ii) Xylem</strong></td><td><strong>(d) Transport of water</strong> and dissolved minerals</td></tr>\n              <tr><td><strong>(iii) Root hairs</strong></td><td><strong>(a) Absorption of water</strong> by increasing root surface area</td></tr>\n              <tr><td><strong>(iv) Phloem</strong></td><td><strong>(c) Transport of food</strong> (translocation of sugars)</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct matching pair (0.5 Mark × 4)</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q2 -->\n  <div class=\"q-card\" id=\"q7_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Fill in the blanks:<br>(i) The blood from the heart is transported to all parts of the body by the _________.<br>(ii) Haemoglobin is present in _________ cells.<br>(iii) Arteries and veins are joined by a network of _________.<br>(iv) The rhythmic expansion and contraction of the heart is called _________.<br>(v) The main excretory product in human beings is _________.<br>(vi) Sweat contains water and _________.<br>(vii) Kidneys eliminate the waste materials in the liquid form called _________.<br>(viii) Water reaches great heights in the trees because of suction pull caused by _________.</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i)</strong> The blood from the heart is transported to all parts of the body by the <strong>arteries</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(ii)</strong> Haemoglobin is present in <strong>red blood</strong> cells (RBCs).\n          </div>\n          <div class=\"step\">\n            <strong>(iii)</strong> Arteries and veins are joined by a network of <strong>capillaries</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(iv)</strong> The rhythmic expansion and contraction of the heart is called <strong>heartbeat</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(v)</strong> The main excretory product in human beings is <strong>urea</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(vi)</strong> Sweat contains water and <strong>salts</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(vii)</strong> Kidneys eliminate the waste materials in the liquid form called <strong>urine</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>(viii)</strong> Water reaches great heights in the trees because of suction pull caused by <strong>transpiration</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct blank (0.5 Mark × 8)</span><span class=\"marking-marks\">4 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q3 -->\n  <div class=\"q-card\" id=\"q7_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Choose the correct option:<br>(a) In plants, water is transported through: (i) xylem (ii) phloem (iii) stomata (iv) root hair<br>(b) Water absorption through roots can be increased by keeping the plants: (i) in the shade (ii) in dim light (iii) under the fan (iv) covered with a polythene bag</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) (i) xylem</strong><br>\n            <em>Reason:</em> Xylem vessels form a continuous microscopic pipeline from roots through stem into leaf veins to transport water and dissolved minerals upwards.\n          </div>\n          <div class=\"step\">\n            <strong>(b) (iii) under the fan</strong><br>\n            <em>Reason:</em> Air movement from the running fan blows away humid air around the leaves, increasing the rate of evaporation (transpiration). The increased transpiration creates a stronger suction pull, causing the roots to absorb water from the soil much faster.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (a): (i) xylem</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (b): (iii) under the fan with transpiration pull explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q4 -->\n  <div class=\"q-card\" id=\"q7_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Why is transport of materials necessary in a plant or in an animal? Explain.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Transportation of materials is fundamentally essential for the survival and homeostasis of multicellular organisms for the following reasons:</p>\n          <div class=\"step\">\n            <strong>1. Distribution of Nutrients and Water:</strong>\n            <ul>\n              <li><em>In Plants:</em> Water and minerals absorbed by underground roots must reach leaves for photosynthesis. The glucose prepared by green leaves must be translocated to non-photosynthetic roots, fruits, and growing buds for energy.</li>\n              <li><em>In Animals:</em> Digested nutrients from the intestines must be distributed by blood to trillions of cells across the entire body for cellular respiration and tissue growth.</li>\n            </ul>\n          </div>\n          <div class=\"step\">\n            <strong>2. Respiratory Gas Exchange:</strong> Oxygen inhaled by the lungs must be carried to all tissues to oxidise food, while carbon dioxide generated during metabolism must be transported back to lungs for expulsion.\n          </div>\n          <div class=\"step\">\n            <strong>3. Elimination of Toxic Waste Products:</strong> Cellular metabolism constantly generates toxic nitrogenous byproducts (such as urea and uric acid). An internal circulatory system carries these poisons to excretory organs (kidneys) for filtering and disposal. Without transport, cells would die from toxic accumulation.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Transport of water and food nutrients in plants and animals</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Transport of respiratory gases (O₂ and CO₂)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Transport of toxic metabolic wastes to excretory organs</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q5 -->\n  <div class=\"q-card\" id=\"q7_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">What will happen if there are no platelets in the blood?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. Inability to Clot:</strong> Blood platelets (thrombocytes) are specialised cellular fragments responsible for <strong>blood coagulation (clotting)</strong>. When an injury or cut occurs, platelets rupture and release clotting factors that convert soluble fibrinogen into a dark meshwork of insoluble fibrin fibres, forming a dark red clot that seals the wound.\n          </div>\n          <div class=\"step\">\n            <strong>2. Fatal Consequence:</strong> If there are no platelets in the blood, bleeding from even a minor scratch or cut will <strong>not stop</strong>. Continuous, unchecked haemorrhage will cause severe blood loss, drop in blood pressure, organ failure, and eventual death.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Platelets responsible for blood coagulation and clot formation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Continuous bleeding leading to excessive blood loss and fatal outcome</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q6 -->\n  <div class=\"q-card\" id=\"q7_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">What are stomata? Give two functions of stomata.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Definition:</strong> <strong>Stomata</strong> (singular: <em>stoma</em>) are tiny microscopic pores present predominantly on the epidermal surface of plant leaves. Each pore is flanked and regulated by a pair of kidney-shaped (or bean-shaped) <strong>guard cells</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>Two Primary Functions:</strong>\n            <ol>\n              <li><strong>Exchange of Gases:</strong> They allow the diffusion of carbon dioxide (CO₂) from the atmosphere into the leaf for photosynthesis and the release of oxygen (O₂) into the atmosphere. They also facilitate respiration.</li>\n              <li><strong>Transpiration:</strong> They allow the evaporation of excess water in the form of water vapour, generating a powerful transpirational suction pull to transport water and cooling the plant.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of stomata and guard cells</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Two functions: gaseous exchange and transpiration</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q7 -->\n  <div class=\"q-card\" id=\"q7_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Does transpiration serve any useful function in the plants? Explain.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Yes</strong>, although plants lose more than 95% of absorbed water through transpiration, it is a \"necessary physiological process\" serving several indispensable functions:</p>\n          <div class=\"step\">\n            <strong>1. Generation of Transpirational Pull:</strong> As water evaporates through leaf stomata, it creates negative hydrostatic pressure (suction force) at the top of xylem columns. Similar to sucking liquid through a straw, this powerful transpirational pull lifts continuous columns of water and dissolved minerals from the roots to the highest tips of tall trees.\n          </div>\n          <div class=\"step\">\n            <strong>2. Mineral Uptake and Distribution:</strong> Mineral ions dissolved in soil water (nitrates, phosphates, potassium) are drawn upwards and distributed throughout the plant via transpirational stream.\n          </div>\n          <div class=\"step\">\n            <strong>3. Evaporative Cooling Effect:</strong> The evaporation of water absorbs latent heat from leaf tissues, lowering leaf temperatures by 2°C to 5°C. This prevents thermal shock and enzyme denaturing under scorching direct sunlight.\n          </div>\n          <div class=\"step\">\n            <strong>4. Maintaining Cell Turgidity:</strong> Transpiration ensures a steady water flow that keeps plant cells turgid, maintaining upright plant posture and leaf shape.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Generating suction pull for ascent of sap in xylem</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Evaporative cooling effect safeguarding delicate leaf enzymes</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Transport of dissolved mineral salts and turgidity maintenance</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q8 -->\n  <div class=\"q-card\" id=\"q7_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">What are the components of blood?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Blood is a specialised fluid connective tissue composed of four primary components:</p>\n          <div class=\"step\">\n            <strong>1. Plasma:</strong> The straw-coloured, fluid liquid matrix constituting about 55% of total blood volume. It consists of 90–92% water with dissolved nutrients (glucose, amino acids), proteins, salts, hormones, and waste materials (carbon dioxide, urea).\n          </div>\n          <div class=\"step\">\n            <strong>2. Red Blood Cells (RBCs / Erythrocytes):</strong> Biconcave disc-shaped cells packed with an iron-containing respiratory pigment called <strong>haemoglobin</strong>. Haemoglobin binds reversibly with oxygen to form oxyhaemoglobin, transporting oxygen from lungs to all body tissues.\n          </div>\n          <div class=\"step\">\n            <strong>3. White Blood Cells (WBCs / Leucocytes):</strong> Defence cells that form the body's immune system. They patrol the bloodstream, engulf foreign bacteria, and produce antibodies to neutralise pathogens and fight off infections.\n          </div>\n          <div class=\"step\">\n            <strong>4. Platelets (Thrombocytes):</strong> Tiny, disc-shaped cell fragments produced in bone marrow that initiate blood coagulation (clotting) at the site of a cut or injury to prevent fatal blood loss.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Plasma: fluid matrix transporting nutrients/wastes</span><span class=\"marking-marks\">0.75 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">RBCs: containing haemoglobin for oxygen transport</span><span class=\"marking-marks\">0.75 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">WBCs: fighting germs/infections</span><span class=\"marking-marks\">0.75 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Platelets: responsible for blood clotting</span><span class=\"marking-marks\">0.75 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q9 & Q10 & Q11 & Q12 & Q13 -->\n  <div class=\"q-card\" id=\"q7_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">Why is blood needed by all the parts of a body?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Blood is the vital circulating river of life required by every living cell because:</p>\n          <div class=\"step\">\n            <strong>1. Delivery of Oxygen:</strong> Every cell requires oxygen continuously to metabolise glucose during cellular respiration; blood carries oxygen from lungs to all peripheral organs.\n          </div>\n          <div class=\"step\">\n            <strong>2. Distribution of Digested Nutrients:</strong> It transports glucose, amino acids, fatty acids, vitamins, and minerals absorbed from the small intestine to nourish all body tissues.\n          </div>\n          <div class=\"step\">\n            <strong>3. Waste Removal:</strong> It picks up harmful carbon dioxide and nitrogenous wastes (urea) from cells and transports them to the lungs and kidneys for disposal.\n          </div>\n          <div class=\"step\">\n            <strong>4. Protection &amp; Regulation:</strong> It carries antibodies and WBCs to fight infections and distributes heat to regulate uniform body temperature (37°C).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Supplying oxygen and nutrients to all cells</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Collecting CO₂/wastes and maintaining body temperature</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_10\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_10')\">\n      <div class=\"q-num\">Q10</div>\n      <div class=\"q-text\">What makes the blood look red?</div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Blood appears bright red due to the presence of a specialised iron-containing protein pigment called <strong>Haemoglobin</strong> located inside Red Blood Cells (RBCs). When haemoglobin binds with oxygen in the lungs, it forms bright scarlet-red <strong>oxyhaemoglobin</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Presence of iron pigment haemoglobin in RBCs</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_11\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_11')\">\n      <div class=\"q-num\">Q11</div>\n      <div class=\"q-text\">Describe the function of the heart.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>The human <strong>heart</strong> acts as a non-stop muscular pump maintaining systemic blood circulation through a double-circulation loop:</p>\n          <div class=\"step\">\n            <strong>1. Four-Chambered Separation:</strong> The heart is partitioned into four chambers: two upper receiving atria (Right Atrium, Left Atrium) and two lower pumping ventricles (Right Ventricle, Left Ventricle). A central muscular partition (septum) completely isolates oxygen-rich blood from carbon dioxide-rich blood.\n          </div>\n          <div class=\"step\">\n            <strong>2. Pulmonary Circulation:</strong> Deoxygenated blood loaded with CO₂ collected from body tissues enters the <strong>Right Atrium</strong>, passes into the <strong>Right Ventricle</strong>, and is pumped via the pulmonary artery to the <strong>lungs</strong> to discharge CO₂ and absorb fresh oxygen.\n          </div>\n          <div class=\"step\">\n            <strong>3. Systemic Circulation:</strong> Freshly oxygenated blood from the lungs returns via pulmonary veins into the <strong>Left Atrium</strong>, enters the thick-walled <strong>Left Ventricle</strong>, and is pumped under high pressure through the main artery (<strong>Aorta</strong>) to all tissues and organs of the entire body.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Four chambers and septum preventing mixing of oxygenated/deoxygenated blood</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Right side pumping deoxygenated blood to lungs for purification</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Left side pumping oxygenated blood via aorta to all body tissues</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_12\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_12')\">\n      <div class=\"q-num\">Q12</div>\n      <div class=\"q-text\">Why is it necessary to excrete waste products?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. Continuous Production of Toxins:</strong> During normal cellular metabolic processes (such as cellular respiration and protein breakdown), cells generate harmful, toxic metabolic byproducts like <strong>urea, uric acid, and carbon dioxide</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>2. Toxicity &amp; Cellular Poisoning:</strong> If these waste substances are not continuously filtered and eliminated, their concentration builds up in the bloodstream (uraemia). This causes chemical poisoning of vital organs, damages cell membranes, leads to coma, and can be fatal. Hence, excretion is mandatory to maintain physiological homeostasis.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Metabolic activities producing toxic nitrogenous wastes like urea</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accumulation poisoning cells and disrupting homeostasis</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"q-card\" id=\"q7_13\">\n    <div class=\"q-head\" onclick=\"toggleQ('q7_13')\">\n      <div class=\"q-num\">Q13</div>\n      <div class=\"q-text\">Draw a diagram of the human excretory system and label the various parts.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>The human excretory system consists of four principal anatomical structures:</p>\n          <div class=\"step\">\n            <strong>1. Pair of Kidneys:</strong> Two reddish-brown, bean-shaped organs located against the posterior abdominal wall on either side of the spine. Millions of microscopic nephron filters continuously purify blood, removing urea, excess water, and salts to form urine.\n          </div>\n          <div class=\"step\">\n            <strong>2. Pair of Ureters:</strong> Two thin, narrow muscular tubes (~25 cm long) emerging from the hilum of each kidney that conduct urine downwards by peristaltic action.\n          </div>\n          <div class=\"step\">\n            <strong>3. Urinary Bladder:</strong> A distensible, hollow muscular reservoir located in the pelvic cavity that temporarily stores urine (holding 300–500 mL) until pressure triggers the urge to urinate.\n          </div>\n          <div class=\"step\">\n            <strong>4. Urethra &amp; Urinary Opening:</strong> A short muscular duct leading from the neck of the bladder to an external urinary aperture for micturition (expulsion of urine).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Neat anatomical diagrammatic representation with kidneys, ureters, bladder, urethra</span><span class=\"marking-marks\">2 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct labelling of all 4 key structures</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#059669;\">Case Study: Dialysis in Chronic Kidney Disease</div>\n        <div class=\"cbq-question\">\n          <strong>Clinical Case:</strong> 55-year-old Mohan suffered from chronic uncontrolled hypertension, resulting in complete renal failure (both kidneys stopped functioning). His blood urea level surged dangerously, causing severe nausea, swelling of limbs, and breathlessness. His nephrologist scheduled him for haemodialysis twice a week.<br><br>\n          (i) What is the medical term for artificial blood purification when kidneys fail?<br>\n          (ii) How does a dialysis machine purify blood?<br>\n          (iii) What permanent medical solution exists if long-term dialysis is no longer viable?\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Medical Term:</strong> <strong>Haemodialysis</strong> (Artificial Kidney).</p>\n          <p><strong>(ii) Mechanism:</strong> Blood from an artery in the patient's arm is pumped through a dialysis machine containing thousands of semi-permeable cellophane tubes bathed in a temperature-controlled dialysing fluid (which has the exact same ionic composition as normal blood plasma but zero urea). As patient blood flows through, toxic urea, uric acid, and excess salts diffuse across the semi-permeable walls into the dialysing fluid. The cleansed blood is then warmed, mixed with an anti-coagulant reversal agent, and pumped back into the patient's vein.</p>\n          <p><strong>(iii) Permanent Solution:</strong> <strong>Kidney Transplantation</strong> — surgically grafting a healthy matching kidney from a compatible living or deceased donor into the patient.</p>\n        </div>\n      </div>\n\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">⚡ Assertion &amp; Reason (HOTS)</div>\n        <div class=\"cbq-question\">\n          <strong>Assertion (A):</strong> Veins have relatively thin walls with internal one-way valves, whereas arteries have thick, elastic walls without valves.<br>\n          <strong>Reason (R):</strong> Blood in arteries is pumped directly from the heart under high, pulsating pressure, while blood in veins flows at low pressure and needs valves to prevent backward flow under gravity.<br><br>\n          Choose the correct option:<br>\n          (a) Both A and R are true, and R is the correct explanation of A.<br>\n          (b) Both A and R are true, but R is not the correct explanation of A.<br>\n          (c) A is true, but R is false.<br>\n          (d) A is false, but R is true.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>Answer: (a) Both A and R are true, and R is the correct explanation of A.</strong></p>\n          <p><em>Scientific Explanation:</em> Left ventricular contraction forcefully ejects blood into the aorta at high pressure (~120 mm Hg), requiring thick muscular walls in arteries to prevent bursting. In veins, blood pressure drops to only 5–10 mm Hg; hence, walls are thin, and crescent pocket valves are physiologically essential to ensure blood flows only towards the heart against gravity.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(6)\">← Chapter 6: Respiration in Organisms</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(8)\">Chapter 8: Reproduction in Plants →</button>\n  </div>\n</section>\n","8":"<section class=\"chapter-section\" id=\"ch8\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">8</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 8: Reproduction in Plants</h2>\n      <p>NCERT Exercise Solutions — Complete Step-by-Step Answers with CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Scientific Concepts &amp; Plant Reproduction Modes</div>\n    <ul class=\"concept-list\">\n      <li><strong>Modes of Plant Reproduction:</strong>\n        <ul>\n          <li><em>Asexual Reproduction:</em> Multiplication without involving the fusion of gametes or production of seeds. Offspring are genetically identical clones of the single parent. Major types include:\n            <ul>\n              <li><strong>Vegetative Propagation:</strong> New plants arise from vegetative units like roots (sweet potato, dahlia), stems (runners, rhizomes in ginger/turmeric, tubers with \"eyes\" in potato, stem cuttings in rose), and leaves (notches of leaves in <em>Bryophyllum</em>).</li>\n              <li><strong>Budding:</strong> Formation of a small daughter bulb-like projection (bud) that detaches and matures (e.g., <em>Yeast</em>).</li>\n              <li><strong>Fragmentation:</strong> Filamentous organisms break into two or more fragments when mature, each growing into a new individual (e.g., <em>Spirogyra</em> alga).</li>\n              <li><strong>Spore Formation:</strong> Production of asexual microscopic spores protected by a tough, thick wall to withstand unfavourable conditions (heat, low humidity) which germinate under moisture (e.g., <em>Bread mould / Rhizopus</em>, ferns, mosses).</li>\n            </ul>\n          </li>\n          <li><em>Sexual Reproduction:</em> Involves fusion of male and female gametes produced by the reproductive organ of angiosperms — the <strong>flower</strong>.</li>\n        </ul>\n      </li>\n      <li><strong>Anatomy of a Flower:</strong>\n        <ul>\n          <li><strong>Bisexual Flowers:</strong> Contain both stamens (male) and pistil (female) — e.g., mustard, rose, petunia.</li>\n          <li><strong>Unisexual Flowers:</strong> Possess either male stamens (staminate) or female pistil (pistillate) — e.g., corn, papaya, cucumber.</li>\n          <li><strong>Stamen (Male organ):</strong> Comprises a slender <em>filament</em> and a terminal two-lobed <em>anther</em> containing pollen grains that produce male gametes.</li>\n          <li><strong>Pistil / Carpel (Female organ):</strong> Comprises the receptive <em>stigma</em>, elongated <em>style</em>, and a basal swollen <em>ovary</em> containing one or more <em>ovules</em> enclosing female gametes (egg cells).</li>\n        </ul>\n      </li>\n      <li><strong>Pollination &amp; Fertilisation:</strong>\n        <ul>\n          <li><em>Pollination:</em> Transfer of pollen grains from anther to stigma. Can be <strong>Self-pollination</strong> (same flower or another flower on same plant) or <strong>Cross-pollination</strong> (flower of another plant of same species via wind, water, insects).</li>\n          <li><em>Fertilisation:</em> Fusion of male gamete (travelling down a pollen tube) with the female egg cell inside the ovule to produce a diploid <strong>zygote</strong>. The zygote develops into an <strong>embryo</strong>; ovule matures into a <strong>seed</strong>, and the ovary ripens into a <strong>fruit</strong>.</li>\n        </ul>\n      </li>\n      <li><strong>Seed Dispersal Mechanisms:</strong> Prevents overcrowding, competition for sunlight, water, and minerals. Dispersed by: <em>Wind</em> (winged seeds of drumstick, maple; hairy seeds of aak, dandelion), <em>Water</em> (spongy, fibrous coats in coconut, lotus), <em>Animals</em> (hooked/spiny seeds of <em>Xanthium</em>, <em>Urena</em>), and <em>Explosion/dehiscence</em> (balsam, castor).</li>\n    </ul>\n  </div>\n\n  <div class=\"ex-div\">NCERT Textbook Exercise Questions</div>\n\n  <!-- Q1 -->\n  <div class=\"q-card\" id=\"q8_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Fill in the blanks:<br>\n        (a) Production of new individuals from the vegetative part of parent is called ______.<br>\n        (b) A flower may have either male or female reproductive parts. Such a flower is called ______.<br>\n        (c) The transfer of pollen grains from the anther to the stigma of the same or of another flower of the same kind is known as ______.<br>\n        (d) The fusion of male and female gametes is termed as ______.<br>\n        (e) Seed dispersal takes place by means of ______, ______, and ______.\n      </div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>(a)</strong> Production of new individuals from the vegetative part of parent is called <strong>vegetative propagation</strong>.</p>\n          <p><strong>(b)</strong> A flower may have either male or female reproductive parts. Such a flower is called a <strong>unisexual flower</strong>.</p>\n          <p><strong>(c)</strong> The transfer of pollen grains from the anther to the stigma of the same or of another flower of the same kind is known as <strong>pollination</strong>.</p>\n          <p><strong>(d)</strong> The fusion of male and female gametes is termed as <strong>fertilisation</strong>.</p>\n          <p><strong>(e)</strong> Seed dispersal takes place by means of <strong>wind</strong>, <strong>water</strong>, and <strong>animals</strong> (or explosion of fruits).</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct blank correctly identified (0.5 Mark × 5)</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q2 -->\n  <div class=\"q-card\" id=\"q8_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Describe the different methods of asexual reproduction in plants. Give examples.</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Asexual reproduction is a mode of reproduction in which new individuals are produced from a single parent without the formation and fusion of gametes or seeds. The primary methods are:</p>\n          <div class=\"step\">\n            <strong>1. Vegetative Propagation:</strong>\n            New plants arise from vegetative organs (roots, stems, leaves, buds).\n            <ul>\n              <li><em>Stem Tuber:</em> Potato tubers bear \"eyes\" (buds) covered by scar leaves. Planting an eye piece with a portion of potato gives rise to a new potato plant.</li>\n              <li><em>Stem Cutting:</em> In rose and money plant, a piece of branch cut at a node and planted in soil develops roots and leaves.</li>\n              <li><em>Leaf Buds:</em> In <em>Bryophyllum</em>, margin notches produce plantlets with adventitious roots that detach and establish independently.</li>\n              <li><em>Root Buds:</em> Sweet potato and Dahlia sprout into new plants from their swollen tuberous roots.</li>\n            </ul>\n          </div>\n          <div class=\"step\">\n            <strong>2. Budding:</strong>\n            A tiny bulb-like cellular outgrowth called a <strong>bud</strong> gradually grows on the parent cell, receives a replicated nucleus, and pinches off to form a new daughter cell (which may form chains before detaching).<br>\n            <em>Example:</em> Unicellular fungus <strong>Yeast</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>3. Fragmentation:</strong>\n            When nutrient and water conditions are favourable, filamentous green algae break into two or more small pieces (fragments). Each fragment rapidly grows through cell division into a complete mature filament.<br>\n            <em>Example:</em> <strong>Spirogyra</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>4. Spore Formation:</strong>\n            Special asexual reproductive bodies called <strong>spores</strong> are enclosed inside a hard protective coat (sporangium) to endure extreme drying and heat. When conditions become warm and humid, the sporangium bursts, liberating microscopic spores that germinate into new mycelia.<br>\n            <em>Example:</em> <strong>Bread mould (Rhizopus)</strong>, mosses, and ferns.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Vegetative propagation definition with suitable examples</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Budding mechanism with Yeast example</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Fragmentation mechanism with Spirogyra example</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Spore formation explanation with Bread mould example</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q3 -->\n  <div class=\"q-card\" id=\"q8_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Explain what you understand by sexual reproduction.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Definition:</strong> <strong>Sexual reproduction</strong> is the biological process of creating new offspring by the union of two specialized sex cells (gametes) — a male gamete and a female gamete — typically originating from two parents (or from both male and female organs of a bisexual organism).</p>\n          <div class=\"step\">\n            <strong>Key Features in Flowering Plants:</strong>\n            <ul>\n              <li>The <strong>flower</strong> is the reproductive organ of angiosperms.</li>\n              <li>The <strong>stamen</strong> (male reproductive organ) produces pollen grains containing male gametes.</li>\n              <li>The <strong>pistil / carpel</strong> (female reproductive organ) bears ovules containing female gametes (egg cells).</li>\n              <li>Pollination transfers pollen to the stigma, leading to <strong>fertilisation</strong> (syngamy) to form a single diploid cell called a <strong>zygote</strong>.</li>\n              <li>The zygote develops into an embryo contained within a protective <strong>seed</strong>, which germinates under favourable moisture and warmth to yield a genetically unique plant.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clear definition highlighting fusion of male and female gametes</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role of flower parts, zygote formation, and seed development</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q4 -->\n  <div class=\"q-card\" id=\"q8_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">State the main difference between asexual and sexual reproduction.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr>\n                <th>Feature / Parameter</th>\n                <th>Asexual Reproduction</th>\n                <th>Sexual Reproduction</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td><strong>Number of Parents</strong></td>\n                <td>Only one single parent is involved.</td>\n                <td>Usually two parents (male and female) are involved.</td>\n              </tr>\n              <tr>\n                <td><strong>Gamete Formation &amp; Fertilisation</strong></td>\n                <td>No gametes are produced; no fertilisation takes place.</td>\n                <td>Male and female gametes are produced and undergo fertilisation.</td>\n              </tr>\n              <tr>\n                <td><strong>Involvement of Seeds</strong></td>\n                <td>New plants develop without seeds (from stems, roots, leaves, buds, or spores).</td>\n                <td>Seeds are invariably formed within fruits and germinate into new plants.</td>\n              </tr>\n              <tr>\n                <td><strong>Genetic Variation</strong></td>\n                <td>Offspring are exact morphological and genetic clones of the parent.</td>\n                <td>Offspring inherit characters from both parents, creating genetic variation and diversity.</td>\n              </tr>\n              <tr>\n                <td><strong>Speed &amp; Rate of Multiplication</strong></td>\n                <td>Rapid multiplication process; produces a large population quickly.</td>\n                <td>Comparatively slower process requiring flowering, pollination, and seed maturation.</td>\n              </tr>\n              <tr>\n                <td><strong>Examples</strong></td>\n                <td>Potato (tubers), Yeast (budding), <em>Spirogyra</em> (fragmentation).</td>\n                <td>Mustard, Rose, Pea, Mango, Wheat, Papaya.</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Any 3 well-distinguished comparison points (1 Mark each)</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q5 -->\n  <div class=\"q-card\" id=\"q8_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Sketch the reproductive parts of a flower.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>The flower contains two essential reproductive whorls: the <strong>Stamen</strong> (androecium) and the <strong>Pistil / Carpel</strong> (gynoecium).</p>\n          <div class=\"step\">\n            <strong>1. Stamen (Male Reproductive Organ):</strong>\n            <ul>\n              <li><strong>Anther:</strong> The terminal, bilobed sac that produces and stores microscopic pollen grains (which house the male gametes).</li>\n              <li><strong>Filament:</strong> The slender, elongated stalk that supports and positions the anther for optimal pollen dispersal.</li>\n            </ul>\n          </div>\n          <div class=\"step\">\n            <strong>2. Pistil / Carpel (Female Reproductive Organ):</strong>\n            <ul>\n              <li><strong>Stigma:</strong> The sticky or feathery top surface designed to capture and anchor landed pollen grains.</li>\n              <li><strong>Style:</strong> The narrow, elongated neck connecting the stigma to the ovary, through which the pollen tube grows.</li>\n              <li><strong>Ovary:</strong> The basal, swollen chamber containing one or more egg-containing ovules. Upon fertilisation, the ovary ripens into the fruit.</li>\n              <li><strong>Ovule:</strong> The female reproductive structure inside the ovary containing the female gamete (egg cell), which transforms into the seed.</li>\n            </ul>\n          </div>\n          <div class=\"step\">\n            <strong>Diagrammatic Layout for Board Exams:</strong><br>\n            Draw two distinct sketches:\n            <ol>\n              <li><em>Stamen:</em> A slender stalk labelled <strong>Filament</strong> leading to a two-lobed top labelled <strong>Anther</strong>.</li>\n              <li><em>Pistil:</em> A vase-shaped structure with a top flat disc labelled <strong>Stigma</strong>, a central tube labelled <strong>Style</strong>, and a swollen lower base labelled <strong>Ovary</strong> with rounded inner bodies labelled <strong>Ovules</strong>.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Neat diagram of Stamen with Anther and Filament labelled</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Neat diagram of Pistil with Stigma, Style, Ovary, and Ovule labelled</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q6 -->\n  <div class=\"q-card\" id=\"q8_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">Explain the difference between self-pollination and cross-pollination.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr>\n                <th>Feature</th>\n                <th>Self-Pollination (Autogamy / Geitonogamy)</th>\n                <th>Cross-Pollination (Allogamy / Xenogamy)</th>\n              </tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td><strong>Definition</strong></td>\n                <td>Transfer of pollen grains from the anther to the stigma of the <em>same flower</em> or another flower on the <em>same plant</em>.</td>\n                <td>Transfer of pollen grains from the anther of one flower to the stigma of a flower on <em>another plant of the same species</em>.</td>\n              </tr>\n              <tr>\n                <td><strong>External Agents</strong></td>\n                <td>External pollinating agents (insects, wind, water) are usually not required.</td>\n                <td>Requires external pollinating agents such as bees, butterflies, birds, wind, or water.</td>\n              </tr>\n              <tr>\n                <td><strong>Floral Adaptations</strong></td>\n                <td>Flowers need not be large, showy, scent-producing, or rich in nectar.</td>\n                <td>Flowers are usually large, brightly colored, possess fragrant scent and sweet nectar to attract pollinators (or produce dry, powdery pollen for wind).</td>\n              </tr>\n              <tr>\n                <td><strong>Genetic Variation</strong></td>\n                <td>Does not introduce genetic variations; preserves pure parental traits.</td>\n                <td>Combines genes from two parent plants, resulting in high genetic diversity and stronger adaptability.</td>\n              </tr>\n              <tr>\n                <td><strong>Examples</strong></td>\n                <td>Pea, peanut, wheat, rice.</td>\n                <td>Mustard, apple, sunflower, corn, papaya.</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate definition of self-pollination and cross-pollination</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Differences based on pollinating agents and genetic variations</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Appropriate plant examples for both</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q7 -->\n  <div class=\"q-card\" id=\"q8_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">How does the process of fertilisation take place in flowers?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Fertilisation</strong> is the process in which the male gamete fuses with the female gamete to form a single diploid cell called a <strong>zygote</strong>. In flowering plants, it occurs in the following sequential stages:</p>\n          <div class=\"step\">\n            <strong>Step 1: Pollen Germination:</strong>\n            After landing on the compatible receptive surface of the stigma, the pollen grain absorbs moisture and sugary nutrient secretions, germinating to produce a narrow, thin <strong>pollen tube</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Growth down the Style:</strong>\n            The pollen tube grows downwards through the tissues of the style towards the ovary, carrying two male gametes in its tip.\n          </div>\n          <div class=\"step\">\n            <strong>Step 3: Entry into the Ovule:</strong>\n            The pollen tube enters the ovary and penetrates an ovule through a microscopic aperture called the micropyle.\n          </div>\n          <div class=\"step\">\n            <strong>Step 4: Syngamy / Fusion:</strong>\n            The tip of the pollen tube bursts open, releasing the male gamete, which fuses directly with the female egg cell situated within the ovule. This union results in the formation of a <strong>zygote</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>Post-Fertilisation Changes:</strong>\n            <ul>\n              <li>The zygote divides repeatedly to develop into an <strong>embryo</strong>.</li>\n              <li>The ovule develops a tough seed coat and matures into a <strong>seed</strong>.</li>\n              <li>The ovary enlarges, ripens, and transforms into a succulent or dry <strong>fruit</strong>.</li>\n              <li>Petals, sepals, and stamens wither and fall off.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pollen germination and pollen tube elongation description</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Fusion of male gamete with egg cell in ovule to form zygote</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Post-fertilisation development into seed and fruit</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q8 -->\n  <div class=\"q-card\" id=\"q8_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">Describe the various ways by which seeds are dispersed.</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Seed dispersal is the natural scattering or transport of seeds away from parent plants. It is ecologically vital because it avoids overcrowding, minimizes intense competition for water, sunlight, and soil minerals, and enables species to invade new geographical habitats. The four major mechanisms are:</p>\n          <div class=\"step\">\n            <strong>1. Dispersal by Wind:</strong>\n            Seeds are lightweight, small, and equipped with special aerodynamic structures:\n            <ul>\n              <li><em>Winged seeds:</em> Drumstick (<em>Moringa</em>) and Maple seeds have thin papery wings that catch wind currents and glide over long distances.</li>\n              <li><em>Hairy seeds and tufts:</em> Aak (<em>Calotropis</em>) and Dandelion have parachutes or tufts of fine silk-like hairs; sunflower fruits possess a hairy pappus that floats on breezes.</li>\n              <li><em>Microscopic spores:</em> Extremely light spores of ferns and mosses blow away effortlessly.</li>\n            </ul>\n          </div>\n          <div class=\"step\">\n            <strong>2. Dispersal by Water:</strong>\n            Seeds or fruits develop light, fibrous, or spongy outer coats that trap air, enabling them to float on surface water streams and ocean currents.<br>\n            <em>Examples:</em> <strong>Coconut</strong> has a buoyant fibrous mesocarp; <strong>Lotus</strong> has a spongy fruit that floats down rivers.\n          </div>\n          <div class=\"step\">\n            <strong>3. Dispersal by Animals:</strong>\n            Seeds possess physical clinging adaptations or sweet fleshy pulp:\n            <ul>\n              <li><em>Hooked / Spiny seeds:</em> <strong>Xanthium</strong> and <strong>Urena</strong> have hooked spines that latch tenaciously onto the fur of grazing animals or human clothing, falling off miles away.</li>\n              <li><em>Edible fruits:</em> Birds and mammals consume juicy fruits (figs, guava, berries); the indigestible hard seeds pass unharmed through the digestive tract and are deposited far away in nutrient-rich droppings.</li>\n            </ul>\n          </div>\n          <div class=\"step\">\n            <strong>4. Dispersal by Explosive Mechanism (Dehiscence):</strong>\n            Upon ripening and drying under solar heat, extreme mechanical tension builds up inside the fruit wall, causing the pericarp to suddenly burst open with explosive force, catapulting seeds several metres away from the parent plant.<br>\n            <em>Examples:</em> <strong>Balsam</strong>, <strong>Castor</strong>, and <strong>Pea pods</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Wind dispersal with winged/hairy examples (Drumstick, Maple, Aak)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Water dispersal with buoyant structures (Coconut, Lotus)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Animal dispersal with hooked seeds (Xanthium, Urena)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explosive dehiscence mechanism (Balsam, Castor)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q9 -->\n  <div class=\"q-card\" id=\"q8_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">Match items in Column I with those in Column II:<br>\n        <strong>Column I:</strong> (a) Bud, (b) Eyes, (c) Fragmentation, (d) Wings, (e) Spores<br>\n        <strong>Column II:</strong> (i) Maple, (ii) Spirogyra, (iii) Yeast, (iv) Bread mould, (v) Potato, (vi) Rose\n      </div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr><th>Column I (Structure / Feature)</th><th>Column II (Matched Organism)</th></tr>\n            </thead>\n            <tbody>\n              <tr><td><strong>(a) Bud</strong></td><td><strong>(iii) Yeast</strong> (reproduces asexually by budding)</td></tr>\n              <tr><td><strong>(b) Eyes</strong></td><td><strong>(v) Potato</strong> (vegetative buds on tubers)</td></tr>\n              <tr><td><strong>(c) Fragmentation</strong></td><td><strong>(ii) Spirogyra</strong> (green alga breaking into filaments)</td></tr>\n              <tr><td><strong>(d) Wings</strong></td><td><strong>(i) Maple</strong> (winged seeds for aerodynamic wind dispersal)</td></tr>\n              <tr><td><strong>(e) Spores</strong></td><td><strong>(iv) Bread mould</strong> (asexual spores in sporangia)</td></tr>\n            </tbody>\n          </table>\n          <p><em>Note: (vi) Rose reproduces via stem cuttings (vegetative propagation), so it remains an extra unmatched distractor.</em></p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correctly matched pair (0.5 Mark × 5)</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q10 -->\n  <div class=\"q-card\" id=\"q8_10\">\n    <div class=\"q-head\" onclick=\"toggleQ('q8_10')\">\n      <div class=\"q-num\">Q10</div>\n      <div class=\"q-text\">Tick the correct answer:<br>\n        (a) The reproductive part of a plant is the: (i) leaf, (ii) stem, (iii) root, (iv) flower.<br>\n        (b) The process of fusion of the male and the female gametes is called: (i) fertilisation, (ii) pollination, (iii) reproduction, (iv) seed formation.<br>\n        (c) Mature ovary forms the: (i) seed, (ii) stamen, (iii) pistil, (iv) fruit.<br>\n        (d) A spore-producing plant is: (i) rose, (ii) bread mould, (iii) potato, (iv) ginger.<br>\n        (e) <em>Bryophyllum</em> can reproduce by its: (i) stem, (ii) leaves, (iii) roots, (iv) flower.\n      </div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) (iv) flower</strong><br>\n            <em>Reason:</em> While leaves, stems, and roots are vegetative parts, the flower contains the specialized male (stamen) and female (pistil) reproductive structures.\n          </div>\n          <div class=\"step\">\n            <strong>(b) (i) fertilisation</strong><br>\n            <em>Reason:</em> Fertilisation (syngamy) is the precise biological union of male and female gametic nuclei to produce a zygote.\n          </div>\n          <div class=\"step\">\n            <strong>(c) (iv) fruit</strong><br>\n            <em>Reason:</em> Following successful fertilisation, the ovules transform into seeds while the surrounding ovary wall swells and ripens into the fruit.\n          </div>\n          <div class=\"step\">\n            <strong>(d) (ii) bread mould</strong><br>\n            <em>Reason:</em> Bread mould (<em>Rhizopus</em>) forms globular sporangia bearing asexual resistant spores.\n          </div>\n          <div class=\"step\">\n            <strong>(e) (ii) leaves</strong><br>\n            <em>Reason:</em> <em>Bryophyllum</em> features adventitious buds along the serrated notches of its leaf margins, which germinate into plantlets.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct option with valid scientific reason (0.5 Mark × 5)</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#059669;\">Case Study: Commercial Horticulture &amp; Vegetative Propagation</div>\n        <div class=\"cbq-question\">\n          <strong>Horticultural Application:</strong> An agricultural scientist advises a farmer growing seedless Thompson grapes and high-yielding Alphonso mangoes to exclusively practice vegetative propagation (cuttings and grafting) rather than growing plants from seeds.<br><br>\n          (i) Why cannot seedless grapes be propagated through sexual reproduction?<br>\n          (ii) State two major commercial advantages vegetative propagation offers over growing from seeds.<br>\n          (iii) What is the fundamental disadvantage of monoculture clones produced through vegetative propagation?\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Reason for Seedless Grapes:</strong> Seedless grape varieties do not produce viable seeds containing embryos; hence sexual reproduction through seed germination is biologically impossible. They can only be multiplied through stem cuttings or grafting.</p>\n          <p><strong>(ii) Commercial Advantages:</strong>\n            <br>1. <em>Speed and Earlier Maturity:</em> Vegetatively propagated plants bear flowers and fruits much earlier than seedlings grown from seeds.\n            <br>2. <em>Exact Genetic Quality:</em> Offspring are exact clones, ensuring 100% preservation of desirable traits (taste, fruit size, disease resistance, sweetness) without genetic variation.\n          </p>\n          <p><strong>(iii) Biological Disadvantage:</strong> Because all plants in the orchard share identical genetic makeup, there is zero genetic diversity. If a new disease or pest strikes, every single plant will be equally susceptible, risking total crop wipeout.</p>\n        </div>\n      </div>\n\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">⚡ Assertion &amp; Reason (HOTS)</div>\n        <div class=\"cbq-question\">\n          <strong>Assertion (A):</strong> Nature has evolved intricate mechanisms to favor cross-pollination over self-pollination in most flowering plants.<br>\n          <strong>Reason (R):</strong> Cross-pollination brings about new combinations of genes from two distinct parent plants, creating healthier offspring with higher adaptability to changing environments.<br><br>\n          Choose the correct option:<br>\n          (a) Both A and R are true, and R is the correct explanation of A.<br>\n          (b) Both A and R are true, but R is not the correct explanation of A.<br>\n          (c) A is true, but R is false.<br>\n          (d) A is false, but R is true.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>Answer: (a) Both A and R are true, and R is the correct explanation of A.</strong></p>\n          <p><em>Scientific Explanation:</em> Continuous self-pollination leads to inbreeding depression, accumulation of harmful recessive alleles, and reduced vigour. Cross-pollination introduces novel genetic variations, enhances environmental fitness, and produces vigorous, disease-resistant seeds.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(7)\">← Chapter 7: Transportation in Animals and Plants</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(9)\">Chapter 9: Motion and Time →</button>\n  </div>\n</section>\n","9":"<section class=\"chapter-section\" id=\"ch9\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">9</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 9: Motion and Time</h2>\n      <p>NCERT Exercise Solutions — Complete Step-by-Step Answers with CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Scientific Concepts &amp; Kinematic Equations</div>\n    <ul class=\"concept-list\">\n      <li><strong>Motion &amp; Speed:</strong>\n        <ul>\n          <li><strong>Speed:</strong> The total distance covered by an object divided by the total time taken to cover that distance.<br>\n            <div class=\"math\">Speed = Total Distance Covered / Total Time Taken</div>\n          </li>\n          <li><strong>SI Units:</strong> Basic unit of distance is <strong>metre (m)</strong>; basic unit of time is <strong>second (s)</strong>. Hence, the SI basic unit of speed is <strong>metre per second (m/s)</strong>. Larger commercial unit is <strong>kilometre per hour (km/h)</strong>.<br>\n            Conversion: <div class=\"math\">1 km/h = (1000 m) / (3600 s) = 5/18 m/s</div>\n          </li>\n          <li><strong>Uniform vs Non-uniform Motion:</strong> An object moving along a straight line with a constant speed is in <em>uniform motion</em>. If the speed keeps changing with time, the motion is <em>non-uniform</em>.</li>\n        </ul>\n      </li>\n      <li><strong>Measurement of Time &amp; Periodic Motion:</strong>\n        <ul>\n          <li>Clocks and watches rely on regular, repeating periodic events.</li>\n          <li><strong>Simple Pendulum:</strong> Consists of a small metallic sphere (bob) suspended from a rigid stand by a light thread.</li>\n          <li><strong>Oscillation:</strong> One complete to-and-fro motion of the bob from one extreme position to another and back.</li>\n          <li><strong>Time Period (T):</strong> The time taken by the pendulum bob to complete one full oscillation.<br>\n            <div class=\"math\">Time Period (T) = Total Time Taken / Number of Oscillations</div>\n            <em>Discovery:</em> Galileo Galilei observed that the time period of a simple pendulum depends only on the length of the suspension string, and remains constant regardless of the amplitude of swing.\n          </li>\n        </ul>\n      </li>\n      <li><strong>Distance-Time Graphs:</strong>\n        <ul>\n          <li>A graphical representation plotting time on the horizontal X-axis and distance on the vertical Y-axis.</li>\n          <li>A straight line sloping upwards indicates <strong>uniform speed</strong> (constant speed).</li>\n          <li>A horizontal line parallel to the time axis indicates an object at <strong>rest</strong> (speed = 0).</li>\n          <li>A curved line indicates <strong>non-uniform speed</strong> (accelerating or decelerating motion).</li>\n          <li>The steeper the slope (gradient) of the distance-time graph, the greater is the speed of the object.</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n\n  <div class=\"ex-div\">NCERT Textbook Exercise Questions</div>\n\n  <!-- Q1 -->\n  <div class=\"q-card\" id=\"q9_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Classify the following as motion along a straight line, circular or oscillatory motion:<br>\n        (i) Motion of your hands while running.<br>\n        (ii) Motion of a horse pulling a cart on a straight road.<br>\n        (iii) Motion of a child in a merry-go-round.<br>\n        (iv) Motion of a child on a see-saw.<br>\n        (v) Motion of the hammer of an electric bell.<br>\n        (vi) Motion of a train on a straight bridge.\n      </div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr><th>S.No.</th><th>Example of Motion</th><th>Classification / Type of Motion</th><th>Scientific Reason</th></tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td>(i)</td>\n                <td>Motion of hands while running</td>\n                <td><strong>Oscillatory motion</strong></td>\n                <td>Hands execute a repetitive to-and-fro movement about a mean position.</td>\n              </tr>\n              <tr>\n                <td>(ii)</td>\n                <td>Horse pulling a cart on a straight road</td>\n                <td><strong>Motion along a straight line (Rectilinear motion)</strong></td>\n                <td>The movement occurs along a unidirectional straight trajectory.</td>\n              </tr>\n              <tr>\n                <td>(iii)</td>\n                <td>Child in a merry-go-round</td>\n                <td><strong>Circular motion</strong></td>\n                <td>The child moves along a circular path at a constant radial distance from the central axis.</td>\n              </tr>\n              <tr>\n                <td>(iv)</td>\n                <td>Child on a see-saw</td>\n                <td><strong>Oscillatory motion</strong></td>\n                <td>The see-saw moves repeatedly up and down about a central fulcrum pivot.</td>\n              </tr>\n              <tr>\n                <td>(v)</td>\n                <td>Hammer of an electric bell</td>\n                <td><strong>Oscillatory motion</strong></td>\n                <td>The metallic hammer strikes back and forth repeatedly against the gong.</td>\n              </tr>\n              <tr>\n                <td>(vi)</td>\n                <td>Train on a straight bridge</td>\n                <td><strong>Motion along a straight line (Rectilinear motion)</strong></td>\n                <td>The train tracks form a straight linear path across the bridge.</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct classification with justification (0.5 Mark × 6)</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q2 -->\n  <div class=\"q-card\" id=\"q9_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Which of the following are not correct?<br>\n        (i) The basic unit of time is second.<br>\n        (ii) Every object moves with a constant speed.<br>\n        (iii) Distances between two cities are measured in kilometres.<br>\n        (iv) The time period of a given pendulum is not constant.<br>\n        (v) The speed of a train is expressed in m/h.\n      </div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>The statements that are <strong>not correct (incorrect)</strong> are:</p>\n          <div class=\"step\">\n            <strong>(ii) Incorrect:</strong> <em>\"Every object moves with a constant speed.\"</em><br>\n            <strong>Correction:</strong> Most natural objects move with variable (non-uniform) speeds because of traffic, friction, turns, starting, and stopping.\n          </div>\n          <div class=\"step\">\n            <strong>(iv) Incorrect:</strong> <em>\"The time period of a given pendulum is not constant.\"</em><br>\n            <strong>Correction:</strong> The time period of a given pendulum of fixed length is constant (isochronism of pendulums discovered by Galileo).\n          </div>\n          <div class=\"step\">\n            <strong>(v) Incorrect:</strong> <em>\"The speed of a train is expressed in m/h.\"</em><br>\n            <strong>Correction:</strong> Because trains travel long distances at high speeds, their speed is practically expressed in <strong>km/h</strong> (kilometres per hour) or in SI units as <strong>m/s</strong>.\n          </div>\n          <div class=\"step\">\n            <em>Statements (i) and (iii) are completely correct:</em> The SI basic unit of time is the second (s), and geographical distances between cities are measured in kilometres (km).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of statements (ii), (iv), and (v) as incorrect with corrections</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q3 -->\n  <div class=\"q-card\" id=\"q9_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">A simple pendulum takes 32 s to complete 20 oscillations. What is the time period of the pendulum?</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Given Data:</strong><br>\n            Total number of complete oscillations (n) = 20<br>\n            Total time taken (t) = 32 seconds\n          </div>\n          <div class=\"step\">\n            <strong>Formula:</strong><br>\n            The time period (T) of a simple pendulum is defined as the time required to complete one single oscillation:<br>\n            <div class=\"math\">Time Period (T) = Total Time Taken / Total Number of Oscillations</div>\n          </div>\n          <div class=\"step\">\n            <strong>Calculation:</strong><br>\n            <div class=\"math\">T = 32 / 20 = 1.6 seconds</div>\n          </div>\n          <div class=\"step\">\n            <strong>Conclusion:</strong><br>\n            The time period of the simple pendulum is <strong>1.6 seconds</strong>.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Statement of definition and formula for time period</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate substitution and final answer with unit (1.6 s)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q4 -->\n  <div class=\"q-card\" id=\"q9_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">The distance between two stations is 240 km. A train takes 4 hours to cover this distance. Calculate the speed of the train.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Given Data:</strong><br>\n            Distance covered by the train (D) = 240 km<br>\n            Time taken to travel the distance (t) = 4 hours (h)\n          </div>\n          <div class=\"step\">\n            <strong>Formula:</strong><br>\n            <div class=\"math\">Speed = Distance / Time</div>\n          </div>\n          <div class=\"step\">\n            <strong>Calculation:</strong><br>\n            <div class=\"math\">Speed = 240 km / 4 h = 60 km/h</div>\n            <em>In SI units (m/s):</em><br>\n            <div class=\"math\">Speed = 60 × (5/18) = 300 / 18 ≈ 16.67 m/s</div>\n          </div>\n          <div class=\"step\">\n            <strong>Conclusion:</strong><br>\n            The speed of the train is <strong>60 km/h</strong> (or 16.67 m/s).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula Speed = Distance / Time</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Step-by-step calculation with correct units (60 km/h)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q5 -->\n  <div class=\"q-card\" id=\"q9_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">The odometer of a car reads 57321.0 km when the clock shows the time 08:30 AM. What is the distance moved by the car, if at 08:50 AM, the odometer reading has changed to 57336.0 km? Calculate the speed of the car in km/min during this time. Express the speed in km/h also.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Step 1: Calculate Distance Covered:</strong><br>\n            Initial odometer reading at 08:30 AM = 57321.0 km<br>\n            Final odometer reading at 08:50 AM = 57336.0 km<br>\n            <div class=\"math\">Distance = Final Reading - Initial Reading = 57336.0 - 57321.0 = 15.0 km</div>\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Calculate Elapsed Time:</strong><br>\n            Time elapsed = 08:50 AM - 08:30 AM = 20 minutes\n          </div>\n          <div class=\"step\">\n            <strong>Step 3: Calculate Speed in km/min:</strong><br>\n            <div class=\"math\">Speed = Distance / Time = 15 km / 20 min = 0.75 km/min</div>\n          </div>\n          <div class=\"step\">\n            <strong>Step 4: Express Speed in km/h:</strong><br>\n            Since 1 hour = 60 minutes, time in hours = 20/60 h = 1/3 h.<br>\n            <div class=\"math\">Speed = 15 km / (1/3 h) = 15 × 3 = 45 km/h</div>\n            <em>(Alternatively: Speed in km/h = 0.75 km/min × 60 min/h = 45 km/h)</em>\n          </div>\n          <div class=\"step\">\n            <strong>Final Summary:</strong><br>\n            • Distance moved = <strong>15.0 km</strong><br>\n            • Speed in km/min = <strong>0.75 km/min</strong><br>\n            • Speed in km/h = <strong>45 km/h</strong>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Distance calculation (15 km) and time interval (20 min)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Speed in km/min (0.75 km/min)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conversion and speed in km/h (45 km/h)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q6 -->\n  <div class=\"q-card\" id=\"q9_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">Salma takes 15 minutes from her house to reach her school on a bicycle. If the bicycle has a speed of 2 m/s, calculate the distance between her house and the school.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Given Data:</strong><br>\n            Speed of bicycle (v) = 2 m/s<br>\n            Time taken (t) = 15 minutes\n          </div>\n          <div class=\"step\">\n            <strong>Unit Conversion:</strong><br>\n            To use the speed in m/s, time must be converted from minutes into seconds:<br>\n            <div class=\"math\">Time (t) = 15 × 60 s = 900 seconds</div>\n          </div>\n          <div class=\"step\">\n            <strong>Formula:</strong><br>\n            <div class=\"math\">Distance = Speed × Time</div>\n          </div>\n          <div class=\"step\">\n            <strong>Calculation:</strong><br>\n            <div class=\"math\">Distance = 2 m/s × 900 s = 1800 metres</div>\n            <em>Converting to kilometres:</em><br>\n            <div class=\"math\">Distance = 1800 / 1000 = 1.8 km</div>\n          </div>\n          <div class=\"step\">\n            <strong>Conclusion:</strong><br>\n            The distance between Salma's house and her school is <strong>1800 m</strong> (or <strong>1.8 km</strong>).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conversion of time to seconds (900 s)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Formula and calculation yielding 1800 m or 1.8 km</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q7 -->\n  <div class=\"q-card\" id=\"q9_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Show the shape of the distance-time graph for the motion in the following cases:<br>\n        (i) A car moving with a constant speed.<br>\n        (ii) A car parked on a side road.\n      </div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Case (i): A car moving with a constant speed:</strong><br>\n            • <em>Shape of Graph:</em> A <strong>straight line inclined at an angle</strong> to the time axis (sloping upwards linearly from the origin).<br>\n            • <em>Scientific Explanation:</em> When an object covers equal distances in equal intervals of time, the ratio Distance / Time remains constant. Hence, the graph is a linear upward diagonal line representing uniform motion.\n          </div>\n          <div class=\"step\">\n            <strong>Case (ii): A car parked on a side road:</strong><br>\n            • <em>Shape of Graph:</em> A <strong>horizontal straight line parallel to the time axis (X-axis)</strong> at a fixed distance value.<br>\n            • <em>Scientific Explanation:</em> As time progresses continuously, the car remains stationary at the exact same location, so distance does not change (Slope = 0, Speed = 0).\n          </div>\n          <div class=\"step\">\n            <strong>Exam Diagram Note:</strong><br>\n            Always label Time on the horizontal X-axis (with units, e.g., seconds or minutes) and Distance on the vertical Y-axis (with units, e.g., metres or kilometres).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Shape and explanation for constant speed (straight inclined line)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Shape and explanation for parked car (horizontal line parallel to X-axis)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q8 -->\n  <div class=\"q-card\" id=\"q9_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">Which of the following relations is correct?<br>\n        (i) Speed = Distance × Time<br>\n        (ii) Speed = Distance / Time<br>\n        (iii) Speed = Time / Distance<br>\n        (iv) Speed = 1 / (Distance × Time)\n      </div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (ii) Speed = Distance / Time</strong></p>\n          <p><em>Scientific Definition:</em> Speed is defined as the rate of change of distance with respect to time, or the distance covered by an object per unit time.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct option selection with definition</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q9 -->\n  <div class=\"q-card\" id=\"q9_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">The basic unit of speed is:<br>\n        (i) km/min<br>\n        (ii) m/min<br>\n        (iii) km/h<br>\n        (iv) m/s\n      </div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (iv) m/s (metre per second)</strong></p>\n          <p><em>Scientific Reason:</em> In the International System of Units (SI), the base unit of length is the <strong>metre (m)</strong> and the base unit of time is the <strong>second (s)</strong>. Since Speed = Distance / Time, the basic derived unit of speed is metres divided by seconds, written as <strong>m/s</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Selection of m/s with SI derivation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q10 -->\n  <div class=\"q-card\" id=\"q9_10\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_10')\">\n      <div class=\"q-num\">Q10</div>\n      <div class=\"q-text\">A car moves with a speed of 40 km/h for 15 minutes and then with a speed of 60 km/h for the next 15 minutes. The total distance covered by the car is:<br>\n        (i) 100 km<br>\n        (ii) 25 km<br>\n        (iii) 15 km<br>\n        (iv) 10 km\n      </div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (ii) 25 km</strong></p>\n          <div class=\"step\">\n            <strong>Detailed Step-by-Step Calculation:</strong><br>\n            • Time duration for each part = 15 minutes = 15 / 60 hours = 1/4 hour = 0.25 h.<br><br>\n            • <em>Part 1:</em> Distance covered in first 15 minutes (<span class=\"math\">d₁</span>):<br>\n            <div class=\"math\">d₁ = Speed₁ × Time₁ = 40 km/h × (1/4) h = 10 km</div>\n            <br>\n            • <em>Part 2:</em> Distance covered in next 15 minutes (<span class=\"math\">d₂</span>):<br>\n            <div class=\"math\">d₂ = Speed₂ × Time₂ = 60 km/h × (1/4) h = 15 km</div>\n            <br>\n            • <em>Total Distance:</em><br>\n            <div class=\"math\">Total Distance = d₁ + d₂ = 10 km + 15 km = 25 km</div>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of individual distances (10 km and 15 km)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Total sum (25 km) matching option (ii)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q11 -->\n  <div class=\"q-card\" id=\"q9_11\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_11')\">\n      <div class=\"q-num\">Q11</div>\n      <div class=\"q-text\">Suppose the two photographs, shown in Fig. 9.1 and Fig. 9.2, had been taken at an interval of 10 seconds. If a distance of 100 metres is shown by 1 cm in these photographs, calculate the speed of the fastest blue car (assuming it covers 2 cm on the photograph scale).</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Given Data:</strong><br>\n            Time interval between the two photographs (t) = 10 s<br>\n            Scale of photograph: 1 cm on photo represents 100 m on actual ground.<br>\n            Distance measured on photograph for the blue car = 2.0 cm\n          </div>\n          <div class=\"step\">\n            <strong>Step 1: Calculate Actual Distance Covered:</strong><br>\n            <div class=\"math\">Actual Distance (d) = 2.0 cm × 100 m/cm = 200 metres</div>\n          </div>\n          <div class=\"step\">\n            <strong>Step 2: Calculate Speed in m/s:</strong><br>\n            <div class=\"math\">Speed = Distance / Time = 200 m / 10 s = 20 m/s</div>\n          </div>\n          <div class=\"step\">\n            <strong>Step 3: Convert Speed to km/h:</strong><br>\n            <div class=\"math\">Speed = 20 × (18/5) = 4 × 18 = 72 km/h</div>\n          </div>\n          <div class=\"step\">\n            <strong>Conclusion:</strong><br>\n            The speed of the fastest car is <strong>20 m/s</strong> (or <strong>72 km/h</strong>).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Scale conversion to actual distance (200 m)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of speed in m/s (20 m/s)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conversion to km/h (72 km/h)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q12 -->\n  <div class=\"q-card\" id=\"q9_12\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_12')\">\n      <div class=\"q-num\">Q12</div>\n      <div class=\"q-text\">Figure 9.5 shows the distance-time graph for the motion of two vehicles A and B. Which one of them is moving faster? Explain with scientific reasoning.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Answer: Vehicle A is moving faster than Vehicle B.</strong></p>\n          <div class=\"step\">\n            <strong>Scientific Justification:</strong>\n            <ul>\n              <li>On a distance-time graph, the <strong>slope (steepness)</strong> of the curve represents the <strong>speed</strong> of the vehicle:<br>\n                <div class=\"math\">Slope = (Change in Distance) / (Change in Time) = Speed</div>\n              </li>\n              <li>In the given graph, line A is steeper (has a greater slope / angle with the horizontal time axis) compared to line B.</li>\n              <li>For any given fixed time interval <span class=\"math\">t</span>, vehicle A covers a noticeably larger vertical distance than vehicle B. Therefore, vehicle A moves at a higher speed.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of Vehicle A as the faster moving vehicle</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation linking graph slope to speed</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q13 -->\n  <div class=\"q-card\" id=\"q9_13\">\n    <div class=\"q-head\" onclick=\"toggleQ('q9_13')\">\n      <div class=\"q-num\">Q13</div>\n      <div class=\"q-text\">Which of the following distance-time graphs shows a truck moving with speed which is not constant? Explain how graph geometry identifies variable speed.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Answer: The graph with a curved line (non-linear graph) shows a truck moving with a non-constant (variable) speed.</strong></p>\n          <div class=\"step\">\n            <strong>Geometric and Physical Reasons:</strong>\n            <ul>\n              <li><strong>Constant Speed (Uniform Motion):</strong> Represented by a straight line inclined to the time axis because equal distances are covered in equal time intervals.</li>\n              <li><strong>Zero Speed (Rest):</strong> Represented by a straight horizontal line parallel to the time axis.</li>\n              <li><strong>Non-Constant Speed (Non-uniform Motion):</strong> Represented by a <strong>curved line</strong> where the slope continuously changes from moment to moment. A changing slope indicates that the distance covered per unit time is either increasing (acceleration) or decreasing (deceleration).</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of the curved-line graph</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of changing slope representing changing speed</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#059669;\">Case Study: High-Speed Train Vande Bharat Telemetry</div>\n        <div class=\"cbq-question\">\n          <strong>Railway Engineering Case:</strong> During trial runs of the semi-high-speed Vande Bharat Express between New Delhi and Varanasi (distance = 760 km), the train covered the first 160 km in 1 hour, the next 300 km in 2 hours, and the remaining 300 km in 3 hours.<br><br>\n          (i) Calculate the average speed of the train over the entire journey in km/h.<br>\n          (ii) Did the train maintain uniform motion throughout the journey? Justify.<br>\n          (iii) Convert the overall average speed into SI units (m/s).\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Average Speed:</strong><br>\n            Total Distance = 160 + 300 + 300 = 760 km<br>\n            Total Time = 1 + 2 + 3 = 6 hours<br>\n            <span class=\"math\">Average Speed = 760 / 6 ≈ 126.67 km/h</span>\n          </p>\n          <p><strong>(ii) Motion Type:</strong> <strong>Non-uniform motion</strong>. The speeds in the three legs were 160 km/h (leg 1), 150 km/h (leg 2), and 100 km/h (leg 3). Because the speed varied across sections, the motion was non-uniform.</p>\n          <p><strong>(iii) SI Units Conversion:</strong><br>\n            <span class=\"math\">126.67 × (5/18) = 633.35 / 18 ≈ 35.19 m/s</span>\n          </p>\n        </div>\n      </div>\n\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">⚡ Assertion &amp; Reason (HOTS)</div>\n        <div class=\"cbq-question\">\n          <strong>Assertion (A):</strong> If the distance-time graph of a moving scooter is a straight line parallel to the time axis, the scooter is at complete rest.<br>\n          <strong>Reason (R):</strong> The slope of a distance-time graph gives the speed of an object, and a horizontal line parallel to the time axis has a slope equal to zero.<br><br>\n          Choose the correct option:<br>\n          (a) Both A and R are true, and R is the correct explanation of A.<br>\n          (b) Both A and R are true, but R is not the correct explanation of A.<br>\n          (c) A is true, but R is false.<br>\n          (d) A is false, but R is true.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>Answer: (a) Both A and R are true, and R is the correct explanation of A.</strong></p>\n          <p><em>Scientific Explanation:</em> When distance remains fixed as time elapses, <span class=\"math\">Δd = 0</span>. Therefore, <span class=\"math\">Speed = Δd / Δt = 0</span>. This translates graphically to zero slope (a horizontal line), proving that the vehicle is stationary.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(8)\">← Chapter 8: Reproduction in Plants</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(10)\">Chapter 10: Electric Current and its Effects →</button>\n  </div>\n</section>\n","10":"<section class=\"chapter-section\" id=\"ch10\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">10</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 10: Electric Current and its Effects</h2>\n      <p>NCERT Exercise Solutions — Complete Step-by-Step Answers with CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Scientific Concepts &amp; Circuit Fundamentals</div>\n    <ul class=\"concept-list\">\n      <li><strong>Symbols of Circuit Components:</strong>\n        <ul>\n          <li><strong>Electric Cell:</strong> Represented by two parallel lines — one long thin line (+ positive terminal) and one shorter thick line (- negative terminal).</li>\n          <li><strong>Battery:</strong> A combination of two or more cells connected such that the positive terminal of one cell connects to the negative terminal of the next.</li>\n          <li><strong>Switch:</strong> Shown open (OFF - incomplete circuit) or closed (ON - complete closed circuit).</li>\n          <li><strong>Electric Bulb:</strong> A circle enclosing an incandescent filament loop.</li>\n        </ul>\n      </li>\n      <li><strong>Heating Effect of Electric Current (Joule Heating):</strong>\n        <ul>\n          <li>When an electric current flows through a high-resistance wire, electrical energy is converted into heat energy. The wire becomes hot.</li>\n          <li>Amount of heat produced depends on the wire's <em>material</em>, <em>length</em>, <em>thickness</em>, and the <em>magnitude of current</em>.</li>\n          <li><em>Heating Appliances:</em> Electric iron, room heater, geyser, toaster use coils of high-resistance wire called <strong>elements</strong> (usually made of Nichrome alloy).</li>\n          <li><em>Electric Fuse:</em> A safety device made of a special wire with a low melting point. If excessive current surges through the circuit due to overloading or short-circuiting, the fuse wire melts and breaks the circuit, preventing fires and device damage.</li>\n          <li><em>MCB (Miniature Circuit Breaker):</em> Modern electromagnetic/bimetallic switch that automatically trips OFF when current exceeds safe limits; easily reset without wire replacement.</li>\n        </ul>\n      </li>\n      <li><strong>Magnetic Effect of Electric Current (Electromagnetism):</strong>\n        <ul>\n          <li>Discovered in 1820 by Danish physicist <strong>Hans Christian Oersted</strong>, who noticed that a magnetic compass needle deflects whenever current passes through a nearby wire.</li>\n          <li><strong>Electromagnet:</strong> An insulated wire coil wound tightly around a soft iron core. It behaves like a magnet only when electric current flows through it. Magnetism disappears immediately when current is switched off.</li>\n          <li><em>Applications:</em> Scrap-metal cranes, electric bells, telephone receivers, MRI machines, maglev trains.</li>\n          <li><em>Electric Bell:</em> Operates on an electromagnet, an armature with a striker hammer, an adjustment contact screw, and a metallic gong in a self-breaking circuit loop.</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n\n  <div class=\"ex-div\">NCERT Textbook Exercise Questions</div>\n\n  <!-- Q1 -->\n  <div class=\"q-card\" id=\"q10_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Draw in your notebook the symbols to represent the following components of electrical circuits: connecting wires, switch in the ‘OFF’ position, bulb, cell, switch in the ‘ON’ position, and battery.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr><th>Electrical Component</th><th>Standard Circuit Symbol Description</th><th>Graphical Description / Symbol Representation</th></tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td><strong>1. Connecting Wire</strong></td>\n                <td>Straight solid continuous line</td>\n                <td><strong>───</strong> (A straight horizontal conductive line)</td>\n              </tr>\n              <tr>\n                <td><strong>2. Switch in 'OFF' position</strong></td>\n                <td>Open key with gap (broken line)</td>\n                <td><strong>──o &nbsp; /o──</strong> (Two terminals with arm raised open)</td>\n              </tr>\n              <tr>\n                <td><strong>3. Electric Bulb</strong></td>\n                <td>Loop inside a circle</td>\n                <td>A circle enclosing a coiled filament loop: <strong>( ⌒ )</strong></td>\n              </tr>\n              <tr>\n                <td><strong>4. Electric Cell</strong></td>\n                <td>Long thin line (+), short thick line (-)</td>\n                <td><strong>──| ▎──</strong> (Long line = positive, thick short line = negative)</td>\n              </tr>\n              <tr>\n                <td><strong>5. Switch in 'ON' position</strong></td>\n                <td>Closed key (arm making contact)</td>\n                <td><strong>──o───o──</strong> (Both terminal dots bridged by solid line)</td>\n              </tr>\n              <tr>\n                <td><strong>6. Battery</strong></td>\n                <td>Series combination of cell symbols</td>\n                <td><strong>──| ▎──| ▎──| ▎──</strong> (Long thin line followed by short thick line repeatedly)</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct electrical symbol drawn and labelled (0.5 Mark × 6)</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q2 -->\n  <div class=\"q-card\" id=\"q10_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Draw the circuit diagram to represent the circuit shown in Fig. 10.21 (consisting of a single electric cell, a bulb, a switch in the ON position, and connecting wires).</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>A <strong>circuit diagram</strong> represents an electrical circuit using standardized schematic symbols rather than pictorial drawings of actual components.</p>\n          <div class=\"step\">\n            <strong>Components to Connect in Series:</strong>\n            <ol>\n              <li><strong>Electric Cell:</strong> Draw a long thin line (+ve terminal) and a parallel shorter thick line (-ve terminal).</li>\n              <li><strong>Connecting Wire:</strong> Draw straight lines at right angles joining the components.</li>\n              <li><strong>Switch in 'ON' position:</strong> Draw two terminal dots bridged by a straight closed line (or a closed key).</li>\n              <li><strong>Electric Bulb:</strong> Draw a circle enclosing a filament loop. Since the switch is ON and the circuit is closed, add radiating lines around the bulb to depict glowing.</li>\n            </ol>\n          </div>\n          <div class=\"step\">\n            <strong>Schematic Trace:</strong><br>\n            Cell (+ terminal) ─── Connecting Wire ─── Switch (ON) ─── Electric Bulb (Glowing) ─── Connecting Wire ─── Cell (- terminal).\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct use of all 4 standard schematic symbols in closed loop</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Neat rectangular layout and indication of glowing bulb</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q3 -->\n  <div class=\"q-card\" id=\"q10_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Fig. 10.22 shows four cells fixed on a board. Draw lines to indicate how you will connect their terminals with wires to make a battery of four cells.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>To construct a battery of four cells, the cells must be connected in series such that the <strong>positive terminal (+, metallic cap)</strong> of one cell is connected to the <strong>negative terminal (-, flat zinc base)</strong> of the adjacent cell.</p>\n          <div class=\"step\">\n            <strong>Wiring Sequence for 4 Cells (labelled 1, 2, 3, 4):</strong>\n            <ul>\n              <li>Connect the <strong>negative terminal (-) of Cell 1</strong> to the <strong>positive terminal (+) of Cell 2</strong> using a connecting wire.</li>\n              <li>Connect the <strong>negative terminal (-) of Cell 2</strong> to the <strong>positive terminal (+) of Cell 3</strong> using a connecting wire.</li>\n              <li>Connect the <strong>negative terminal (-) of Cell 3</strong> to the <strong>positive terminal (+) of Cell 4</strong> using a connecting wire.</li>\n              <li>The <strong>positive terminal (+) of Cell 1</strong> and the <strong>negative terminal (-) of Cell 4</strong> serve as the two free external terminals of the combined 4-cell battery to power the circuit.</li>\n            </ul>\n          </div>\n          <div class=\"step\">\n            <strong>Key Rule:</strong> Never connect positive to positive (+ to +) or negative to negative (- to -), as their opposing electromotive forces will cancel each other out and no current will flow.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct opposite terminal (+ to -) series connection rule</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clear wiring layout identifying two free external terminals</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q4 -->\n  <div class=\"q-card\" id=\"q10_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">The bulb in the circuit shown in Fig. 10.23 does not glow. Can you identify the problem? Make necessary changes in the circuit to make the bulb glow.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Identification of the Problem:</strong><br>\n            In the given circuit, the two cells are connected incorrectly: the <strong>positive terminal of the first cell is connected to the positive terminal of the second cell</strong> (+ to +). Because similar polarity terminals oppose each other, the net voltage across the circuit is zero, preventing electric current from flowing.\n          </div>\n          <div class=\"step\">\n            <strong>Necessary Changes:</strong><br>\n            Turn one of the cells around so that the <strong>positive terminal (+, brass cap) of the first cell connects to the negative terminal (-, zinc base) of the second cell</strong>.<br>\n            Once the cells are connected in series with opposite polarities, a complete closed circuit is formed and the bulb will glow brightly.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of identical polarities connected together (+ to +)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Corrective measure (+ to - connection) to allow current flow</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q5 -->\n  <div class=\"q-card\" id=\"q10_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Name any two effects of electric current.</div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Two major effects produced by electric current are:</p>\n          <div class=\"step\">\n            <strong>1. Heating Effect of Electric Current:</strong> Conversion of electrical energy into thermal energy when current passes through a resistive conductor (e.g., electric iron, water geyser, room heater, fuse wire).\n          </div>\n          <div class=\"step\">\n            <strong>2. Magnetic Effect of Electric Current:</strong> Production of an invisible magnetic field around a current-carrying conductor (e.g., electromagnets, electric bells, electric motors).\n          </div>\n          <p><em>(Note: Electric current also exhibits a Chemical Effect, e.g., electroplating).</em></p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing Heating effect and Magnetic effect (0.5 Mark each)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q6 -->\n  <div class=\"q-card\" id=\"q10_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">When the current is switched on through a wire, a compass needle kept nearby gets deflected from its north-south position. Explain.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Scientific Explanation:</strong></p>\n          <div class=\"step\">\n            <ul>\n              <li>A compass needle is a tiny, freely pivoted <strong>permanent magnet</strong> that aligns itself along Earth's geomagnetic North-South axis when no other magnetic field is present.</li>\n              <li>When electric current flows through the adjacent wire, the wire generates a <strong>magnetic field around itself</strong> (the <em>magnetic effect of electric current</em>, discovered by Hans Christian Oersted).</li>\n              <li>This newly generated magnetic field exerts a mechanical magnetic force on the compass needle.</li>\n              <li>The interaction between the magnetic field of the current-carrying wire and the permanent magnetic field of the compass needle forces the needle to deflect away from its natural North-South position.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Mention of compass needle being a tiny magnet</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Current-carrying wire producing a magnetic field causing magnetic interaction</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q7 -->\n  <div class=\"q-card\" id=\"q10_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Will the compass needle show deflection when the switch in the circuit shown by Fig. 10.24 is closed? Explain.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Answer: No, the compass needle will NOT show any deflection.</strong></p>\n          <div class=\"step\">\n            <strong>Scientific Reason:</strong>\n            <ul>\n              <li>The circuit shown in Fig. 10.24 consists only of a bulb, connecting wires, and a switch — it <strong>lacks an electric source (no electric cell or battery)</strong>.</li>\n              <li>Without an electromotive power source (cell/battery), no potential difference exists to push electric charges through the circuit.</li>\n              <li>Even when the switch is closed, <strong>no electric current flows</strong> through the wire (<span class=\"math\">I = 0</span>).</li>\n              <li>Since there is no electric current, no magnetic field is generated around the wire. Therefore, the magnetic compass needle remains completely undeflected in its resting North-South alignment.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Direct 'No' answer</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Absence of electric cell/battery leading to zero current and zero magnetic field</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q8 -->\n  <div class=\"q-card\" id=\"q10_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">Fill in the blanks:<br>\n        (a) Longer line in the symbol for a cell represents its ______ terminal.<br>\n        (b) The combination of two or more cells is called a ______.<br>\n        (c) When current is switched ‘on’ in a room heater, it produces ______.<br>\n        (d) The safety device based on the heating effect of electric current is called a ______.\n      </div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>(a)</strong> Longer line in the symbol for a cell represents its <strong>positive (+)</strong> terminal.</p>\n          <p><strong>(b)</strong> The combination of two or more cells is called a <strong>battery</strong>.</p>\n          <p><strong>(c)</strong> When current is switched ‘on’ in a room heater, it produces <strong>heat</strong> (due to red-hot nichrome heating elements).</p>\n          <p><strong>(d)</strong> The safety device based on the heating effect of electric current is called a <strong>fuse</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct term correctly identified (0.5 Mark × 4)</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q9 -->\n  <div class=\"q-card\" id=\"q10_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">Mark ‘T’ if the statement is true and ‘F’ if it is false:<br>\n        (a) To make a battery of two cells, the negative terminal of one cell is connected to the negative terminal of the other cell. (T/F)<br>\n        (b) When the electric current through the fuse exceeds a certain limit, the fuse wire melts and breaks. (T/F)<br>\n        (c) An electromagnet does not attract a piece of iron. (T/F)<br>\n        (d) An electric bell has an electromagnet. (T/F)\n      </div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) False (F):</strong><br>\n            <em>Reason:</em> To form a functioning battery, the negative terminal of one cell must be connected to the positive terminal of the other cell.\n          </div>\n          <div class=\"step\">\n            <strong>(b) True (T):</strong><br>\n            <em>Reason:</em> A fuse wire is fabricated from an alloy with a specific low melting point. Excess current generates excessive heat (<span class=\"math\">H = I²Rt</span>), melting the wire and isolating the circuit.\n          </div>\n          <div class=\"step\">\n            <strong>(c) False (F):</strong><br>\n            <em>Reason:</em> An electromagnet behaves like a strong magnet when energized and exerts a powerful magnetic attraction on ferromagnetic materials like iron and steel.\n          </div>\n          <div class=\"step\">\n            <strong>(d) True (T):</strong><br>\n            <em>Reason:</em> An electric bell incorporates an electromagnet (a U-shaped soft iron core wound with coils) to repeatedly attract the iron armature hammer.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with scientific justification (0.5 Mark × 4)</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q10 -->\n  <div class=\"q-card\" id=\"q10_10\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_10')\">\n      <div class=\"q-num\">Q10</div>\n      <div class=\"q-text\">Do you think an electromagnet can be used for separating plastic bags from a garbage heap? Explain.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Answer: No, an electromagnet cannot be used to separate plastic bags from a garbage heap.</strong></p>\n          <div class=\"step\">\n            <strong>Scientific Reason:</strong>\n            <ul>\n              <li>An electromagnet produces a magnetic field and can only attract <strong>magnetic substances</strong> such as iron, cobalt, nickel, and steel.</li>\n              <li><strong>Plastic</strong> is a completely non-magnetic polymer. It does not possess magnetic dipoles and is unaffected by magnetic lines of force.</li>\n              <li>Therefore, an electromagnet will not exert any attractive force on plastic bags. Scrap heaps utilize electromagnets only to extract ferromagnetic scrap iron, not plastics.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clear 'No' assertion</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation that magnets only attract magnetic substances, while plastic is non-magnetic</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q11 -->\n  <div class=\"q-card\" id=\"q10_11\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_11')\">\n      <div class=\"q-num\">Q11</div>\n      <div class=\"q-text\">An electrician is carrying out some repairs in your house. He wants to replace a fuse by a piece of wire. Would you agree? Give reasons for your response.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Answer: No, I would strictly disagree and forbid the electrician from replacing the fuse with an ordinary piece of wire.</strong></p>\n          <div class=\"step\">\n            <strong>Scientific Reasons:</strong>\n            <ul>\n              <li><strong>Specific Low Melting Point:</strong> Standard fuse wire is manufactured from a specialized tin-lead alloy engineered with a low melting point and precise current rating.</li>\n              <li><strong>Ordinary Wires Do Not Melt:</strong> Ordinary connecting copper or aluminium wires have very high melting points and can withstand very high electrical currents without breaking.</li>\n              <li><strong>Severe Fire &amp; Damage Hazard:</strong> If an electrical overload or short-circuit occurs, an ordinary copper wire will not melt. The heavy current will flow unchecked through household appliances, damaging expensive electronics, melting wall wiring insulation, and potentially causing an electrical building fire.</li>\n              <li><strong>Safe Alternative:</strong> Only an ISI-marked fuse cartridge of the correct rated amperage (e.g., 5 A or 15 A) or a Miniature Circuit Breaker (MCB) must be installed.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clear 'No' position</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Comparison of low melting point of fuse vs high melting point of ordinary wire</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Risk of appliance destruction and fire hazards</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q12 -->\n  <div class=\"q-card\" id=\"q10_12\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_12')\">\n      <div class=\"q-num\">Q12</div>\n      <div class=\"q-text\">Zubeda made an electric circuit using a cell holder, a switch and a bulb. When she put the switch in the ‘ON’ position, the bulb did not glow. Help Zubeda in identifying the possible defects in the circuit.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>The bulb may fail to glow due to any of the following technical defects in the circuit:</p>\n          <div class=\"step\">\n            <ol>\n              <li><strong>Incorrect Cell Polarity:</strong> The cells in the cell holder may be placed backwards, connecting like terminals together (+ to + or - to -) instead of opposite terminals (+ to -).</li>\n              <li><strong>Exhausted / Discharged Cells:</strong> The chemical energy of the dry cells might be completely depleted (dead cells).</li>\n              <li><strong>Fused Bulb:</strong> The tungsten filament inside the bulb might be broken, resulting in an open circuit.</li>\n              <li><strong>Loose Connections:</strong> Connecting wires may not be tightly fastened to the terminals of the cell holder, switch, or bulb socket.</li>\n              <li><strong>Oxidation / Dirt on Terminals:</strong> Corrosion or rust on the metal contacts of the cell holder or switch contacts may introduce high contact resistance, blocking current flow.</li>\n              <li><strong>Faulty Switch:</strong> The switch contacts might not make proper conductive contact when moved to the 'ON' position.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Any 3 well-explained possible defects (1 Mark each)</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q13 -->\n  <div class=\"q-card\" id=\"q10_13\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_13')\">\n      <div class=\"q-num\">Q13</div>\n      <div class=\"q-text\">In the circuit shown in Fig. 10.25 (with bulbs A, B, and C connected in series along with a switch and a cell):<br>\n        (i) Would any of the bulbs glow when the switch is in the ‘OFF’ position?<br>\n        (ii) What will be the order in which the bulbs A, B and C will glow when the switch is moved to the ‘ON’ position?\n      </div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(i) When switch is in 'OFF' position:</strong><br>\n            <strong>None of the bulbs will glow.</strong> When the switch is OFF, the electrical circuit is incomplete (open circuit). Electric current cannot flow across any part of an open circuit.\n          </div>\n          <div class=\"step\">\n            <strong>(ii) When switch is moved to 'ON' position:</strong><br>\n            <strong>All three bulbs (A, B, and C) will glow simultaneously at the exact same instant.</strong><br>\n            <em>Scientific Justification:</em> Electric current is the collective drift of free electrons present throughout the conducting wire loop. The moment the switch is closed, the electric field propagates through the circuit almost instantaneously at nearly the speed of light (<span class=\"math\">~3 × 10⁸ m/s</span>). Therefore, current starts flowing through every series component simultaneously, causing bulbs A, B, and C to illuminate together without any human-perceptible time delay.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (i): Stating none of the bulbs glow due to open circuit</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Part (ii): Stating all bulbs glow simultaneously with scientific reasoning</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#059669;\">Case Study: Modern Home Electrical Safety — Fuse vs MCB</div>\n        <div class=\"cbq-question\">\n          <strong>Domestic Electrical Engineering:</strong> In an older apartment, a blown traditional porcelain fuse often plunged the house into darkness, requiring someone to search for fuse wire and rewire the cartridge in the dark. During renovation, an electrical engineer replaced all traditional fuses with Miniature Circuit Breakers (MCBs).<br><br>\n          (i) On which two physical principles do MCBs operate to interrupt excessive current?<br>\n          (ii) Why are MCBs considered far superior and safer than traditional rewirable fuses?<br>\n          (iii) What should a homeowner inspect before resetting a tripped MCB back to the ON position?\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Operating Principles:</strong> MCBs utilize two trip mechanisms:\n            <br>1. <em>Thermal effect (Bimetallic strip):</em> For gradual sustained overloads, resistive heating causes a bimetallic strip to bend and mechanically release the latch.\n            <br>2. <em>Magnetic effect (Solenoid coil):</em> For dangerous instantaneous short circuits, high surge current energizes an internal electromagnet plunger that instantly trips the contact open in milliseconds.\n          </p>\n          <p><strong>(ii) Advantages of MCBs:</strong>\n            <br>• <em>Quick Reset:</em> Simply flip the toggle switch back up — no messy wire handling or risk of touching live terminals.\n            <br>• <em>Tamper-proof Safety:</em> Calibrated factory ratings cannot be bypassed by using an oversized wire.\n            <br>• <em>High Sensitivity:</em> Trips in 2.5 milliseconds, minimizing fire risk and appliance damage.\n          </p>\n          <p><strong>(iii) Safety Inspection:</strong> The homeowner must unplug the faulty appliance or rectify the underlying short circuit / overload that triggered the trip before flicking the MCB back ON, otherwise it will trip again instantly.</p>\n        </div>\n      </div>\n\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">⚡ Assertion &amp; Reason (HOTS)</div>\n        <div class=\"cbq-question\">\n          <strong>Assertion (A):</strong> An electromagnet can be switched ON and OFF at will and its magnetic strength can be varied by adjusting the electric current.<br>\n          <strong>Reason (R):</strong> The magnetic field of an electromagnet is produced by the electric current flowing through its solenoid coil, and soft iron cores lose their magnetism as soon as current stops.<br><br>\n          Choose the correct option:<br>\n          (a) Both A and R are true, and R is the correct explanation of A.<br>\n          (b) Both A and R are true, but R is not the correct explanation of A.<br>\n          (c) A is true, but R is false.<br>\n          (d) A is false, but R is true.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>Answer: (a) Both A and R are true, and R is the correct explanation of A.</strong></p>\n          <p><em>Scientific Explanation:</em> Unlike permanent magnets whose strength and poles are fixed, electromagnets are temporary magnets. Increasing current or number of coil turns amplifies magnetic flux, and cutting current drops magnetization to zero immediately, making them indispensable in heavy crane hoists and relays.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(9)\">← Chapter 9: Motion and Time</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(11)\">Chapter 11: Light →</button>\n  </div>\n</section>\n","11":"<section class=\"chapter-section\" id=\"ch11\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">11</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 11: Light</h2>\n      <p>NCERT Exercise Solutions — Complete Step-by-Step Answers with CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Scientific Concepts &amp; Optics Fundamentals</div>\n    <ul class=\"concept-list\">\n      <li><strong>Rectilinear Propagation &amp; Reflection of Light:</strong>\n        <ul>\n          <li>Light travels in straight lines (rectilinear propagation). When light falls on a polished, shiny surface, its direction changes — a phenomenon known as <strong>reflection of light</strong>.</li>\n          <li><strong>Plane Mirror Image Characteristics:</strong>\n            <ol>\n              <li>The image is <strong>erect</strong> (upright) and <strong>virtual</strong> (cannot be caught on a screen).</li>\n              <li>The size of the image is <strong>identical to the object</strong>.</li>\n              <li>The distance of the image behind the mirror is <strong>equal</strong> to the distance of the object in front of the mirror.</li>\n              <li>The image exhibits <strong>lateral inversion</strong>: the left side of the object appears as the right side of the image, and vice versa.</li>\n            </ol>\n          </li>\n        </ul>\n      </li>\n      <li><strong>Spherical Mirrors:</strong>\n        <ul>\n          <li><strong>Concave Mirror (Converging):</strong> Inner curved surface is reflecting. Can form real, inverted images (diminished, same size, or magnified) when the object is beyond the focus; forms an <em>erect, enlarged, and virtual image</em> when placed very close (between pole and focus). Used by dentists, in solar furnaces, torch reflectors, and shaving mirrors.</li>\n          <li><strong>Convex Mirror (Diverging):</strong> Outer bulging surface is reflecting. Always forms an <em>erect, virtual, and diminished (smaller)</em> image over a very wide field of view. Used as rear-view mirrors in automobiles.</li>\n        </ul>\n      </li>\n      <li><strong>Spherical Lenses:</strong>\n        <ul>\n          <li><strong>Convex Lens (Converging):</strong> Thicker at the middle than at edges. Converges incident parallel light rays. Can form real and inverted images, or a virtual, erect, and magnified image when held close to an object (used as a <strong>magnifying glass</strong> and in spectacles for hypermetropia).</li>\n          <li><strong>Concave Lens (Diverging):</strong> Thinner at the middle than at edges. Diverges incident parallel light rays. Always forms an <em>erect, virtual, and diminished</em> image regardless of object distance.</li>\n        </ul>\n      </li>\n      <li><strong>Dispersion of Light &amp; Sunlight:</strong>\n        <ul>\n          <li>White sunlight consists of seven distinct constituent colours: <strong>Violet, Indigo, Blue, Green, Yellow, Orange, Red (VIBGYOR)</strong>.</li>\n          <li>A glass prism splits white light into its seven constituent colours (dispersion of light), forming a rainbow spectrum.</li>\n          <li><strong>Newton's Disc:</strong> A circular disc painted with the seven rainbow segments rotated rapidly blends into a uniform white appearance, demonstrating that white light is a composite of the seven colours.</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n\n  <div class=\"ex-div\">NCERT Textbook Exercise Questions</div>\n\n  <!-- Q1 -->\n  <div class=\"q-card\" id=\"q11_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Fill in the blanks:<br>\n        (a) An image that cannot be obtained on a screen is called ______.<br>\n        (b) Image formed by a convex ______ is always virtual and smaller in size.<br>\n        (c) An image formed by a ______ mirror is always of the same size as that of the object.<br>\n        (d) An image which can be obtained on a screen is called a ______ image.<br>\n        (e) An image formed by a concave ______ cannot be obtained on a screen.\n      </div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>(a)</strong> An image that cannot be obtained on a screen is called a <strong>virtual image</strong>.</p>\n          <p><strong>(b)</strong> Image formed by a convex <strong>mirror</strong> (or concave lens) is always virtual and smaller in size.</p>\n          <p><strong>(c)</strong> An image formed by a <strong>plane</strong> mirror is always of the same size as that of the object.</p>\n          <p><strong>(d)</strong> An image which can be obtained on a screen is called a <strong>real</strong> image.</p>\n          <p><strong>(e)</strong> An image formed by a concave <strong>lens</strong> cannot be obtained on a screen (because it is always virtual).</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct blank accurately filled (0.5 Mark × 5)</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q2 -->\n  <div class=\"q-card\" id=\"q11_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Mark ‘T’ if the statement is true and ‘F’ if it is false:<br>\n        (a) We can obtain an enlarged and erect image by a convex mirror. (T/F)<br>\n        (b) A concave lens always forms a virtual image. (T/F)<br>\n        (c) We can obtain a real, enlarged and inverted image by a concave mirror. (T/F)<br>\n        (d) A real image cannot be obtained on a screen. (T/F)<br>\n        (e) A concave mirror always forms a real image. (T/F)\n      </div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>(a) False (F):</strong><br>\n            <em>Reason:</em> A convex mirror always forms an erect, virtual, and <strong>diminished (smaller)</strong> image; it can never produce an enlarged image.\n          </div>\n          <div class=\"step\">\n            <strong>(b) True (T):</strong><br>\n            <em>Reason:</em> A concave lens is a diverging lens and always forms an erect, virtual, and diminished image for all object positions.\n          </div>\n          <div class=\"step\">\n            <strong>(c) True (T):</strong><br>\n            <em>Reason:</em> When an object is placed between the centre of curvature (C) and principal focus (F) of a concave mirror, it produces a real, inverted, and enlarged image beyond C.\n          </div>\n          <div class=\"step\">\n            <strong>(d) False (F):</strong><br>\n            <em>Reason:</em> By definition, a real image is formed by actual converging light rays and can always be captured on a physical screen.\n          </div>\n          <div class=\"step\">\n            <strong>(e) False (F):</strong><br>\n            <em>Reason:</em> When an object is positioned very close to a concave mirror (between the pole and focus), it forms a <strong>virtual and erect</strong> image behind the mirror.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct evaluation with scientific rationale (0.5 Mark × 5)</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q3 -->\n  <div class=\"q-card\" id=\"q11_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Match the items given in Column I with one or more items of Column II:<br>\n        <strong>Column I:</strong><br>\n        (a) A plane mirror<br>\n        (b) A convex mirror<br>\n        (c) A convex lens<br>\n        (d) A concave mirror<br>\n        (e) A concave lens<br>\n        <strong>Column II:</strong><br>\n        (i) Used as a magnifying glass.<br>\n        (ii) Can form image of objects spread over a large area.<br>\n        (iii) Used by dentists to see enlarged image of teeth.<br>\n        (iv) The image is always inverted and magnified.<br>\n        (v) The image is erect and of the same size than the object.<br>\n        (vi) The image is erect and smaller in size than the object.\n      </div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr><th>Column I (Optical Device)</th><th>Column II (Matched Optical Properties / Application)</th></tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td><strong>(a) A plane mirror</strong></td>\n                <td><strong>(v) The image is erect and of the same size as the object.</strong></td>\n              </tr>\n              <tr>\n                <td><strong>(b) A convex mirror</strong></td>\n                <td><strong>(ii) Can form image of objects spread over a large area</strong> (wide field of view), and <strong>(vi) The image is erect and smaller in size than the object</strong>.</td>\n              </tr>\n              <tr>\n                <td><strong>(c) A convex lens</strong></td>\n                <td><strong>(i) Used as a magnifying glass</strong> (when object placed close to lens).</td>\n              </tr>\n              <tr>\n                <td><strong>(d) A concave mirror</strong></td>\n                <td><strong>(iii) Used by dentists to see enlarged image of teeth</strong> (erect magnified virtual image).</td>\n              </tr>\n              <tr>\n                <td><strong>(e) A concave lens</strong></td>\n                <td><strong>(vi) The image is erect and smaller in size than the object</strong>.</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct matching alignment (0.5 Mark × 5)</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q4 -->\n  <div class=\"q-card\" id=\"q11_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">State the characteristics of the image formed by a plane mirror.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>The image formed by a flat plane mirror possesses the following distinct physical characteristics:</p>\n          <div class=\"step\">\n            <ol>\n              <li><strong>Virtual Image:</strong> It is formed behind the mirror where reflected rays appear to diverge from, and cannot be captured or projected on a screen.</li>\n              <li><strong>Erect (Upright):</strong> The image stands right side up in the exact orientation as the object.</li>\n              <li><strong>Same Size:</strong> The height and width of the image are exactly identical to the dimensions of the object (<span class=\"math\">Magnification m = +1</span>).</li>\n              <li><strong>Equal Distance:</strong> The distance of the image behind the mirror surface is exactly equal to the distance of the object in front of the mirror (<span class=\"math\">Image Distance = Object Distance</span>).</li>\n              <li><strong>Laterally Inverted:</strong> The image exhibits <strong>lateral inversion</strong>, meaning the left side of the real object appears as the right side in the mirror image, and vice versa.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Any 3 core characteristics correctly stated (1 Mark each)</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q5 -->\n  <div class=\"q-card\" id=\"q11_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Find out the letters of English alphabet or any other language known to you in which the image formed in a plane mirror appears exactly like the letter itself. Discuss your findings.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Symmetrical Capital Letters of English Alphabet:</strong><br>\n            The letters whose plane mirror image appears identical to the original letter itself are:\n            <div class=\"math\" style=\"font-size:1.1rem; letter-spacing:4px; margin:8px 0;\">A, H, I, M, O, T, U, V, W, X, Y</div>\n          </div>\n          <div class=\"step\">\n            <strong>Discussion &amp; Scientific Reason:</strong>\n            <ul>\n              <li>Although every image in a plane mirror undergoes <strong>lateral inversion</strong> (reversal of left and right), these specific 11 letters possess a <strong>vertical line of reflective symmetry</strong> through their middle.</li>\n              <li>Because their left half is the exact mirror image of their right half, swapping the left and right sides during mirror reflection does not produce any visible change in their overall appearance.</li>\n              <li>Conversely, asymmetric letters like <strong>B, C, D, E, F, G, J, K, L, N, P, Q, R, S, Z</strong> do not have a vertical axis of symmetry, so their lateral inversion is immediately noticeable as reversed characters.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Listing vertically symmetrical letters (A, H, I, M, O, T, U, V, W, X, Y)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Scientific explanation based on vertical line symmetry</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q6 -->\n  <div class=\"q-card\" id=\"q11_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">What is a virtual image? Give one situation where a virtual image is formed.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Definition of Virtual Image:</strong><br>\n            A <strong>virtual image</strong> is an optical image formed when light rays originating from an object do not actually intersect at a physical point, but only appear to diverge from a location behind the reflecting or refracting surface. Consequently, a virtual image <strong>cannot be captured or obtained on a screen</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>Situations where a virtual image is formed:</strong>\n            <ul>\n              <li>The everyday image of our face seen when looking into a <strong>plane mirror</strong> inside a dressing room.</li>\n              <li>The smaller, upright rear view of following highway traffic observed in the <strong>convex side-view mirror</strong> of an automobile.</li>\n              <li>The magnified upright letters viewed through a <strong>convex lens (magnifying glass)</strong> held close to a page.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clear definition (rays appear to diverge, cannot be cast on screen)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">One valid everyday situation (e.g. plane mirror or convex mirror)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q7 -->\n  <div class=\"q-card\" id=\"q11_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">State two differences between a convex and a concave lens.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr><th>Feature</th><th>Convex Lens (Converging Lens)</th><th>Concave Lens (Diverging Lens)</th></tr>\n            </thead>\n            <tbody>\n              <tr>\n                <td><strong>1. Physical Geometry</strong></td>\n                <td>It is <strong>thicker in the middle</strong> and thinner at its peripheral edges.</td>\n                <td>It is <strong>thinner in the middle</strong> and thicker at its peripheral edges.</td>\n              </tr>\n              <tr>\n                <td><strong>2. Action on Parallel Light Rays</strong></td>\n                <td>It <strong>converges</strong> (brings together) parallel incoming light rays to a focal point.</td>\n                <td>It <strong>diverges</strong> (spreads out) parallel incoming light rays away from the axis.</td>\n              </tr>\n              <tr>\n                <td><strong>3. Nature of Images Formed</strong></td>\n                <td>Can form both real (inverted) images and virtual (magnified, erect) images depending on distance.</td>\n                <td>Always forms an <strong>erect, virtual, and diminished (smaller)</strong> image for all positions.</td>\n              </tr>\n              <tr>\n                <td><strong>4. Common Application</strong></td>\n                <td>Used as a magnifying glass, in microscopes, and cameras.</td>\n                <td>Used in peepholes of doors and spectacles for myopia.</td>\n              </tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Any 2 clear, accurate distinguishing differences (1 Mark each)</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q8 -->\n  <div class=\"q-card\" id=\"q11_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">Give one use each of a concave and a convex mirror.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. Use of a Concave Mirror:</strong><br>\n            • <em>Use:</em> <strong>Used by dentists to examine teeth</strong> (or in automobile headlights and shaving mirrors).<br>\n            • <em>Scientific Reason:</em> When held close to a tooth (within its focal length), a concave mirror forms an <strong>erect, enlarged (magnified), and clear virtual image</strong>, enabling the dentist to spot small cavities easily.\n          </div>\n          <div class=\"step\">\n            <strong>2. Use of a Convex Mirror:</strong><br>\n            • <em>Use:</em> <strong>Used as rear-view (wing) mirrors in automobiles</strong> (cars, buses, motorcycles).<br>\n            • <em>Scientific Reason:</em> Convex mirrors always form an erect and diminished image, giving the driver a <strong>much wider field of view</strong> of traffic trailing behind than a flat plane mirror could ever provide.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Use of concave mirror with scientific reason</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Use of convex mirror with scientific reason</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q9 -->\n  <div class=\"q-card\" id=\"q11_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">Which type of mirror can form a real image?</div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Answer: A Concave Mirror.</strong></p>\n          <p><em>Scientific Explanation:</em> Because a concave mirror is a converging spherical mirror, reflected light rays physically intersect in front of the mirror whenever the object is placed at or beyond the principal focus (F), thereby projecting a genuine <strong>real and inverted image</strong> that can be caught on a screen.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Concave mirror identified with converging explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q10 -->\n  <div class=\"q-card\" id=\"q10_10\">\n    <div class=\"q-head\" onclick=\"toggleQ('q10_10')\">\n      <div class=\"q-num\">Q10</div>\n      <div class=\"q-text\">Which type of lens forms always a virtual image?</div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Answer: A Concave Lens.</strong></p>\n          <p><em>Scientific Explanation:</em> A concave lens is a diverging lens that bends refracted light rays outwards away from the principal axis. These rays never converge in real space; when traced backwards, they appear to intersect, forming an image that is <strong>always virtual, erect, and diminished</strong>, irrespective of the object's distance.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Concave lens named with diverging property</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q11 -->\n  <div class=\"q-card\" id=\"q11_11\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_11')\">\n      <div class=\"q-num\">Q11</div>\n      <div class=\"q-text\">Choose the correct option: A virtual image larger than the object can be produced by a:<br>\n        (i) concave lens<br>\n        (ii) concave mirror<br>\n        (iii) convex mirror<br>\n        (iv) plane mirror\n      </div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (ii) concave mirror</strong></p>\n          <div class=\"step\">\n            <strong>Scientific Justification:</strong>\n            <ul>\n              <li>A <em>plane mirror</em> always forms a virtual image of the <em>exact same size</em> as the object.</li>\n              <li>A <em>convex mirror</em> always forms a virtual image that is <em>diminished (smaller)</em>.</li>\n              <li>A <em>concave lens</em> always forms a virtual image that is <em>diminished (smaller)</em>.</li>\n              <li>Only a <strong>concave mirror</strong> can produce an <strong>enlarged (magnified) virtual image</strong> when an object is held close to it (between its pole and focus).</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct option (ii) concave mirror with justification</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q12 -->\n  <div class=\"q-card\" id=\"q11_12\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_12')\">\n      <div class=\"q-num\">Q12</div>\n      <div class=\"q-text\">David is observing his image in a plane mirror. The distance between the mirror and his image is 4 m. If he moves 1 m towards the mirror, then the distance between David and his image will be:<br>\n        (i) 3 m<br>\n        (ii) 5 m<br>\n        (iii) 6 m<br>\n        (iv) 8 m\n      </div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (iii) 6 m</strong></p>\n          <div class=\"step\">\n            <strong>Detailed Step-by-Step Calculation:</strong>\n            <ol>\n              <li>In a plane mirror, <strong>Object Distance = Image Distance</strong> from the mirror surface.</li>\n              <li>Initially, the distance between the mirror and the image is 4 m. Hence, the initial distance of David (object) from the mirror was also 4 m.</li>\n              <li>When David walks 1 m towards the mirror, his new distance from the mirror becomes:<br>\n                <div class=\"math\">New Object Distance = 4 m - 1 m = 3 m</div>\n              </li>\n              <li>Consequently, the new image will form 3 m behind the mirror:<br>\n                <div class=\"math\">New Image Distance = 3 m</div>\n              </li>\n              <li>The total distance between David and his image is the sum of object distance and image distance:<br>\n                <div class=\"math\">Total Distance = 3 m + 3 m = 6 m</div>\n              </li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Calculation of new distance to mirror (3 m)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Total separation between person and image (6 m)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q13 -->\n  <div class=\"q-card\" id=\"q11_13\">\n    <div class=\"q-head\" onclick=\"toggleQ('q11_13')\">\n      <div class=\"q-num\">Q13</div>\n      <div class=\"q-text\">The rear view mirror of a car is a plane mirror. A driver is reversing his car at a speed of 2 m/s. The driver sees in his rear view mirror the image of a truck parked behind his car. The speed at which the image of the truck appears to approach the driver will be:<br>\n        (i) 1 m/s<br>\n        (ii) 2 m/s<br>\n        (iii) 4 m/s<br>\n        (iv) 8 m/s\n      </div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (iii) 4 m/s</strong></p>\n          <div class=\"step\">\n            <strong>Physical &amp; Relative Velocity Proof:</strong>\n            <ul>\n              <li>The truck is stationary (parked). As the car reverses towards the truck at a speed of 2 m/s, the physical distance between the car's mirror and the parked truck decreases at a rate of <strong>2 m/s</strong>.</li>\n              <li>In a plane mirror, the distance of the image behind the mirror is always equal to the distance of the object from the mirror.</li>\n              <li>Therefore, when the object distance decreases by 2 metres in 1 second, the image distance behind the mirror also decreases by 2 metres in that same 1 second.</li>\n              <li>Hence, relative to the driver sitting in the moving car:\n                <br>• The mirror moves 2 m closer to the truck.\n                <br>• The image advances 2 m closer towards the mirror.\n                <br>• The rate at which the image approaches the driver = <span class=\"math\">2 m/s + 2 m/s = 4 m/s</span>.\n              </li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Selection of 4 m/s (Option iii)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clear relative velocity / optical doubling explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#059669;\">Case Study: Automobile Safety &amp; \"AMBULANCE\" Inscription</div>\n        <div class=\"cbq-question\">\n          <strong>Optical Application:</strong> On emergency response ambulances, the word <strong>AMBULANCE</strong> is painted in reverse lettering on the front bonnet.<br><br>\n          (i) Which optical phenomenon of plane mirrors is this design based on?<br>\n          (ii) How does this reverse lettering assist the driver in a car moving in front of the ambulance?<br>\n          (iii) Why are convex mirrors, rather than plane mirrors, used for the wing/side-view mirrors in vehicles?\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Optical Phenomenon:</strong> <strong>Lateral Inversion</strong> — the property of plane mirrors where left and right sides are interchanged.</p>\n          <p><strong>(ii) Practical Benefit:</strong> When the driver of a vehicle ahead looks into their rear-view mirror, the laterally reversed word undergoes a second lateral inversion in the mirror, reading perfectly correctly as standard readable <strong>AMBULANCE</strong>. This allows the driver to immediately recognize the emergency and yield right-of-way without hesitation.</p>\n          <p><strong>(iii) Reason for Convex Mirrors:</strong> Convex mirrors are curved outwards (diverging), which allows them to capture rays from a much wider angle. They produce upright, diminished images that give the driver a <strong>substantially broader panoramic field of view</strong> of trailing highway traffic compared to flat plane mirrors.</p>\n        </div>\n      </div>\n\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">⚡ Assertion &amp; Reason (HOTS)</div>\n        <div class=\"cbq-question\">\n          <strong>Assertion (A):</strong> When white sunlight passes through a triangular glass prism, it emerges as a rainbow spectrum band of seven colours.<br>\n          <strong>Reason (R):</strong> White light is a composite mixture of seven colours (VIBGYOR), each having a different speed and angle of bending (refraction) inside glass.<br><br>\n          Choose the correct option:<br>\n          (a) Both A and R are true, and R is the correct explanation of A.<br>\n          (b) Both A and R are true, but R is not the correct explanation of A.<br>\n          (c) A is true, but R is false.<br>\n          (d) A is false, but R is true.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>Answer: (a) Both A and R are true, and R is the correct explanation of A.</strong></p>\n          <p><em>Scientific Explanation:</em> Dispersion occurs because violet light slows down the most and bends through the greatest angle, while red light slows down the least and bends the least upon entering glass. This differential refraction spreads the composite beam into the visible spectrum band (VIBGYOR).</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(10)\">← Chapter 10: Electric Current and its Effects</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(12)\">Chapter 12: Forests: Our Lifeline →</button>\n  </div>\n</section>\n","12":"<section class=\"chapter-section\" id=\"ch12\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">12</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 12: Forests: Our Lifeline</h2>\n      <p>NCERT Exercise Solutions — Complete Step-by-Step Answers with CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Scientific Concepts &amp; Forest Ecosystem Architecture</div>\n    <ul class=\"concept-list\">\n      <li><strong>Forest Structure &amp; Stratification:</strong>\n        <ul>\n          <li><strong>Canopy:</strong> The uppermost continuous roof formed by the crowns of tall mature trees over the forest floor.</li>\n          <li><strong>Understorey:</strong> The distinct horizontal layers formed below the canopy, consisting of smaller trees, shrubs, and tall bushes.</li>\n          <li><strong>Forest Floor:</strong> Covered with dead leaves, twigs, seeds, animal waste, and herbs; home to millipedes, beetles, fungi, and decomposers.</li>\n        </ul>\n      </li>\n      <li><strong>Ecosystem Balance &amp; Food Chains:</strong>\n        <ul>\n          <li>Forests are self-sustaining, dynamic living entities (a \"super-organism\").</li>\n          <li><strong>Food Chain:</strong> Energy flow from solar radiation to autotrophic producers (green plants) → primary consumers (herbivores like deer, grasshoppers) → secondary/tertiary consumers (carnivores like frogs, tigers) → decomposers.</li>\n          <li><strong>Decomposers:</strong> Micro-organisms (fungi, bacteria) that decompose dead organic matter into dark organic <strong>humus</strong>, recycling nutrients back into the soil for root uptake. <em>There is zero waste in a virgin forest.</em></li>\n        </ul>\n      </li>\n      <li><strong>Ecological &amp; Hydrological Services:</strong>\n        <ul>\n          <li><strong>\"Green Lungs\" of the Earth:</strong> Forests absorb atmospheric carbon dioxide (<span class=\"math\">CO₂</span>) through photosynthesis and replenish oxygen (<span class=\"math\">O₂</span>), preserving atmospheric gas equilibrium.</li>\n          <li><strong>Natural Water Filter &amp; Flood Barrier:</strong> Dense leaf canopies dissipate torrential rainfall impact, while extensive root networks bind the soil (preventing soil erosion) and facilitate rapid rainwater seepage into aquifers, maintaining the water table and preventing flash floods.</li>\n        </ul>\n      </li>\n    </ul>\n  </div>\n\n  <div class=\"ex-div\">NCERT Textbook Exercise Questions</div>\n\n  <!-- Q1 -->\n  <div class=\"q-card\" id=\"q12_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Explain how animals dwelling in the forest help it grow and regenerate.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Animals living in a forest play crucial symbiotic roles that stimulate forest growth, seed dispersal, and continuous regeneration:</p>\n          <div class=\"step\">\n            <ol>\n              <li><strong>Seed Dispersal:</strong> Herbivores and frugivorous birds feed on forest fruits. The indigestible seeds pass through their digestive tracts unharmed and are deposited far away with manure, allowing seedlings to sprout across new territories without overcrowding. Hooked seeds (like <em>Xanthium</em>) cling to animal fur and are carried to distant clearings.</li>\n              <li><strong>Pollination of Flowers:</strong> Flying insects (butterflies, bees, moths), birds, and bats visit flowers for nectar, transferring pollen grains between blossoms to ensure cross-pollination and viable seed formation.</li>\n              <li><strong>Nutrient Enrichment (Natural Manure):</strong> Animal excreta (dung, droppings) and decomposing carcasses provide essential organic matter. Microorganisms decompose these wastes into nutrient-rich <strong>humus</strong>, providing essential nitrogen, phosphorus, and potassium that fertilize germinating seedlings.</li>\n              <li><strong>Soil Aeration &amp; Overgrowth Control:</strong> Burrowing animals (earthworms, ants, rodents) loosen the soil, improving root respiration and water infiltration, while grazing animals prevent aggressive undergrowth from suffocating young saplings.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role in seed dispersal with examples</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role in cross-pollination</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role of excreta/manure in forming humus for regeneration</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q2 -->\n  <div class=\"q-card\" id=\"q12_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">Explain how forests prevent floods.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Forests act as <strong>natural giant sponges and flood control buffers</strong> through the following hydrological mechanisms:</p>\n          <div class=\"step\">\n            <ol>\n              <li><strong>Canopy Interception:</strong> The dense overhead roof of interlocking tree crowns and leaves intercepts torrential downpours, breaking the kinetic force of falling raindrops and preventing direct high-velocity impact on bare soil.</li>\n              <li><strong>Slow Drip to Forest Floor:</strong> Rainwater trickles slowly down tree trunks and drips gently onto the porous, litter-covered forest floor rather than surging over the surface.</li>\n              <li><strong>Natural Sponge &amp; Percolation:</strong> The thick spongy layer of decaying leaves, humus, and organic mulch absorbs vast quantities of water, allowing it to slowly percolate deep underground into aquifers, steadily recharging the groundwater table.</li>\n              <li><strong>Prevention of Surface Runoff &amp; Erosion:</strong> Extensive tree root networks bind the soil particles tightly, preventing them from being washed away (preventing siltation of rivers and reservoirs). By moderating surface runoff, forests ensure rivers receive a steady, controlled supply of water throughout the year rather than sudden catastrophic flash floods.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Canopy breaking impact of heavy rain</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Forest floor acting as sponge aiding groundwater percolation</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Roots binding soil and regulating surface runoff to prevent flash floods</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q3 -->\n  <div class=\"q-card\" id=\"q12_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">What are decomposers? Name any two of them. What do they do in the forest?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. Definition of Decomposers:</strong><br>\n            <strong>Decomposers</strong> are saprophytic micro-organisms that feed upon dead plant tissues, fallen leaves, rotten wood, and animal carcasses, breaking down complex organic molecules into simpler inorganic nutrients.\n          </div>\n          <div class=\"step\">\n            <strong>2. Examples of Decomposers:</strong><br>\n            • <strong>Bacteria</strong><br>\n            • <strong>Fungi (e.g., mushrooms, moulds)</strong>\n          </div>\n          <div class=\"step\">\n            <strong>3. Role in the Forest Ecosystem:</strong>\n            <ul>\n              <li>They convert dead plant and animal remains into a dark, crumbly organic substance known as <strong>humus</strong>.</li>\n              <li>Humus enriches the forest topsoil with essential mineral nutrients (nitrogen, carbon, potassium, phosphorus).</li>\n              <li>These released mineral nutrients are subsequently re-absorbed by tree roots, maintaining a <strong>continuous cyclic flow of nutrients</strong> in the ecosystem.</li>\n              <li>They prevent dead debris from piling up, serving as natural recyclers and cleaners of the forest floor.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Precise scientific definition of decomposers</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Two valid examples (Bacteria, Fungi)</span><span class=\"marking-marks\">0.5 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role in humus formation and recycling of mineral nutrients</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q4 -->\n  <div class=\"q-card\" id=\"q12_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Explain the role of forest in maintaining the balance between oxygen and carbon dioxide in the atmosphere.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Forests are globally recognized as the <strong>\"green lungs of nature\"</strong> because of their indispensable role in maintaining the atmospheric equilibrium of oxygen and carbon dioxide:</p>\n          <div class=\"step\">\n            <ol>\n              <li><strong>Photosynthesis (Oxygen Generation &amp; Carbon Sink):</strong><br>\n                During daylight hours, trillions of leaves in a forest absorb immense volumes of <strong>carbon dioxide (<span class=\"math\">CO₂</span>)</strong> from the atmosphere to synthesize glucose, releasing massive quantities of life-sustaining <strong>oxygen gas (<span class=\"math\">O₂</span>)</strong> into the air:<br>\n                <div class=\"math\">6CO₂ + 6H₂O + Solar Energy → C₆H₁₂O₆ + 6O₂</div>\n              </li>\n              <li><strong>Respiration:</strong><br>\n                All forest animals, micro-organisms, and plants inhale oxygen for cellular respiration and release carbon dioxide back into the atmosphere:<br>\n                <div class=\"math\">C₆H₁₂O₆ + 6O₂ → 6CO₂ + 6H₂O + Energy</div>\n              </li>\n              <li><strong>Net Ecological Balance:</strong><br>\n                Because the net oxygen produced during daytime photosynthesis far exceeds the oxygen consumed during respiration by forest organisms, the surplus oxygen is dispersed globally to sustain animal life across the planet, while excess carbon dioxide is locked away in forest biomass, preventing runaway global warming.\n              </li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of photosynthesis consuming CO₂ and liberating O₂</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of respiration and net dynamic atmospheric balance (\"green lungs\")</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q5 -->\n  <div class=\"q-card\" id=\"q12_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">Explain why there is no waste in a forest.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Answer: There is no waste in a forest because all biological by-products are naturally recycled within closed ecological food chains and cycles.</strong></p>\n          <div class=\"step\">\n            <strong>Key Reasons:</strong>\n            <ul>\n              <li><strong>Scavengers Consume Carrion:</strong> Scavengers (vultures, crows, jackals, hyenas) quickly consume dead animal carcasses.</li>\n              <li><strong>Decomposers Complete Mineralisation:</strong> Any remaining organic matter, fallen dry leaves, animal excreta, and decaying logs are attacked by millions of decomposers (fungi, bacteria, beetles, earthworms).</li>\n              <li><strong>Transformation into Humus:</strong> Decomposers break down these organic residues into <strong>humus</strong>, releasing base minerals and nitrogen back into the topsoil.</li>\n              <li><strong>Root Uptake:</strong> Plants immediately reabsorb these mineral nutrients through their root hairs to build new leaves, branches, and fruits.</li>\n              <li>Because everything produced is consumed and re-assimilated, the forest operates as a perfectly zero-waste circular ecosystem.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role of scavengers and decomposers</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Conversion into humus and re-absorption by plant roots (circular zero-waste loop)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q6 -->\n  <div class=\"q-card\" id=\"q12_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">List five products we get from forests.</div>\n      <div class=\"q-marks\">2.5 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Five important economic and domestic products obtained from forests include:</p>\n          <div class=\"step\">\n            <ol>\n              <li><strong>Timber and Firewood:</strong> High-grade structural wood (teak, sal, rosewood, deodar) used for furniture, buildings, boats, and paper pulp.</li>\n              <li><strong>Medicinal Herbs and Pharmaceuticals:</strong> Natural therapeutic plants (cinchona for quinine, neem, tulsi, amla, rauwolfia for blood pressure).</li>\n              <li><strong>Gums, Resins, and Turpentine:</strong> Industrial bonding agents, paints, varnishes, and aromatics extracted from tree bark.</li>\n              <li><strong>Honey and Wax:</strong> Wild forest honey harvested from wild honeybee hives, and natural beeswax used in cosmetics.</li>\n              <li><strong>Spices, Lac, and Catechu (Katha):</strong> Forest spices (cinnamon, cardamom), lac for sealing wax and bangles, and katha for betel leaves.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Any 5 distinct forest products listed (0.5 Mark × 5)</span><span class=\"marking-marks\">2.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q7 -->\n  <div class=\"q-card\" id=\"q12_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Fill in the blanks:<br>\n        (a) The insects, butterflies, honeybees and birds help flowering plants in ______.<br>\n        (b) A forest is a purifier of ______ and ______.<br>\n        (c) Herbs form the ______ layer in the forest.<br>\n        (d) The decaying leaves and animal droppings in a forest enrich the ______.\n      </div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>(a)</strong> The insects, butterflies, honeybees and birds help flowering plants in <strong>pollination</strong>.</p>\n          <p><strong>(b)</strong> A forest is a purifier of <strong>air</strong> and <strong>water</strong>.</p>\n          <p><strong>(c)</strong> Herbs form the <strong>lowest</strong> layer in the forest.</p>\n          <p><strong>(d)</strong> The decaying leaves and animal droppings in a forest enrich the <strong>soil with nutrients (or humus)</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct fill-in-the-blank (0.5 Mark × 4)</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q8 -->\n  <div class=\"q-card\" id=\"q12_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">Why should we worry about the conditions and issues related to forests far from us?</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Even if forests are located hundreds of kilometres away from our urban cities, their degradation directly impacts global planetary survival in the following ways:</p>\n          <div class=\"step\">\n            <ol>\n              <li><strong>Global Warming &amp; Climate Change:</strong> Forests act as planetary carbon sinks. Widespread deforestation releases stored carbon, increasing atmospheric <span class=\"math\">CO₂</span> concentrations and accelerating global global warming, unpredictable monsoon cycles, and melting polar glaciers.</li>\n              <li><strong>Oxygen Depletion:</strong> Large tropical forests (like the Amazon and Western Ghats) generate substantial shares of the world's oxygen. Their loss threatens breathable atmospheric oxygen quality.</li>\n              <li><strong>Disruption of Rainfall &amp; Water Cycles:</strong> Forests contribute massive volumes of water vapour to cloud formation through transpiration. Destroying forests leads to severe continental droughts, erratic rainfall, and shrinking rivers.</li>\n              <li><strong>Downstream Flooding &amp; Siltation:</strong> Deforested mountain watersheds allow unchecked torrents of rainwater to wash down fertile topsoil into distant urban rivers, causing catastrophic silt build-up, flash flooding, and drinking water shortages in faraway plains.</li>\n              <li><strong>Loss of Global Biodiversity:</strong> Over 80% of terrestrial wildlife lives in forests. Deforestation drives species to permanent extinction, destroying potential future sources of life-saving medical compounds.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Any 3 well-reasoned ecological connections (1 Mark each)</span><span class=\"marking-marks\">3 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q9 -->\n  <div class=\"q-card\" id=\"q12_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">Explain why there is a need of variety of animals and plants in a forest.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>A high variety of plants and animals (<strong>biodiversity</strong>) is essential for the ecological resilience, stability, and survival of a forest:</p>\n          <div class=\"step\">\n            <ol>\n              <li><strong>Interconnected Food Chains and Food Webs:</strong> Different herbivores feed on different species of plants (grasses, tender leaves, bark, fruits). A greater variety of herbivores provides abundant prey for diverse carnivores. This intricate food web ensures that no single species overpopulates or starves.</li>\n              <li><strong>Enhanced Nutrient Regeneration:</strong> A diverse mixture of tree species sheds varying types of foliage and produces complex roots, supporting diverse communities of soil microbes and decomposers that replenish a broader spectrum of soil minerals.</li>\n              <li><strong>Pest &amp; Disease Resistance:</strong> In a diverse forest, individual trees of the same species are separated by other species. This spatial separation prevents insect infestations and plant epidemics from spreading unchecked across the entire landscape.</li>\n              <li><strong>Habitat Stratification:</strong> Different animal species occupy distinct vertical zones (canopy, understorey, forest floor, underground burrows), enabling the forest to maximize energy utilization without lethal inter-species competition.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role of variety in maintaining complex food chains and webs</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Decomposition diversity and soil nutrient enrichment</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Pest resistance and ecological balance</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q10 -->\n  <div class=\"q-card\" id=\"q12_10\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_10')\">\n      <div class=\"q-num\">Q10</div>\n      <div class=\"q-text\">In Fig. 12.15, the artist has forgotten to put the labels and directions on the arrows. Mark the directions on the arrows and label the diagram using the following labels: clouds, rain, atmosphere, carbon dioxide, oxygen, plants, animals, soil, roots, water table.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Correct Arrow Directions &amp; Label Descriptions for Exam Schematics:</strong>\n            <ul>\n              <li><strong>Clouds &amp; Rain:</strong> Arrow pointing downwards from <strong>Clouds</strong> towards the forest trees and ground labelled <strong>Rain</strong>.</li>\n              <li><strong>Atmosphere:</strong> Surrounding air layer above the tree canopy.</li>\n              <li><strong>Carbon Dioxide (<span class=\"math\">CO₂</span>):</strong>\n                <br>• Arrow pointing <em>from atmosphere down into plants</em> (absorbed during photosynthesis).\n                <br>• Arrow pointing <em>from animals up into atmosphere</em> (released during respiration).\n              </li>\n              <li><strong>Oxygen (<span class=\"math\">O₂</span>):</strong>\n                <br>• Arrow pointing <em>from plants out into atmosphere</em> (released during photosynthesis).\n                <br>• Arrow pointing <em>from atmosphere towards animals</em> (inhaled for respiration).\n              </li>\n              <li><strong>Plants &amp; Roots:</strong> Green foliage labelled <strong>Plants</strong>, with subterranean branching networks penetrating the upper soil layer labelled <strong>Roots</strong>.</li>\n              <li><strong>Soil &amp; Water Table:</strong> The dark ground layer holding roots labelled <strong>Soil</strong>; a downward arrow showing percolation to the underground blue saturated layer labelled <strong>Water Table</strong>.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate arrow directions for gas exchange (CO₂ in, O₂ out)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate hydrological arrow directions (rain down, percolation to water table)</span><span class=\"marking-marks\">1.5 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q11 -->\n  <div class=\"q-card\" id=\"q12_11\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_11')\">\n      <div class=\"q-num\">Q11</div>\n      <div class=\"q-text\">Which of the following is not a forest product?<br>\n        (i) Gum<br>\n        (ii) Plywood<br>\n        (iii) Sealing wax<br>\n        (iv) Kerosene\n      </div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (iv) Kerosene</strong></p>\n          <div class=\"step\">\n            <strong>Scientific Reason:</strong>\n            <ul>\n              <li><strong>Gum</strong> is a direct natural exudate tapped from forest trees (such as acacia).</li>\n              <li><strong>Plywood</strong> is manufactured by gluing together thin veneers of forest timber.</li>\n              <li><strong>Sealing wax</strong> is derived from lac, a resinous secretion produced by tiny insects dwelling on forest host trees.</li>\n              <li><strong>Kerosene</strong> is a liquid hydrocarbon fuel obtained from the fractional distillation of underground <strong>crude petroleum</strong> (a fossil fuel), not a direct product harvested from forests.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Selection of (iv) Kerosene with petroleum distinction</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q12 -->\n  <div class=\"q-card\" id=\"q12_12\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_12')\">\n      <div class=\"q-num\">Q12</div>\n      <div class=\"q-text\">Which of the following statements is not correct?<br>\n        (i) Forests protect the soil from erosion.<br>\n        (ii) Plants and animals in a forest are not dependent on one another.<br>\n        (iii) Forests influence the climate and water cycle.<br>\n        (iv) Soil helps forests to grow and regenerate.\n      </div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Statement that is NOT correct: (ii) Plants and animals in a forest are not dependent on one another.</strong></p>\n          <div class=\"step\">\n            <strong>Scientific Justification:</strong>\n            Plants and animals in a forest are <strong>deeply interdependent</strong>:\n            <ul>\n              <li>Animals depend on plants for food, shelter, and atmospheric oxygen.</li>\n              <li>Plants depend on animals for pollination of flowers, dispersal of seeds, supply of carbon dioxide for photosynthesis, and manure from animal wastes to enrich soil.</li>\n              <li>Statements (i), (iii), and (iv) are all scientifically accurate ecological facts.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Identification of statement (ii) with symbiotic explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q13 -->\n  <div class=\"q-card\" id=\"q12_13\">\n    <div class=\"q-head\" onclick=\"toggleQ('q12_13')\">\n      <div class=\"q-num\">Q13</div>\n      <div class=\"q-text\">Micro-organisms act upon the dead plants to produce:<br>\n        (i) sand<br>\n        (ii) mushrooms<br>\n        (iii) humus<br>\n        (iv) wood\n      </div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (iii) humus</strong></p>\n          <p><em>Scientific Explanation:</em> Decomposer micro-organisms (bacteria and fungi) secrete digestive enzymes that biochemically decompose complex plant cellulose and lignin into a dark, amorphous, nutrient-rich organic compound called <strong>humus</strong>, which elevates the fertility and moisture-retention capacity of forest topsoil.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Selection of humus with biochemical decomposition explanation</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#059669;\">Case Study: Deforestation &amp; Flash Flood Catastrophe</div>\n        <div class=\"cbq-question\">\n          <strong>Environmental Disaster Case:</strong> A hill slopes district cleared 500 hectares of virgin mountain forest for an infrastructure project. During the following monsoon, an intense rainfall event of 180 mm in 24 hours caused massive landslides, wiped out roads, and caused catastrophic flash flooding in river valleys 80 km downstream.<br><br>\n          (i) What natural role of tree roots on the slope was lost due to deforestation?<br>\n          (ii) Why did rainwater rush down into the river so rapidly instead of recharging aquifers?<br>\n          (iii) How does the canopy of a forest protect the underlying soil from detachment?\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Loss of Soil Binding:</strong> Tree root systems act like biological reinforcing mesh that mechanically binds soil particles, prevents slope destabilization, and holds millions of tonnes of earth firmly against gravitational shear stress.</p>\n          <p><strong>(ii) Loss of Infiltration:</strong> Without the spongy forest floor (humus and leaf litter) to absorb water and facilitate gradual underground percolation, rain became immediate high-speed surface runoff, causing catastrophic downstream torrents.</p>\n          <p><strong>(iii) Canopy Shielding:</strong> An intact forest canopy absorbs the terminal velocity kinetic energy of large falling raindrops. Instead of forcefully impacting and dislodging topsoil particles (splash erosion), water gently drips down leaves and branches onto the ground.</p>\n        </div>\n      </div>\n\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">⚡ Assertion &amp; Reason (HOTS)</div>\n        <div class=\"cbq-question\">\n          <strong>Assertion (A):</strong> Despite huge quantities of fallen leaves, dead animals, and droppings, a virgin forest floor never accumulates waste.<br>\n          <strong>Reason (R):</strong> Decomposers (bacteria and fungi) convert all dead organic matter into fertile dark humus, which is rapidly recycled back into growing plants.<br><br>\n          Choose the correct option:<br>\n          (a) Both A and R are true, and R is the correct explanation of A.<br>\n          (b) Both A and R are true, but R is not the correct explanation of A.<br>\n          (c) A is true, but R is false.<br>\n          (d) A is false, but R is true.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>Answer: (a) Both A and R are true, and R is the correct explanation of A.</strong></p>\n          <p><em>Scientific Explanation:</em> Natural ecosystems operate on a perfect circular bio-economy. Microscopic decomposers and macro-scavengers recycle every gram of biomass into chemical nutrients, ensuring that nature generates zero waste.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(11)\">← Chapter 11: Light</button>\n    <button class=\"ch-nav-btn next\" onclick=\"showChapter(13)\">Chapter 13: Wastewater Story →</button>\n  </div>\n</section>\n","13":"<section class=\"chapter-section\" id=\"ch13\">\n  <div class=\"chapter-header\">\n    <div class=\"ch-badge\">13</div>\n    <div class=\"chapter-header-info\">\n      <h2>Chapter 13: Wastewater Story</h2>\n      <p>NCERT Exercise Solutions — Complete Step-by-Step Answers with CBSE Marking Scheme 2026-27</p>\n    </div>\n  </div>\n\n  <div class=\"concept-card\">\n    <div class=\"concept-header\">📌 Key Scientific Concepts &amp; Wastewater Treatment Plant (WWTP)</div>\n    <ul class=\"concept-list\">\n      <li><strong>Sewage &amp; Contaminants:</strong>\n        <ul>\n          <li><strong>Sewage:</strong> Liquid waste containing dissolved and suspended impurities called <strong>contaminants</strong>.</li>\n          <li><em>Organic Impurities:</em> Human excreta, animal waste, oil, urea, pesticides, herbicides, fruit/vegetable waste.</li>\n          <li><em>Inorganic Impurities:</em> Nitrates, phosphates, heavy metals.</li>\n          <li><em>Nutrients:</em> Phosphorus and Nitrogen.</li>\n          <li><em>Bacteria &amp; Microbes:</em> Pathogens causing cholera (<em>Vibrio cholerae</em>), typhoid (<em>Salmonella typhi</em>), dysentery, and hepatitis.</li>\n        </ul>\n      </li>\n      <li><strong>Wastewater Treatment Plant (WWTP) Stages:</strong>\n        <ul>\n          <li><strong>Physical Stage:</strong>\n            <ol>\n              <li><em>Bar Screens:</em> Screen out large floating debris like plastic bottles, rags, cans, sticks, and napkins.</li>\n              <li><em>Grit &amp; Sand Removal Tank:</em> Wastewater flows slowly, allowing heavy sand, grit, and pebbles to settle down by gravity.</li>\n              <li><em>Clarifier / Sedimentation Tank:</em> Suspended solid faeces settle at the bottom as <strong>sludge</strong> (scraped off); lighter grease and oils float to the top and are removed by a <strong>skimmer</strong>. The output is <em>clarified water</em>.</li>\n            </ol>\n          </li>\n          <li><strong>Biological Stage:</strong>\n            <em>Aeration Tank:</em> Air is continuously pumped into clarified water to encourage the rapid growth of <strong>aerobic bacteria</strong>. These microbes consume remaining human waste, food particles, soaps, and organic impurities.</li>\n          <li><strong>Disinfection Stage:</strong>\n            Treated water is disinfected using chemical agents like <strong>Chlorine</strong> or <strong>Ozone (<span class=\"math\">O₃</span>)</strong> or ultraviolet light before being safely discharged into natural rivers or the ocean.</li>\n        </ul>\n      </li>\n      <li><strong>Sludge &amp; Biogas Utilization:</strong> Sludge from the clarifier is transferred to an anaerobic digester where anaerobic bacteria digest it, generating combustible <strong>biogas</strong> (used for electricity/cooking fuel). The remaining dried sludge forms nutrient-rich organic <strong>manure</strong>.</li>\n    </ul>\n  </div>\n\n  <div class=\"ex-div\">NCERT Textbook Exercise Questions</div>\n\n  <!-- Q1 -->\n  <div class=\"q-card\" id=\"q13_1\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_1')\">\n      <div class=\"q-num\">Q1</div>\n      <div class=\"q-text\">Fill in the blanks:<br>\n        (a) Cleaning of water is a process of removing ______.<br>\n        (b) Wastewater released by houses is called ______.<br>\n        (c) Dried ______ is used as manure.<br>\n        (d) Drains get blocked by ______ and ______.\n      </div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>(a)</strong> Cleaning of water is a process of removing <strong>pollutants (or contaminants)</strong>.</p>\n          <p><strong>(b)</strong> Wastewater released by houses is called <strong>sewage</strong>.</p>\n          <p><strong>(c)</strong> Dried <strong>sludge</strong> is used as manure.</p>\n          <p><strong>(d)</strong> Drains get blocked by <strong>cooking oil (fats)</strong> and <strong>solid food remains (or plastics)</strong>.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each blank accurately filled (0.5 Mark × 4)</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q2 -->\n  <div class=\"q-card\" id=\"q13_2\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_2')\">\n      <div class=\"q-num\">Q2</div>\n      <div class=\"q-text\">What is sewage? Explain why it is harmful to discharge untreated sewage into rivers or seas.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. Definition of Sewage:</strong><br>\n            <strong>Sewage</strong> is wastewater carried away by a drainage network of sewers from homes, industries, agricultural fields, and public institutions. It is a complex liquid suspension containing dissolved organic and inorganic impurities, nutrients, toxic chemicals, and disease-causing microbes.\n          </div>\n          <div class=\"step\">\n            <strong>2. Hazards of Discharging Untreated Sewage into Water Bodies:</strong>\n            <ul>\n              <li><strong>Outbreak of Waterborne Diseases:</strong> Untreated sewage contains dangerous pathogens that contaminate drinking water sources, sparking deadly epidemics of cholera, typhoid, jaundice (hepatitis), dysentery, and polio.</li>\n              <li><strong>Severe Aquatic Oxygen Depletion (Eutrophication):</strong> Aerobic micro-organisms rapidly decompose organic wastes in sewage, consuming dissolved oxygen (<span class=\"math\">DO</span>). As oxygen plunges to near-zero levels, fish, crabs, and other aquatic life suffocate and die en masse.</li>\n              <li><strong>Destruction of Aquatic Ecosystems:</strong> Toxic household detergents, industrial chemicals, and heavy metals bioaccumulate in marine life, devastating coral reefs and marine food webs.</li>\n              <li><strong>Foul Odour &amp; Environmental Degradation:</strong> Unchecked anaerobic decomposition emits toxic hydrogen sulphide (<span class=\"math\">H₂S</span>) and methane gases, making water bodies putrid, uninhabitable eyesores.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Precise definition of sewage</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Explanation of waterborne epidemics and oxygen depletion in aquatic life</span><span class=\"marking-marks\">2 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q3 -->\n  <div class=\"q-card\" id=\"q13_3\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_3')\">\n      <div class=\"q-num\">Q3</div>\n      <div class=\"q-text\">Why should oils and fats not be released in the drain? Explain.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Cooking oils, fats, and grease should <strong>never</strong> be poured down kitchen sinks or household drains for two major reasons:</p>\n          <div class=\"step\">\n            <ol>\n              <li><strong>Clogging of Drainage Pipes:</strong> As liquid oils and melted butter flow through cold underground plumbing pipes, they cool down and solidify into thick, sticky fat deposits. These deposits trap dirt and other debris, narrowing the pipe diameter and eventually causing complete, foul blockage of household drains.</li>\n              <li><strong>Choking of Open Soil Pores:</strong> In open drains and soil seepage channels, oily residues coat the soil particles, clogging natural microscopic soil pores. This prevents normal water percolation and suffocates the soil's natural capacity to filter wastewater.</li>\n            </ol>\n          </div>\n          <p><em>Eco-friendly Disposal:</em> Used cooking oil and solid grease should always be discarded into the solid garbage dustbin.</p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Solidification and blocking of drainage pipes</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Clogging of soil pores reducing water filtration</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q4 -->\n  <div class=\"q-card\" id=\"q13_4\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_4')\">\n      <div class=\"q-num\">Q4</div>\n      <div class=\"q-text\">Describe the steps involved in getting clarified water from wastewater.</div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>At a Wastewater Treatment Plant (WWTP), raw sewage is transformed into clarified water through the following sequential physical and biological stages:</p>\n          <div class=\"step\">\n            <strong>Stage 1: Filtration through Bar Screens:</strong><br>\n            Wastewater first flows through large vertical <strong>bar screens</strong>. These screens intercept and strain out large floating physical debris such as plastic rags, polythene bags, sticks, cans, sanitary napkins, and pebbles.\n          </div>\n          <div class=\"step\">\n            <strong>Stage 2: Grit and Sand Removal Chamber:</strong><br>\n            The water then passes through a grit and sand removal tank where the incoming flow velocity is deliberately slowed down. Heavy inorganic particles like coarse sand, gravel, and grit settle to the tank bottom by gravity and are mechanically removed.\n          </div>\n          <div class=\"step\">\n            <strong>Stage 3: Primary Sedimentation (Clarifier Tank):</strong><br>\n            The water is channeled into a large sedimentation tank sloped downwards towards the centre. The water remains undisturbed for several hours:\n            <ul>\n              <li>Heavy solid organic wastes (human faeces) settle at the bottom as <strong>sludge</strong> and are removed by a bottom mechanical scraper.</li>\n              <li>Light, floatable impurities such as oils and grease rise to the surface and are removed by a surface <strong>skimmer</strong>.</li>\n            </ul>\n            The remaining liquid separated from sludge and scum is called <strong>clarified water</strong>.\n          </div>\n          <div class=\"step\">\n            <strong>Stage 4: Aeration &amp; Biological Purification:</strong><br>\n            Air is continuously pumped into the clarified water inside a massive <strong>aeration tank</strong>. The abundant oxygen triggers explosive growth of harmless <strong>aerobic bacteria</strong>, which consume residual dissolved organic impurities, food remnants, and soaps. After aeration, the microbes settle down as activated sludge, leaving clear, purified water ready for chemical disinfection.\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stage 1: Bar screen coarse filtration</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stage 2: Grit and sand chamber settling</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stage 3: Primary sedimentation tank (sludge scraper + oil skimmer)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Stage 4: Aeration tank aerobic bacterial breakdown</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q5 -->\n  <div class=\"q-card\" id=\"q13_5\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_5')\">\n      <div class=\"q-num\">Q5</div>\n      <div class=\"q-text\">What is sludge? Explain how it is treated.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>1. Definition of Sludge:</strong><br>\n            <strong>Sludge</strong> is the solid, semi-liquid organic matter (primarily settled human faecal matter and particulate debris) that sinks and accumulates at the bottom of the primary sedimentation/clarifier tank during wastewater treatment.\n          </div>\n          <div class=\"step\">\n            <strong>2. Treatment of Sludge:</strong>\n            <ol>\n              <li><strong>Transfer to Anaerobic Digester:</strong> Sludge is continuously collected by mechanical scrapers and pumped into a sealed, oxygen-free chamber called an <strong>anaerobic digester</strong>.</li>\n              <li><strong>Anaerobic Digestion:</strong> Specialized anaerobic bacteria decompose the complex organic compounds in the sludge in the absence of oxygen.</li>\n              <li><strong>Biogas Production:</strong> This digestion process generates combustible <strong>biogas</strong> (a mixture of methane and carbon dioxide), which is captured and burned to generate electricity or used as fuel to power the treatment plant.</li>\n              <li><strong>Conversion to Organic Manure:</strong> After complete digestion, the remaining stabilized sludge is dehydrated on large sand drying beds. The dried solids yield an odorless, nutrient-rich organic <strong>manure</strong> that enriches agricultural soil.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Definition of sludge as settled solid faecal matter</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Anaerobic decomposition producing biogas fuel</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Drying of digested residue into valuable agricultural manure</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q6 -->\n  <div class=\"q-card\" id=\"q13_6\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_6')\">\n      <div class=\"q-num\">Q6</div>\n      <div class=\"q-text\">Explain why untamed human excreta is a health hazard.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Untreated human excreta is a critical biological hazard for the following reasons:</p>\n          <div class=\"step\">\n            <ol>\n              <li><strong>Severe Water Pollution:</strong> In open defecation areas, rain washes human faeces into nearby rivers, canals, ponds, and open wells. Furthermore, pathogens seep through porous soil into shallow aquifers, contaminating the groundwater that rural communities rely on for drinking and cooking.</li>\n              <li><strong>Transmission of Fatal Waterborne Diseases:</strong> A single gram of human faeces can contain millions of viruses, bacteria, and parasitic cysts. It is the primary vector for lethal waterborne epidemics, including:\n                <ul>\n                  <li><strong>Cholera</strong> (caused by <em>Vibrio cholerae</em>)</li>\n                  <li><strong>Typhoid</strong> (caused by <em>Salmonella typhi</em>)</li>\n                  <li><strong>Dysentery &amp; Diarrhoea</strong></li>\n                  <li><strong>Hepatitis A &amp; Polio</strong></li>\n                </ul>\n              </li>\n              <li><strong>Vector Attraction (Houseflies &amp; Pests):</strong> Exposed faecal mounds attract houseflies and cockroaches, which pick up microbial pathogens on their hairy legs and transfer them directly onto exposed human food, spreading infection.</li>\n              <li><strong>Soil Pollution &amp; Worm Infections:</strong> Soil contaminated with faecal matter contains parasitic roundworm and hookworm eggs that penetrate barefoot walkers, causing chronic anaemia and malnutrition in children.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Contamination of surface and groundwater resources</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Spread of waterborne pathogens (cholera, typhoid, hepatitis)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Role of insect vectors and hookworm/parasitic infections</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q7 -->\n  <div class=\"q-card\" id=\"q13_7\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_7')\">\n      <div class=\"q-num\">Q7</div>\n      <div class=\"q-text\">Name two chemicals used to disinfect water.</div>\n      <div class=\"q-marks\">1 Mark</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>Two chemicals widely used to disinfect water and destroy dangerous microscopic pathogens are:</p>\n          <div class=\"step\">\n            <strong>1. Chlorine</strong> (added as chlorine gas, liquid sodium hypochlorite, or bleaching powder).<br>\n            <strong>2. Ozone (<span class=\"math\">O₃</span>)</strong> (a powerful oxidant that sterilizes water without leaving residual chemical taste).\n          </div>\n          <p><em>(Note: Ultraviolet (UV) radiation is also widely used as a physical disinfecting agent).</em></p>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Chlorine and Ozone correctly named (0.5 Mark each)</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q8 -->\n  <div class=\"q-card\" id=\"q13_8\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_8')\">\n      <div class=\"q-num\">Q8</div>\n      <div class=\"q-text\">Explain the function of bar screens in a wastewater treatment plant.</div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <div class=\"step\">\n            <strong>Function of Bar Screens:</strong>\n            <ul>\n              <li><strong>Physical Coarse Filtration:</strong> Bar screens act as the very first primary mechanical barrier at the entry point of a wastewater treatment plant.</li>\n              <li><strong>Interception of Bulky Objects:</strong> As raw sewage flows through the grid of parallel vertical metal bars, all large, floating physical debris — such as plastic polythene bags, fabric rags, empty cans, plastic bottles, sticks, and sanitary items — are physically caught and strained out.</li>\n              <li><strong>Protection of Downstream Equipment:</strong> By filtering out these large solids, bar screens prevent catastrophic clogging and damage to expensive high-pressure wastewater pumps, pipes, valves, and mechanical clarifier scrapers deeper within the facility.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Screening out large solid floating debris (plastics, rags, cans)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Protecting pumps and mechanical machinery from clogging and wear</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q9 -->\n  <div class=\"q-card\" id=\"q13_9\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_9')\">\n      <div class=\"q-num\">Q9</div>\n      <div class=\"q-text\">Explain the relationship between sanitation and disease.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Sanitation and human health share a direct, inverse relationship: poor sanitation breeds disease, whereas robust sanitation protects public health.</strong></p>\n          <div class=\"step\">\n            <strong>Key Mechanisms:</strong>\n            <ol>\n              <li><strong>Breeding Ground for Pathogens:</strong> Poor sanitation — such as open defecation, overflowing unsealed sewers, stagnant wastewater, and accumulated garbage — provides the ideal breeding environment for disease-causing bacteria, viruses, and parasites.</li>\n              <li><strong>Vector Proliferation:</strong> Stagnant wastewater puddles serve as breeding grounds for mosquitoes (transmitting malaria, dengue, and chikungunya), while open excreta attracts houseflies that transfer microbes onto food.</li>\n              <li><strong>Contamination of Drinking Supplies:</strong> In areas with inadequate sanitation, untreated sewage leaches into shallow water tables and pipelines, triggering outbreaks of fatal waterborne illnesses like cholera, dysentery, and typhoid.</li>\n              <li><strong>Sanitation Breaks the Chain of Infection:</strong> Proper sanitation — including sanitary toilets, underground closed sewage systems, clean drinking water, and hygienic handwashing — breaks the faecal-oral transmission route, eradicating infectious diseases and saving millions of children's lives annually.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Direct relationship: Poor sanitation causes infectious diseases</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Contamination pathways via vectors and contaminated water</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Proper sanitation breaking the transmission cycle</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q10 -->\n  <div class=\"q-card\" id=\"q13_10\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_10')\">\n      <div class=\"q-num\">Q10</div>\n      <div class=\"q-text\">Outline your role as an active citizen in relation to sanitation.</div>\n      <div class=\"q-marks\">3 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p>As a responsible and proactive citizen, one should maintain civic hygiene and sanitation through the following concrete actions:</p>\n          <div class=\"step\">\n            <ol>\n              <li><strong>Responsible Household Waste Disposal:</strong> Never pour cooking oils, paints, grease, medicines, or chemicals down household sinks. Dispose of solid tea leaves, cotton, food scraps, and plastic wrappers in designated dry/wet dustbins rather than drains.</li>\n              <li><strong>Reporting Open Sewer Hazards:</strong> If an open sewer, choked manhole, or broken municipal water pipe is spotted in the neighbourhood, immediately alert the local municipal corporation or Gram Panchayat to avert disease outbreaks.</li>\n              <li><strong>Eradicating Open Defecation:</strong> Promote and use sanitary closed toilets; advocate against open defecation and urination in open public spaces.</li>\n              <li><strong>Community Cleanliness Campaigns:</strong> Actively participate in neighbourhood sanitation drives (like the Swachh Bharat Abhiyan), ensuring stagnant rainwater puddles are sprayed or drained to curb mosquito breeding.</li>\n              <li><strong>Spreading Awareness:</strong> Educate family, neighbours, and community workers about proper hand hygiene, water purification, and the health benefits of covered sewage networks.</li>\n            </ol>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Proper domestic disposal habits (no oils/solids down the drain)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Civic reporting of leaks/choked manholes to municipal authorities</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Promoting community toilet use and hygiene education</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q11 -->\n  <div class=\"q-card\" id=\"q13_11\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_11')\">\n      <div class=\"q-num\">Q11</div>\n      <div class=\"q-text\">Solve the NCERT Crossword Puzzle on Wastewater Treatment terms:<br>\n        <strong>Across Clues:</strong><br>\n        3. Liquid waste products.<br>\n        4. Solid waste extracted in sewage treatment.<br>\n        6. A word related to hygiene.<br>\n        8. Waste matter discharged from human body.<br>\n        <strong>Down Clues:</strong><br>\n        1. Used water.<br>\n        2. A pipe carrying sewage.<br>\n        5. Micro-organisms which cause cholera.<br>\n        7. A chemical to disinfect water.\n      </div>\n      <div class=\"q-marks\">4 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <table class=\"data-table\">\n            <thead>\n              <tr><th>Direction &amp; Clue Number</th><th>Clue Description</th><th>Crossword Solution Word</th></tr>\n            </thead>\n            <tbody>\n              <tr><td><strong>Across 3</strong></td><td>Liquid waste products</td><td><strong>SEWAGE</strong></td></tr>\n              <tr><td><strong>Across 4</strong></td><td>Solid waste extracted in sewage treatment</td><td><strong>SLUDGE</strong></td></tr>\n              <tr><td><strong>Across 6</strong></td><td>A word related to hygiene</td><td><strong>SANITATION</strong></td></tr>\n              <tr><td><strong>Across 8</strong></td><td>Waste matter discharged from human body</td><td><strong>EXCRETA</strong></td></tr>\n              <tr><td><strong>Down 1</strong></td><td>Used water</td><td><strong>WASTEWATER</strong></td></tr>\n              <tr><td><strong>Down 2</strong></td><td>A pipe carrying sewage</td><td><strong>SEWER</strong></td></tr>\n              <tr><td><strong>Down 5</strong></td><td>Micro-organisms which cause cholera</td><td><strong>BACTERIA</strong></td></tr>\n              <tr><td><strong>Down 7</strong></td><td>A chemical to disinfect water</td><td><strong>OZONE</strong> (or <strong>CHLORINE</strong>)</td></tr>\n            </tbody>\n          </table>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Each correct crossword term accurately mapped (0.5 Mark × 8)</span><span class=\"marking-marks\">4 Marks</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- Q12 -->\n  <div class=\"q-card\" id=\"q13_12\">\n    <div class=\"q-head\" onclick=\"toggleQ('q13_12')\">\n      <div class=\"q-num\">Q12</div>\n      <div class=\"q-text\">Study the following statements about ozone:<br>\n        (a) It is essential for breathing of living organisms.<br>\n        (b) It is used to disinfect water.<br>\n        (c) It absorbs ultraviolet rays.<br>\n        (d) Its proportion in air is about 3%.<br>\n        Which of these statements are correct?<br>\n        (i) (a), (b) and (c)<br>\n        (ii) (b) and (c)<br>\n        (iii) (a) and (d)<br>\n        (iv) All four\n      </div>\n      <div class=\"q-marks\">2 Marks</div>\n      <div class=\"q-toggle\"><svg viewBox=\"0 0 24 24\" fill=\"none\" stroke=\"currentColor\" stroke-width=\"2.5\"><line x1=\"12\" y1=\"5\" x2=\"12\" y2=\"19\"/><line x1=\"5\" y1=\"12\" x2=\"19\" y2=\"12\"/></svg></div>\n    </div>\n    <div class=\"q-answer\">\n      <div class=\"answer-box\">\n        <div class=\"answer-label\">✅ CBSE Standard Answer</div>\n        <div class=\"answer-text\">\n          <p><strong>Correct Option: (ii) (b) and (c)</strong></p>\n          <div class=\"step\">\n            <strong>Scientific Evaluation of Each Statement:</strong>\n            <ul>\n              <li><strong>(a) Incorrect:</strong> Oxygen (<span class=\"math\">O₂</span>), not ozone (<span class=\"math\">O₃</span>), is essential for cellular respiration. Ozone is actually toxic and irritating to animal lungs if inhaled in significant quantities.</li>\n              <li><strong>(b) Correct:</strong> Ozone is a potent germicide and powerful oxidizing agent used in municipal waterworks to disinfect and sterilize water.</li>\n              <li><strong>(c) Correct:</strong> The stratospheric ozone layer shields Earth's biosphere by absorbing harmful ultraviolet (<span class=\"math\">UV-B</span>) solar radiation.</li>\n              <li><strong>(d) Incorrect:</strong> Ozone is a trace gas making up less than 0.00006% of Earth's atmosphere, nowhere near 3%.</li>\n            </ul>\n          </div>\n        </div>\n        <div class=\"marking-scheme\">\n          <div class=\"marking-title\">CBSE Marking Scheme 2026-27</div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Correct option selection: (ii) (b) and (c)</span><span class=\"marking-marks\">1 Mark</span></div>\n          <div class=\"marking-row\"><span class=\"marking-key\">Accurate scientific justification of correct and incorrect statements</span><span class=\"marking-marks\">1 Mark</span></div>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <!-- CBQ SECTION -->\n  <div class=\"cbq-section\">\n    <div class=\"cbq-header\">\n      <span>🎯 Competency-Based Questions (CBQ) &amp; HOTS</span>\n      <span class=\"cbq-badge\">CBSE Board Exam Pattern</span>\n    </div>\n    <div class=\"cbq-body\">\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#059669;\">Case Study: Vermi-Processing Toilets &amp; Low-Cost On-Site Sanitation</div>\n        <div class=\"cbq-question\">\n          <strong>Biotechnology in Sanitation:</strong> In a remote rural village without underground sewerage infrastructure, an NGO introduced vermi-processing toilets. Human excreta is collected in a pit populated by red earthworms (tiger worms).<br><br>\n          (i) What do the earthworms convert human excreta into?<br>\n          (ii) Why are vermi-processing toilets considered ideal for rural communities with low water availability?<br>\n          (iii) Name another traditional on-site sewage disposal system commonly used for isolated rural homes.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>(i) Bio-conversion:</strong> Red worms ingest and thoroughly decompose human faeces, transforming pathogenic excreta into high-grade, pathogen-free <strong>vermicompost</strong> (vermi-cakes), which serves as nutrient-dense organic fertilizer for crops.</p>\n          <p><strong>(ii) Advantages:</strong>\n            <br>• <em>Low Water Requirement:</em> Requires minimal flushing water compared to standard cistern toilets.\n            <br>• <em>Simple &amp; Zero Odour:</em> Operates naturally without noxious odours, complex machinery, or expensive electrical connections.\n            <br>• <em>Resource Recovery:</em> Directly converts hazardous waste into economic fertilizer right at the site.\n          </p>\n          <p><strong>(iii) Other On-site Systems:</strong> <strong>Septic tanks</strong>, biogas composting pits, and chemical toilets.</p>\n        </div>\n      </div>\n\n      <div class=\"cbq-card\">\n        <div class=\"cbq-type\" style=\"color:#0284c7;\">⚡ Assertion &amp; Reason (HOTS)</div>\n        <div class=\"cbq-question\">\n          <strong>Assertion (A):</strong> Cooking oils and solid food wastes should never be flushed down kitchen sinks into domestic drainage pipes.<br>\n          <strong>Reason (R):</strong> Fats and oils solidify inside cold plumbing conduits, trapping food scraps and causing stubborn drain blockages, while choking soil filtration pores in open drains.<br><br>\n          Choose the correct option:<br>\n          (a) Both A and R are true, and R is the correct explanation of A.<br>\n          (b) Both A and R are true, but R is not the correct explanation of A.<br>\n          (c) A is true, but R is false.<br>\n          (d) A is false, but R is true.\n        </div>\n        <button class=\"cbq-show-btn\" onclick=\"toggleCBQ(this)\">▶ Show Answer</button>\n        <div class=\"cbq-answer\">\n          <p><strong>Answer: (a) Both A and R are true, and R is the correct explanation of A.</strong></p>\n          <p><em>Scientific Explanation:</em> Greasy hydrophobic lipids adhere to the walls of drainage pipes and harden as temperature drops, drastically constricting water flow. Discarding oils into solid waste receptacles preserves sewer line integrity.</p>\n        </div>\n      </div>\n    </div>\n  </div>\n\n  <div class=\"ch-nav-btns\">\n    <button class=\"ch-nav-btn\" onclick=\"showChapter(12)\">← Chapter 12: Forests: Our Lifeline</button>\n    <button class=\"ch-nav-btn next\" onclick=\"window.scrollTo({top: 0, behavior: 'smooth'})\">Back to Top ↑</button>\n  </div>\n</section>\n"};
